const a={id:"s04",unidad:1,semana:4,kind:"aprendizaje",temaGenerador:"Crecer, cuidarnos y participar",title:"Crecer, cuidarnos y participar",subtitle:"Cambios del cuerpo, cuidado ético, información confiable, liderazgo y participación",icon:"HeartHandshake",color:"var(--area-cnt)",contexto:"Crecer trae cambios corporales, preguntas y nuevas responsabilidades. Esta semana estudiarás la pubertad y el aparato reproductor con lenguaje científico y respetuoso, distinguirás información confiable de rumores y reconocerás cuándo conviene conversar con una persona adulta de confianza o un profesional de salud, sin intentar diagnosticar. También practicarás liderazgos que escuchan, informan y hacen participar; usarás el teatro, la voz, la música y otros saberes para comunicar cuidado. Cada cuerpo cambia a su ritmo: la variación es normal y ninguna diferencia justifica burlas, vergüenza o estereotipos.",ejes:["vida-familiar","equidad","vida-ciudadana","seguridad"],media:{id:"s04-portada",kind:"image",title:"Crecer con información y apoyo",aspect:"16:9",alt:"Estudiantes diversos preparan una campaña escolar con un guion, un cartel de fuentes confiables y una lista de acuerdos de respeto.",brief:'Ilustración educativa luminosa de estudiantes guatemaltecos diversos preparando una campaña en un aula. En la mesa hay un guion teatral, tarjetas con los rótulos "familia", "docente" y "centro de salud", una lista de acuerdos de respeto y materiales de arte. Una docente acompaña sin dominar la actividad. Ropa completa, posturas naturales, sin representar cambios corporales de forma exagerada ni estereotipada, sin marcas. Dimensiones: 1600x900. Accesibilidad: contraste alto, rotulos grandes y legibles; la descripcion visual debe corresponder exactamente al texto alternativo.'},badge:{id:"medalla-s04",name:"Comunicador del cuidado",icon:"HeartHandshake",desc:"Completaste la semana 4 y superaste su reto"},bank:[{fase:"comprobar",areas:["mat"],cnb:["mat:1.3.4"],prompt:"Una pirámide decagonal tiene una base de diez lados. ¿Cuántas caras tiene en total?",type:"number-input",props:{answer:11,unit:"caras"},id:"s04-banco-1"},{fase:"comprobar",areas:["l1"],cnb:["l1:5.1.8"],prompt:"Clasifica cada línea de una escena informativa.",type:"sort",props:{buckets:[{id:"d",label:"Diálogo",icon:"MessageCircle"},{id:"a",label:"Acotación",icon:"Drama"}],items:[{id:"x",text:"JORGE: Podemos consultar el libro de Ciencias.",bucket:"d"},{id:"y",text:"(Se sientan en círculo y escuchan.)",bucket:"a"}]},id:"s04-banco-2"},{fase:"comprobar",areas:["cnt"],cnb:["cnt:3.5.1"],prompt:"Una estudiante evita compartir materiales con una persona que vive con VIH. ¿Qué respuesta aplica información científica y respeto?",type:"choice",props:{options:[{id:"a",text:"Pueden estudiar juntas: compartir pupitre y materiales no transmite VIH"},{id:"b",text:"Debe mantener distancia porque toda convivencia transmite el virus"},{id:"c",text:"La apariencia de una persona indica si puede participar"}],correct:["a"]},id:"s04-banco-3"},{fase:"comprobar",areas:["ccss"],cnb:["ccss:5.1.4"],prompt:"¿Qué pregunta se puede investigar con observaciones o entrevistas en la comunidad?",type:"choice",props:{options:[{id:"a",text:"¿Cómo participan las familias en las reuniones del barrio?"},{id:"b",text:"¿Cuál es el mejor color del mundo?"},{id:"c",text:"¿Qué pensará cada persona dentro de veinte años?"}],correct:["a"]},id:"s04-banco-4"},{fase:"comprobar",areas:["l2"],cnb:["l2:2.2.2"],prompt:"Al recitar “abro los brazos para recibir ayuda”, ¿qué gesto corresponde al significado?",type:"choice",props:{options:[{id:"a",text:"Abrir los brazos al decir “abro”"},{id:"b",text:"Dar la espalda y taparse la cara"},{id:"c",text:"Mover los pies sin relación con el verso"}],correct:["a"]},id:"s04-banco-5"},{fase:"comprobar",areas:["l3"],cnb:["l3:2.2.1"],prompt:"Choose the correct word: “I have ___ pencils: one for me and one for you.”",type:"choice",props:{options:[{id:"a",text:"two"},{id:"b",text:"to"},{id:"c",text:"too"}],correct:["a"]},id:"s04-banco-6"},{fase:"comprobar",areas:["fc"],cnb:["fc:3.1.1"],prompt:"Clasifica la evidencia sobre el consejo estudiantil.",type:"sort",props:{buckets:[{id:"d",label:"Gestión democrática",icon:"Vote"},{id:"a",label:"Gestión autoritaria",icon:"Gavel"}],items:[{id:"x",text:"Publica el presupuesto y recibe preguntas",bucket:"d"},{id:"y",text:"Cambia las reglas para impedir nuevas candidaturas",bucket:"a"}]},id:"s04-banco-7"},{fase:"comprobar",areas:["art"],cnb:["art:3.1.2"],prompt:"¿Qué reseña musical expresa una valoración con razones?",type:"choice",props:{options:[{id:"a",text:"La elegiría: su tempo moderado deja oír el diálogo y su letra habla de apoyo"},{id:"b",text:"Es la mejor porque sí"},{id:"c",text:"Es mala porque no está de moda"}],correct:["a"]},id:"s04-banco-8"},{fase:"comprobar",areas:["ef"],cnb:["ef:2.1.3"],prompt:"¿Qué distingue una ejecución en suspensión de una ejecución directa por arriba del hombro?",type:"choice",props:{options:[{id:"a",text:"Los pies se separan momentáneamente del suelo antes de soltar el implemento"},{id:"b",text:"El implemento avanza siempre pegado al suelo"},{id:"c",text:"Se elimina el movimiento del tronco y de las piernas"}],correct:["a"]},id:"s04-banco-9"},{fase:"comprobar",areas:["pyd"],cnb:["pyd:2.5.3"],prompt:"Un suelo deja escapar el agua muy rápido. ¿Qué descripción corresponde?",type:"choice",props:{options:[{id:"a",text:"Es arenoso y puede necesitar riego más frecuente"},{id:"b",text:"Es arcilloso y siempre queda encharcado"},{id:"c",text:"El tipo de suelo no influye en la producción"}],correct:["a"]},id:"s04-banco-10"}]},e=JSON.parse('[{"missionId":"s04","version":"cnb-sexto-5d2cf06fbf670d12","lesson":{"id":"s04-cnt-1","title":"Estructura del aparato reproductor masculino","icon":"ScanLine","minutes":14,"gancho":"Una ruta anatomica se comprende al relacionar cada estructura con su funcion.","objetivos":["Explicar la estructura del aparato reproductor masculino mediante la ubicacion, funcion y recorrido de sus partes"],"resumen":["Los testiculos forman espermatozoides.","El epididimo los almacena temporalmente y el conducto deferente los transporta.","Las vesiculas seminales y la prostata aportan liquidos; la uretra atraviesa el pene y conduce el semen al exterior."],"media":{"id":"s04-cnt-1-estructura","kind":"diagram","title":"Aparato reproductor masculino","aspect":"4:3","alt":"Diagrama anatomico esquematico y no explicito con las estructuras internas rotuladas.","brief":"Diagrama anatomico educativo 1200x900, vista lateral esquematica y no explicita. Rotular testiculos, epididimo, conducto deferente, vesiculas seminales, prostata, uretra y pene; usar flechas para el recorrido sin representar actividad sexual. Texto grande, alto contraste, patron ademas de color y descripcion lineal accesible."},"steps":[{"fase":"explorar","areas":["cnt"],"cnb":["cnt:3.1.1"],"prompt":"Relaciona la estructura, funcion y recorrido de testiculos, epididimo, conducto deferente, vesiculas seminales, prostata, uretra y pene.","type":"explain","props":{"icon":"Route","body":"La anatomia se estudia con lenguaje cientifico: cada parte tiene una ubicacion y una funcion dentro de un recorrido."},"id":"s04-cnt-1-1"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:3.1.1"],"title":"Partes y funciones","prompt":"Ubica y explica testiculos, epididimo, conducto deferente, vesiculas seminales, prostata, uretra y pene.","type":"explain","props":{"icon":"ListTree","body":"**Testiculos:** forman espermatozoides. **Epididimo:** maduracion y almacenamiento temporal. **Conducto deferente:** transporte. **Vesiculas seminales y prostata:** aportan liquidos. **Uretra:** conducto de salida que atraviesa el **pene**."},"id":"s04-cnt-1-2"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:3.1.1"],"title":"Modelo de recorrido","prompt":"Observa como explicar la estructura, funcion y recorrido de todas las partes.","type":"worked-example","props":{"icon":"MapPinned","problem":"¿Como se organiza el trayecto de las celulas reproductoras?","steps":[{"text":"Se forman en los testiculos y pasan al epididimo."},{"text":"Viajan por el conducto deferente; vesiculas seminales y prostata aportan liquidos."},{"text":"El semen pasa por la uretra, que atraviesa el pene, hacia el exterior."}],"answer":"Testiculos → epididimo → conducto deferente → aportes glandulares → uretra en el pene."},"id":"s04-cnt-1-3"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:3.1.1"],"prompt":"Con ayuda, ordena la estructura, funcion y recorrido: testiculos, epididimo, conducto deferente, vesiculas seminales, prostata, uretra y pene.","hint":"Empieza donde se forman los espermatozoides y termina en el conducto de salida.","explain":"Las glandulas aportan liquidos antes de que el semen recorra la uretra.","type":"order","props":{"labels":{"start":"Inicio","end":"Salida"},"items":[{"id":"a","text":"Testiculos: formacion"},{"id":"b","text":"Epididimo: maduracion y almacenamiento"},{"id":"c","text":"Conducto deferente: transporte"},{"id":"d","text":"Vesiculas seminales y prostata: liquidos"},{"id":"e","text":"Uretra a traves del pene: salida"}]},"id":"s04-cnt-1-4"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:3.1.1"],"prompt":"Relaciona funcion y estructura de testiculos, epididimo, conducto deferente, vesiculas seminales, prostata, uretra y pene.","hint":"Distingue formacion, almacenamiento, transporte, aporte de liquidos y salida.","explain":"Cada relacion ayuda a reconstruir el recorrido anatomico.","type":"match","props":{"pairs":[{"id":"a","left":"Testiculos y epididimo","right":"Formacion, maduracion y almacenamiento temporal"},{"id":"b","left":"Conducto deferente","right":"Transporte"},{"id":"c","left":"Vesiculas seminales y prostata","right":"Aporte de liquidos"},{"id":"d","left":"Uretra y pene","right":"Conducto y estructura de salida"}]},"id":"s04-cnt-1-5"},{"fase":"aplicar","areas":["cnt"],"cnb":["cnt:3.1.1"],"prompt":"Explica de forma independiente la estructura, funcion y recorrido de testiculos, epididimo, conducto deferente, vesiculas seminales, prostata, uretra y pene.","type":"short-answer","props":{"minWords":24,"placeholder":"El recorrido inicia...","model":"Los testiculos forman celulas reproductoras; el epididimo las almacena; el conducto deferente las transporta; vesiculas y prostata aportan liquidos; la uretra atraviesa el pene hacia el exterior.","rubric":["Nombre todas las estructuras","Relacione funcion y ubicacion","Ordene el recorrido"]},"id":"s04-cnt-1-6"},{"fase":"aplicar","areas":["cnt"],"cnb":["cnt:3.1.1"],"prompt":"Al explicar la estructura, funcion y recorrido de testiculos, epididimo, conducto deferente, vesiculas seminales, prostata, uretra y pene, ¿que secuencia es correcta?","type":"choice","props":{"options":[{"id":"a","text":"Formacion y epididimo; transporte; liquidos glandulares; uretra a traves del pene"},{"id":"b","text":"Uretra; testiculos; epididimo; sin glandulas"},{"id":"c","text":"Prostata forma todos los espermatozoides"}],"correct":["a"]},"id":"s04-cnt-1-7"},{"fase":"comprobar","areas":["cnt"],"cnb":["cnt:3.1.1"],"prompt":"Salida: identifica la explicacion correcta de estructura, funcion y recorrido de testiculos, epididimo, conducto deferente, vesiculas seminales, prostata, uretra y pene.","type":"choice","props":{"options":[{"id":"a","text":"Testiculos forman; epididimo almacena; deferente transporta; glandulas aportan; uretra atraviesa el pene"},{"id":"b","text":"El pene forma espermatozoides y la uretra los almacena"},{"id":"c","text":"Todas las partes cumplen la misma funcion"}],"correct":["a"]},"id":"s04-cnt-1-8"},{"fase":"comprobar","areas":["cnt"],"cnb":["cnt:3.1.1"],"prompt":"Salida nueva: comprueba estructura, funcion y recorrido de testiculos, epididimo, conducto deferente, vesiculas seminales, prostata, uretra y pene.","type":"true-false","props":{"statements":[{"text":"El epididimo participa en maduracion y almacenamiento temporal.","answer":true},{"text":"Vesiculas seminales y prostata aportan liquidos.","answer":true},{"text":"La uretra no tiene relacion con el pene.","answer":false}]},"id":"s04-cnt-1-9"}],"kind":"materia","area":"cnt","day":1}},{"missionId":"s04","version":"cnb-sexto-a1fd867b801087c1","lesson":{"id":"s04-ccss-1","title":"Ciencias Sociales para investigar preguntas","icon":"Search","minutes":14,"gancho":"Una pregunta sobre la comunidad puede necesitar varias miradas y evidencia.","objetivos":["Valorar la investigacion social al relacionar Ciencias Sociales con preguntas personales, comunitarias y nacionales"],"resumen":["Historia estudia procesos en el tiempo; Geografia, territorio y relaciones espaciales.","Sociologia estudia grupos e instituciones; Antropologia, culturas y formas de vida.","La investigacion social convierte inquietudes personales y nacionales en preguntas que pueden responderse con evidencia."],"media":{"id":"s04-ccss-1-ciencias","kind":"diagram","title":"Miradas para una pregunta social","aspect":"16:9","alt":"Cuatro lupas representan Historia, Geografia, Sociologia y Antropologia alrededor de una pregunta.","brief":"Diagrama 1600x900 con una pregunta comunitaria al centro y cuatro lupas: Historia-tiempo, Geografia-territorio, Sociologia-grupos e instituciones, Antropologia-culturas y formas de vida. Agregar flecha hacia \\"decidir con evidencia\\". Texto grande, alto contraste e iconos ademas de color."},"steps":[{"fase":"explorar","areas":["ccss"],"cnb":["ccss:5.1.1","ccss:5.1.4"],"prompt":"Valora la investigacion social: Historia, Geografia, Sociologia y Antropologia ayudan a responder preguntas personales, comunitarias y nacionales para decidir con evidencia.","type":"explain","props":{"icon":"Search","body":"Las Ciencias Sociales aportan miradas distintas. Investigarlas importa porque permite fundamentar respuestas en vez de depender solo de rumores."},"id":"s04-ccss-1-1"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:5.1.1","ccss:5.1.4"],"prompt":"Relaciona Historia, Geografia, Sociologia y Antropologia con la importancia de la investigacion social para preguntas personales, comunitarias y nacionales.","type":"explain","props":{"icon":"BookOpenCheck","body":"**Historia:** cambios en el tiempo. **Geografia:** territorio. **Sociologia:** grupos e instituciones. **Antropologia:** culturas y formas de vida. La investigacion social valora cada pregunta y ayuda a decidir con evidencia."},"id":"s04-ccss-1-2"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:5.1.1","ccss:5.1.4"],"title":"Modelo de pregunta social","prompt":"Observa como valorar la investigacion social usando Historia, Geografia, Sociologia y Antropologia para una pregunta comunitaria y nacional.","type":"worked-example","props":{"icon":"Lightbulb","problem":"¿Por que cambio el uso de la plaza y que significa para distintas familias?","steps":[{"text":"Historia busca cuando y por que cambio."},{"text":"Geografia estudia ubicacion y acceso."},{"text":"Sociologia y Antropologia examinan grupos, usos y significados."},{"text":"Valorar estas miradas permite decidir con evidencia en la comunidad y relacionar el caso con preguntas del pais."}],"answer":"Una pregunta social puede necesitar varias disciplinas y evidencia."},"id":"s04-ccss-1-3"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:5.1.1","ccss:5.1.4"],"prompt":"Con ayuda, valora la investigacion social y relaciona Historia, Geografia, Sociologia y Antropologia con preguntas personales, comunitarias y nacionales.","hint":"Busca tiempo, territorio, grupos o cultura.","explain":"Cada disciplina aporta evidencia diferente para fundamentar decisiones.","type":"match","props":{"pairs":[{"id":"a","left":"Historia","right":"Cambio de una costumbre en el tiempo"},{"id":"b","left":"Geografia","right":"Acceso territorial a servicios"},{"id":"c","left":"Sociologia","right":"Participacion de grupos e instituciones"},{"id":"d","left":"Antropologia","right":"Significados culturales de una practica"}]},"id":"s04-ccss-1-4"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:5.1.1","ccss:5.1.4"],"prompt":"¿Que opcion valora la investigacion social con Historia, Geografia, Sociologia y Antropologia para responder preguntas personales, comunitarias y nacionales?","hint":"Valorar implica reconocer utilidad y decidir con evidencia.","explain":"La opcion correcta vincula disciplinas, preguntas y utilidad social.","type":"choice","props":{"options":[{"id":"a","text":"Comparar sus evidencias ayuda a fundamentar respuestas y decisiones"},{"id":"b","text":"Una opinion sin fuente basta para todo problema"},{"id":"c","text":"Las preguntas personales nunca se relacionan con el pais"}],"correct":["a"]},"id":"s04-ccss-1-5"},{"fase":"aplicar","areas":["ccss"],"cnb":["ccss:5.1.1","ccss:5.1.4"],"prompt":"Valora de forma independiente la investigacion social: usa Historia, Geografia, Sociologia y Antropologia para una pregunta personal o comunitaria y otra nacional; explica su importancia para decidir con evidencia.","type":"short-answer","props":{"minWords":28,"placeholder":"Pregunta... Disciplinas... Importancia...","model":"Historia y Geografia explican cambios, lugares y acceso; Sociologia y Antropologia estudian grupos, relaciones y significados. Investigar una inquietud local y nacional permite comprenderla mejor y decidir con evidencia suficiente.","rubric":["Relacione las cuatro disciplinas","Inclui dos escalas de pregunta","Valore la utilidad de investigar"]},"id":"s04-ccss-1-6"},{"fase":"aplicar","areas":["ccss"],"cnb":["ccss:5.1.1","ccss:5.1.4"],"prompt":"Al valorar investigacion social, ¿como ayudan Historia, Geografia, Sociologia y Antropologia a preguntas personales, comunitarias y nacionales?","type":"choice","props":{"options":[{"id":"a","text":"Aportan evidencia temporal, territorial, grupal y cultural para fundamentar respuestas"},{"id":"b","text":"Reemplazan toda pregunta con una sola opinion"},{"id":"c","text":"Solo sirven para memorizar nombres"}],"correct":["a"]},"id":"s04-ccss-1-7"},{"fase":"comprobar","areas":["ccss"],"cnb":["ccss:5.1.1","ccss:5.1.4"],"prompt":"Salida: valora la investigacion social con Historia, Geografia, Sociologia y Antropologia ante preguntas personales, comunitarias y nacionales.","type":"choice","props":{"options":[{"id":"a","text":"Integra miradas y evidencia para comprender y decidir mejor"},{"id":"b","text":"Descarta preguntas de la comunidad por ser pequenas"},{"id":"c","text":"Acepta rumores sin comprobar"}],"correct":["a"]},"id":"s04-ccss-1-8"},{"fase":"comprobar","areas":["ccss"],"cnb":["ccss:5.1.1","ccss:5.1.4"],"prompt":"Salida nueva: comprueba como Historia, Geografia, Sociologia y Antropologia dan importancia a la investigacion social de preguntas personales, comunitarias y nacionales para decidir con evidencia.","type":"true-false","props":{"statements":[{"text":"Una inquietud personal puede convertirse en pregunta investigable.","answer":true},{"text":"Varias disciplinas pueden aportar evidencia complementaria.","answer":true},{"text":"Investigar no tiene utilidad para decisiones comunitarias o nacionales.","answer":false}]},"id":"s04-ccss-1-9"}],"kind":"materia","area":"ccss","day":1}},{"missionId":"s04","version":"cnb-sexto-05eda147ef986072","lesson":{"id":"s04-art-1","title":"Escuchar con atención: describir la música","icon":"Headphones","minutes":15,"gancho":"Todos los días oyes música: en el bus, en la tienda, en una fiesta. Pero ¿cuántas veces la **escuchas** de verdad, con atención?","objetivos":["Describir y valorar una pieza musical mediante escucha atenta y criterios musicales"],"resumen":["Oír es percibir sonidos sin poner atención; escuchar es poner atención para comprender y disfrutar.","Para describir una pieza, fíjate en: instrumentos y voces (timbre), tempo (rápido o lento), intensidad (fuerte o suave), compás (se cuenta en 2, 3 o 4) y carácter (la emoción que transmite: alegre, solemne, triste, tranquila).","La marimba es el instrumento nacional de Guatemala. En el país conviven muchas músicas: marimba, chirimía y tambor en los bailes tradicionales, tambores garífunas, bandas, rock, pop y más.","Valorar la música es escucharla con respeto, reconocer el trabajo de quien la hace y saber explicar por qué nos gusta o no."],"media":{"id":"s04-art-1-paisaje","kind":"video","title":"Músicas de Guatemala","aspect":"16:9","duration":60,"alt":"Un recorrido por escenas musicales: un conjunto de marimba en una feria, músicos de chirimía y tambor en un baile tradicional, tambores garífunas en la playa y una banda escolar.","brief":"Video de 60 s con cuatro escenas de 13 s (recreadas con músicos que dieron su permiso, rostros no protagonistas, sin marcas): (1) marimba de concierto con 4-5 músicos en una feria de pueblo; (2) chirimía y tambor acompañando un baile tradicional frente a un atrio; (3) tambores garífunas y maracas en Livingston, Izabal; (4) banda escolar de percusión y liras. En cada escena aparece un rótulo con el instrumento principal. Música: solo el sonido directo de cada escena (piezas originales o tradicionales de dominio público). Narración breve en español: \\"En Guatemala suenan muchas músicas\\". Accesibilidad: subtitulos completos para toda voz y transcripcion audiovisual; rotulos grandes, legibles y de alto contraste."},"steps":[{"fase":"explorar","areas":["art"],"cnb":["art:3.1.2"],"title":"Idea central","prompt":"Escuchar con atención ayuda a elegir música que acompañe un mensaje sin tapar las voces.","type":"explain","props":{"icon":"BookOpenCheck","body":"Oír es percibir sonidos sin poner atención; escuchar es poner atención para comprender y disfrutar."},"id":"s04-art-1-1"},{"fase":"construir","areas":["art"],"cnb":["art:3.1.2"],"ambito":"ser","prompt":"Piensa en tus días. Clasifica cada situación: ¿estás **oyendo** música de fondo o **escuchándola** con atención?","explain":"**Oír** es que el sonido te llegue; **escuchar** es poner atención. Para valorar la música, primero hay que escucharla de verdad.","type":"sort","props":{"buckets":[{"id":"o","label":"Oigo (de fondo)","icon":"Ear","color":"var(--c-maiz-strong)"},{"id":"e","label":"Escucho (con atención)","icon":"Headphones","color":"var(--area-art)"}],"items":[{"id":"x1","text":"La radio suena en la tienda mientras compro pan","bucket":"o"},{"id":"x2","text":"Cierro los ojos para descubrir qué instrumentos suenan","bucket":"e"},{"id":"x3","text":"Hay música en la camioneta y voy platicando","bucket":"o"},{"id":"x4","text":"Repito una canción para aprenderme la letra","bucket":"e"},{"id":"x5","text":"Cuento el compás de una pieza de marimba","bucket":"e"}]},"id":"s04-art-1-2"},{"fase":"construir","areas":["art"],"cnb":["art:3.1.2"],"ambito":"conocer","title":"Las cinco preguntas del buen oyente","prompt":"Cuando escuches una pieza con atención, hazte estas **cinco preguntas**. Ya conoces varias palabras de semanas anteriores. Toca cada tarjeta.","type":"explain","props":{"icon":"Headphones","body":"Estas preguntas te ayudan a **describir** la música con palabras precisas, no solo \\"me gusta\\" o \\"no me gusta\\".","reveal":[{"icon":"Guitar","front":"¿Qué suena?","back":"**Instrumentos y voces** (el **timbre**): marimba, guitarra, tambor, chirimía, voz de mujer, coro…"},{"icon":"Gauge","front":"¿Qué tan rápido?","back":"El **tempo**: rápido, moderado o lento. Síguelo con el pie: ¿tu pie va de prisa o despacio?"},{"icon":"Volume2","front":"¿Fuerte o suave?","back":"La **intensidad**. Muchas piezas cambian: empiezan suave y crecen, o al revés."},{"icon":"Drum","front":"¿En cuánto se cuenta?","back":"El **compás**: busca el acento y cuenta en 2, en 3 o en 4."},{"icon":"Smile","front":"¿Qué transmite?","back":"El **carácter**: alegre, festivo, solemne (serio y respetuoso), triste, tranquilo, misterioso… Es la emoción que provoca."}]},"id":"s04-art-1-3"},{"id":"s04-art-1-4","fase":"construir","areas":["art"],"cnb":["art:3.1.2"],"ambito":"hacer","title":"Modelo breve: describir antes de opinar","prompt":"Observa cómo una oyente usa datos musicales para justificar su valoración.","type":"worked-example","props":{"icon":"ClipboardList","problem":"En un fragmento de marimba, el pulso avanza rápido y el sonido empieza suave antes de crecer.","steps":[{"text":"**Descripción:** marimba, tempo rápido e intensidad que aumenta."},{"text":"**Carácter:** festivo, porque el pulso rápido invita a moverse."},{"text":"**Opinión:** me gusta porque el cambio de intensidad mantiene mi atención."}],"answer":"La valoración se apoya en lo escuchado: instrumento, tempo, intensidad y carácter."}},{"id":"s04-art-1-6","fase":"construir","areas":["art"],"cnb":["art:3.1.2"],"ambito":"hacer","prompt":"Con ayuda: oyes un tambor con golpes lentos y fuertes. ¿Qué descripción usa criterios musicales?","hint":"Busca una opción que nombre qué suena, el tempo y la intensidad.","explain":"“Tambor, tempo lento e intensidad fuerte” describe datos que otra persona también puede escuchar.","type":"choice","props":{"options":[{"id":"a","text":"Tambor, tempo lento e intensidad fuerte"},{"id":"b","text":"Es la mejor música del mundo"},{"id":"c","text":"Suena bien"}],"correct":["a"]}},{"id":"s04-art-1-7","fase":"aplicar","areas":["art"],"cnb":["art:3.1.2"],"ambito":"hacer","prompt":"Escucha el fragmento. ¿Cuál descripción es la más precisa?","explain":"Suena una chirimía con un tambor, a un tempo lento y con un carácter solemne. Una descripción precisa nombra lo que se escucha.","media":{"id":"s04-art-1-chirimia","kind":"audio","title":"Chirimía y tambor","duration":20,"alt":"Una chirimía toca una melodía lenta y aguda acompañada por golpes graves y pausados de un tambor.","brief":"Audio de 20 s: chirimía (oboe popular de madera) y tambor de cuero, grabados por intérpretes tradicionales con su permiso, melodía tradicional de dominio público o improvisación en estilo de procesión, tempo lento (≈60), intensidad moderada, carácter solemne. Sin voces. Registrar nombre de la comunidad en los créditos. Accesibilidad: transcripcion del contenido sonoro y guion exacto de las voces, si las hay."},"type":"choice","props":{"options":[{"id":"a","text":"Chirimía y tambor, tempo lento, carácter solemne"},{"id":"b","text":"Marimba y contrabajo, tempo rápido, carácter festivo","feedback":"Escucha de nuevo el timbre: es un instrumento de viento, no de teclas."},{"id":"c","text":"\\"Suena bonito\\"","feedback":"Es una opinión válida, pero no describe la música. Usa las cinco preguntas."}],"correct":["a"]}},{"id":"s04-art-1-8","fase":"aplicar","areas":["art"],"cnb":["art:3.1.2"],"ambito":"hacer","prompt":"Usa el fragmento suministrado de chirimía y tambor. Escribe su **ficha de escucha** con las cinco preguntas y tu **opinión con razones**; no necesitas buscar otra grabación.","explain":"Extensión opcional, no requerida: lee la entrevista ficticia de Rosa, quien recuerda la marimba de su infancia, y compárala mentalmente con tu ficha. Una entrevista local a una persona mayor también es opcional.","type":"short-answer","props":{"minWords":40,"placeholder":"Escuché… Suenan… El tempo es… La intensidad… Se cuenta en… Su carácter es… Me gusta porque…","model":"Escuché el fragmento suministrado de chirimía y tambor. La chirimía produce una melodía aguda y el tambor marca golpes graves. El tempo es lento, la intensidad es moderada y se puede contar en dos. Su carácter me parece solemne porque deja pausas amplias. Me gusta porque ambos timbres se distinguen con claridad.","rubric":["Nombra instrumentos o voces","Describe tempo e intensidad","Dice el compás o intenta contarlo","Describe el carácter","Da su opinión con al menos una razón"]}},{"id":"s04-art-1-10","fase":"comprobar","areas":["art"],"cnb":["art:3.1.2"],"prompt":"¿Cuál es la diferencia entre **oír** y **escuchar** música?","type":"choice","props":{"options":[{"id":"a","text":"Oír es percibir el sonido; escuchar es poner atención para comprenderlo"},{"id":"b","text":"Oír es con audífonos y escuchar es con bocinas"},{"id":"c","text":"No hay diferencia"}],"correct":["a"]}},{"id":"s04-art-1-11","fase":"comprobar","areas":["art"],"cnb":["art:3.1.2"],"prompt":"Une cada descripción con la palabra que le corresponde.","type":"match","props":{"pairs":[{"id":"a","left":"\\"Suena una voz de niña y un coro\\"","right":"Timbre"},{"id":"b","left":"\\"Va despacio, como caminando en procesión\\"","right":"Tempo"},{"id":"c","left":"\\"Me transmite calma y respeto\\"","right":"Carácter"}]}}],"kind":"materia","area":"art","day":1}},{"missionId":"s04","version":"cnb-sexto-9cd5a6e6267bb898","lesson":{"id":"s04-cnt-2","title":"Ovogenesis y espermatogenesis","icon":"GitCompare","minutes":15,"gancho":"Dos procesos producen celulas reproductoras, pero no siguen el mismo patron.","objetivos":["Distinguir ovogenesis y espermatogenesis por lugar, proceso y celulas resultantes"],"resumen":["La ovogenesis ocurre en los ovarios y produce una celula funcional grande y cuerpos polares.","La espermatogenesis ocurre en los testiculos y produce espermatozoides.","En lenguaje comun se dice ovulo; con precision, suele liberarse un ovocito secundario y la meiosis II se completa solo si ocurre fecundacion."],"media":{"id":"s04-cnt-2-gametogenesis","kind":"diagram","title":"Comparacion de gametogenesis","aspect":"16:9","alt":"Dos columnas comparan ovogenesis y espermatogenesis con celulas esquematicas.","brief":"Diagrama educativo 1600x900 en dos columnas. Ovogenesis: ovario, una celula funcional grande, cuerpos polares, ovocito secundario y nota de meiosis II. Espermatogenesis: testiculo y varios espermatozoides pequenos y moviles. Sin anatomia explicita; texto grande, alto contraste y formas ademas de color."},"steps":[{"fase":"explorar","areas":["cnt"],"cnb":["cnt:3.2.1"],"prompt":"Compara y distingue ovogenesis en ovarios y espermatogenesis en testiculos por proceso y celulas resultantes.","type":"explain","props":{"icon":"GitCompare","body":"Ambas usan division celular, pero cambian el lugar, el ritmo y el resultado."},"id":"s04-cnt-2-1"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:3.2.1"],"prompt":"Distingue ovogenesis y espermatogenesis: ovarios, testiculos, ovocito y espermatozoides.","type":"explain","props":{"icon":"Microscope","body":"La **ovogenesis** ocurre en ovarios y distribuye el citoplasma de manera desigual: una celula funcional grande y cuerpos polares. La **espermatogenesis** ocurre en testiculos y forma espermatozoides pequenos. Suele liberarse un **ovocito secundario**; la meiosis II se completa solo si ocurre la fecundacion. \\"Ovulo\\" es un termino comun simplificado."},"id":"s04-cnt-2-2"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:3.2.1"],"title":"Modelo comparativo","prompt":"Observa como comparar y distinguir ovogenesis y espermatogenesis.","type":"worked-example","props":{"icon":"Columns2","problem":"Completa lugar, celula resultante y diferencia.","steps":[{"text":"Ovogenesis: ovarios; una celula funcional grande y cuerpos polares."},{"text":"Espermatogenesis: testiculos; espermatozoides pequenos."},{"text":"La diferencia no es solo el nombre: cambia la distribucion del citoplasma y el resultado."}],"answer":"Los dos procesos forman gametos mediante rutas diferentes."},"id":"s04-cnt-2-3"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:3.2.1"],"prompt":"Con ayuda, compara y distingue ovogenesis en ovarios y espermatogenesis en testiculos, incluido ovocito y espermatozoides.","hint":"Busca lugar y producto.","explain":"La ovogenesis no produce cuatro celulas funcionales iguales.","type":"match","props":{"pairs":[{"id":"a","left":"Ovogenesis en ovarios","right":"Una celula funcional grande y cuerpos polares"},{"id":"b","left":"Espermatogenesis en testiculos","right":"Espermatozoides pequenos"},{"id":"c","left":"Ovocito secundario","right":"Puede ser liberado; meiosis II solo si ocurre fecundacion"}]},"id":"s04-cnt-2-4"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:3.2.1"],"prompt":"Compara ovogenesis y espermatogenesis por ovarios, testiculos, ovocito y espermatozoides.","hint":"No confundas el termino comun ovulo con la etapa celular precisa.","explain":"La opcion correcta diferencia lugar y resultado.","type":"choice","props":{"options":[{"id":"a","text":"Ovogenesis-ovarios-ovocito; espermatogenesis-testiculos-espermatozoides"},{"id":"b","text":"Ambas ocurren solo en ovarios"},{"id":"c","text":"Ambas producen celulas identicas"}],"correct":["a"]},"id":"s04-cnt-2-5"},{"fase":"aplicar","areas":["cnt"],"cnb":["cnt:3.2.1"],"prompt":"Compara y distingue de forma independiente ovogenesis en ovarios y espermatogenesis en testiculos; incluye ovocito, celula funcional grande, cuerpos polares y espermatozoides.","type":"short-answer","props":{"minWords":24,"placeholder":"Ovogenesis... Espermatogenesis...","model":"La ovogenesis ocurre en los ovarios y deja una celula funcional grande con cuerpos polares; la espermatogenesis ocurre en los testiculos y forma varios espermatozoides pequenos y moviles.","rubric":["Compare lugar","Diferencie resultados","Use terminos precisos"]},"id":"s04-cnt-2-6"},{"fase":"aplicar","areas":["cnt"],"cnb":["cnt:3.2.1"],"prompt":"Al comparar y distinguir ovogenesis y espermatogenesis en ovarios y testiculos, con ovocito y espermatozoides, ¿que diferencia importa?","type":"choice","props":{"options":[{"id":"a","text":"Lugar y tipo de celulas resultantes"},{"id":"b","text":"Solo el color de la celula"},{"id":"c","text":"No existe ninguna diferencia"}],"correct":["a"]},"id":"s04-cnt-2-7"},{"fase":"comprobar","areas":["cnt"],"cnb":["cnt:3.2.1"],"prompt":"Salida: compara y distingue ovogenesis en ovarios y espermatogenesis en testiculos, ovocito y espermatozoides.","type":"choice","props":{"options":[{"id":"a","text":"Ovogenesis: una celula funcional grande y cuerpos polares; espermatogenesis: espermatozoides"},{"id":"b","text":"Ovogenesis: testiculos; espermatogenesis: ovarios"},{"id":"c","text":"Los procesos producen resultados identicos"}],"correct":["a"]},"id":"s04-cnt-2-8"},{"fase":"comprobar","areas":["cnt"],"cnb":["cnt:3.2.1"],"prompt":"Salida nueva: distingue ovogenesis y espermatogenesis en ovarios y testiculos, ovocito y espermatozoides.","type":"true-false","props":{"statements":[{"text":"La ovogenesis ocurre en ovarios.","answer":true},{"text":"La espermatogenesis forma espermatozoides en testiculos.","answer":true},{"text":"La meiosis II del ovocito siempre termina antes de cualquier fecundacion.","answer":false}]},"id":"s04-cnt-2-9"}],"kind":"materia","area":"cnt","day":3}},{"missionId":"s04","version":"cnb-sexto-0bfa28618daf7044","lesson":{"id":"s04-ccss-2","title":"Usamos herramientas para reunir informacion","icon":"ClipboardList","minutes":14,"gancho":"Observar, entrevistar y encuestar producen registros distintos.","objetivos":["Usar herramientas de observacion, entrevista y encuesta para reunir informacion de un material suministrado"],"resumen":["La guia de observacion registra hechos visibles con criterios.","La entrevista recoge respuestas abiertas; la encuesta, respuestas comparables.","Una herramienta no autoriza inventar datos ni afirmar mas de lo que muestra el material."],"media":{"id":"s04-ccss-2-herramientas","kind":"diagram","title":"Tres herramientas de recoleccion","aspect":"16:9","alt":"Una guia de observacion, una entrevista y una encuesta junto a un caso ficticio.","brief":"Diagrama 1600x900. Mostrar una guia de observacion con casillas, una entrevista con preguntas abiertas y una encuesta con opciones, junto a una ficha rotulada \\"caso ficticio suministrado\\". Incluir nota \\"registrar, no inventar\\". Texto grande, alto contraste y orden de lectura accesible."},"steps":[{"fase":"explorar","areas":["ccss"],"cnb":["ccss:5.3.1"],"prompt":"Usa observacion, entrevista y encuesta para registrar informacion del caso y los datos suministrados.","type":"explain","props":{"icon":"ClipboardList","body":"Cada herramienta responde mejor a una necesidad: ver y registrar, profundizar una respuesta o comparar respuestas."},"id":"s04-ccss-2-1"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:5.3.1"],"prompt":"Aplica observacion, entrevista y encuesta al material suministrado sin inventar registros.","type":"explain","props":{"icon":"ListChecks","body":"**Observacion:** criterio visible. **Entrevista:** pregunta abierta y respuesta textual. **Encuesta:** misma pregunta y opciones para varias personas. Se registra solo lo suministrado."},"id":"s04-ccss-2-2"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:5.3.1"],"title":"Modelo con ficha suministrada","prompt":"Observa como usar las tres herramientas con un caso suministrado.","type":"worked-example","props":{"icon":"SearchCheck","problem":"Ficha ficticia: en el recreo, 6 estudiantes usan la cancha; Ana responde \\"falta sombra\\"; encuesta: 8 prefieren arboles y 4 un techo.","steps":[{"text":"Observacion: registrar 6 estudiantes en la cancha."},{"text":"Entrevista: conservar la respuesta abierta de Ana."},{"text":"Encuesta: organizar 8 arboles y 4 techo."}],"answer":"Cada dato se vincula con la herramienta que lo produjo."},"id":"s04-ccss-2-3"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:5.3.1"],"prompt":"Con ayuda, usa observacion, entrevista y encuesta para organizar el material suministrado del caso ficticio.","hint":"Distingue hecho visible, respuesta abierta y conteo comparable.","explain":"La fuente suministrada determina el registro; no se agregan respuestas.","type":"match","props":{"pairs":[{"id":"a","left":"Se ven tres bancas ocupadas","right":"Guia de observacion"},{"id":"b","left":"Luis explica por que usa el patio","right":"Entrevista"},{"id":"c","left":"9 eligen sombra y 5 eligen juegos","right":"Encuesta"}]},"id":"s04-ccss-2-4"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:5.3.1"],"prompt":"Usa observacion, entrevista y encuesta: selecciona el registro valido del material suministrado.","hint":"No conviertas una respuesta individual en dato de todo el grupo.","explain":"Una entrevista aporta una perspectiva, no una proporcion colectiva.","type":"choice","props":{"options":[{"id":"a","text":"Entrevista: Marta dijo que prefiere sentarse cerca de la biblioteca"},{"id":"b","text":"Encuesta: toda la escuela piensa igual que Marta"},{"id":"c","text":"Observacion: Marta representa a todas las familias"}],"correct":["a"]},"id":"s04-ccss-2-5"},{"fase":"aplicar","areas":["ccss"],"cnb":["ccss:5.3.1"],"prompt":"Usa observacion, entrevista y encuesta con este material suministrado: se observan 4 bebederos, Joel dice \\"uno gotea\\", y la encuesta registra 7 reparacion / 3 cartel. Completa un registro por herramienta.","type":"short-answer","props":{"minWords":22,"placeholder":"Observacion... Entrevista... Encuesta...","model":"Observacion: hay cuatro bebederos disponibles. Entrevista suministrada: Joel informa un goteo constante. Encuesta simulada: siete personas eligen reparacion y tres prefieren colocar un cartel.","rubric":["Use las tres herramientas","Registre solo datos suministrados","Distingui tipos de evidencia"]},"id":"s04-ccss-2-6"},{"fase":"aplicar","areas":["ccss"],"cnb":["ccss:5.3.1"],"prompt":"Al usar observacion, entrevista y encuesta con una ficha de datos suministrados, ¿que accion demuestra uso real?","type":"choice","props":{"options":[{"id":"a","text":"Completar cada registro con la evidencia correspondiente"},{"id":"b","text":"Inventar respuestas que faltan"},{"id":"c","text":"Nombrar herramientas sin registrar nada"}],"correct":["a"]},"id":"s04-ccss-2-7"},{"fase":"comprobar","areas":["ccss"],"cnb":["ccss:5.3.1"],"prompt":"Salida: usa observacion, entrevista y encuesta para seleccionar el registro correcto del material suministrado.","type":"choice","props":{"options":[{"id":"a","text":"Visible-observacion; respuesta abierta-entrevista; conteo comun-encuesta"},{"id":"b","text":"Todo dato corresponde a entrevista"},{"id":"c","text":"Las herramientas permiten inventar detalles"}],"correct":["a"]},"id":"s04-ccss-2-8"},{"fase":"comprobar","areas":["ccss"],"cnb":["ccss:5.3.1"],"prompt":"Salida nueva: aplica observacion, entrevista y encuesta al caso con registros suministrados.","type":"true-false","props":{"statements":[{"text":"Una guia de observacion usa criterios visibles.","answer":true},{"text":"Una entrevista abierta puede conservar las palabras de una persona.","answer":true},{"text":"Una encuesta autoriza completar respuestas no suministradas.","answer":false}]},"id":"s04-ccss-2-9"}],"kind":"materia","area":"ccss","day":3}},{"missionId":"s04","version":"cnb-sexto-282cd0af2d86e331","lesson":{"id":"s04-pyd-1","title":"Leer la naturaleza antes de sembrar","icon":"CloudSun","minutes":15,"gancho":"¿Por qué en Totonicapán se cosechan papas y duraznos, pero no bananos, y en Escuintla crece la caña pero no el trigo?","objetivos":["Analizar clima, suelo, estaciones y relieve para proponer una actividad productiva adecuada"],"resumen":["Antes de producir se analiza la naturaleza: temperatura (depende mucho de la altura), lluvias y estaciones, tipo de suelo, pendiente del terreno y fenómenos como heladas, canícula o tormentas.","En Guatemala, a grandes rasgos: tierra caliente (costas y tierras bajas) para caña, banano, palma y mango; tierra templada (laderas y valles medios) para café, cítricos y aguacate; tierra fría (altiplano alto) para papa, trigo, haba, hortalizas y frutas como manzana y durazno. El maíz y el frijol se siembran en casi todo el país con variedades distintas.","La época lluviosa va aproximadamente de mayo a octubre y la seca de noviembre a abril; a mitad de las lluvias suele venir la canícula (unas semanas secas). Sin riego, se siembra al empezar las lluvias.","Suelo arenoso: el agua se va rápido. Arcilloso: se encharca y se endurece. Franco: mezcla equilibrada, el mejor para la mayoría de cultivos. En laderas se usan terrazas y curvas a nivel."],"media":{"id":"s04-pyd-1-pisos","kind":"diagram","title":"De la costa al altiplano","aspect":"16:9","alt":"Corte de una montaña de Guatemala desde la costa hasta el altiplano, con tres franjas (caliente, templada y fría) y los cultivos de cada una.","brief":"Diagrama en corte lateral de un paisaje guatemalteco: a la izquierda el mar y la costa sur, subiendo hacia volcanes y el altiplano a la derecha. Tres franjas de color: \\"Tierra caliente\\" (naranja, abajo) con caña, banano y palma; \\"Tierra templada\\" (verde, en medio) con cafetales bajo sombra, naranjos y aguacates; \\"Tierra fría\\" (azul, arriba) con papa, trigo, haba y árboles de durazno, y un pequeño símbolo de helada. Un termómetro a un lado que baja al subir. Milpa dibujada en las tres franjas. Nota al pie: \\"A más altura, menos temperatura\\". Sin cifras exactas de altura. Dimensiones: 1600x900. Accesibilidad: contraste alto, rotulos grandes y legibles; la descripcion visual debe corresponder exactamente al texto alternativo."},"steps":[{"fase":"explorar","areas":["pyd"],"cnb":["pyd:2.5.3"],"title":"Idea central","prompt":"Cuidar la vida comunitaria incluye analizar clima, suelo y agua antes de proponer una actividad productiva.","type":"explain","props":{"icon":"BookOpenCheck","body":"Antes de producir se analiza la naturaleza: temperatura (depende mucho de la altura), lluvias y estaciones, tipo de suelo, pendiente del terreno y fenómenos como heladas, canícula o tormentas."},"id":"s04-pyd-1-1"},{"fase":"construir","areas":["pyd"],"cnb":["pyd:2.5.3"],"ambito":"conocer","prompt":"¿Por qué crees que en el altiplano de Totonicapán **no** se cultivan bananos?","explain":"El banano necesita **calor todo el año**. En el altiplano alto hace frío y en algunos meses caen **heladas**, que queman las hojas de las plantas de tierra caliente.","type":"choice","props":{"options":[{"id":"a","text":"Porque hace frío y puede haber heladas","icon":"Snowflake"},{"id":"b","text":"Porque a la gente de allí no le gustan","icon":"Smile","feedback":"El gusto no es la razón: el banano simplemente no crece bien con frío."},{"id":"c","text":"Porque llueve demasiado","icon":"CloudRain","feedback":"El banano necesita bastante agua; el problema en el altiplano es la temperatura."}],"correct":["a"]},"id":"s04-pyd-1-2"},{"fase":"construir","areas":["pyd"],"cnb":["pyd:2.5.3"],"ambito":"conocer","title":"Cinco preguntas a la naturaleza","prompt":"Quien produce **analiza la naturaleza** antes de decidir qué sembrar o criar. Toca cada pregunta.","type":"explain","props":{"icon":"Search","body":"Sembrar sin analizar es arriesgar la semilla, el trabajo y el dinero de la familia.","reveal":[{"icon":"Thermometer","front":"1. ¿Qué temperatura hay?","back":"Depende sobre todo de la **altura**: a más altura, más frío. Cada cultivo tiene su rango de temperatura."},{"icon":"CloudRain","front":"2. ¿Cuándo y cuánto llueve?","back":"Hay una **época lluviosa** (aprox. mayo a octubre) y una **seca** (noviembre a abril). Sin riego, se depende de la lluvia."},{"icon":"Shovel","front":"3. ¿Cómo es el suelo?","back":"**Arenoso** (el agua se va rápido), **arcilloso** (se encharca y se endurece) o **franco** (equilibrado, el mejor para casi todo)."},{"icon":"Mountain","front":"4. ¿Es plano o ladera?","back":"En **laderas**, la lluvia arrastra el suelo. Hay que hacer **terrazas** o **curvas a nivel**."},{"icon":"Snowflake","front":"5. ¿Qué fenómenos hay?","back":"**Heladas** en el altiplano (sobre todo entre diciembre y febrero), **canícula** (semanas secas a mitad de las lluvias), tormentas y huracanes."}]},"id":"s04-pyd-1-3"},{"fase":"construir","areas":["pyd"],"cnb":["pyd:2.5.3"],"ambito":"conocer","title":"Tierra caliente, templada y fría","prompt":"En Guatemala, las familias campesinas hablan de **tres tipos de tierra** según su clima. Toca cada una.","type":"explain","props":{"icon":"Thermometer","body":"El **maíz** y el **frijol** se siembran en casi todo el país: cada región tiene sus propias **variedades** adaptadas a su clima.","reveal":[{"icon":"Sun","front":"Tierra caliente","back":"Costas y tierras bajas (costa sur, oriente bajo, Petén). Calor todo el año. Cultivos: **caña de azúcar, banano, palma, mango, ajonjolí**."},{"icon":"CloudSun","front":"Tierra templada","back":"Laderas y valles de altura media (bocacosta, parte de las Verapaces y del centro). Clima agradable. Cultivos: **café, cítricos, aguacate**."},{"icon":"Snowflake","front":"Tierra fría","back":"Altiplano alto (Totonicapán, partes de Quetzaltenango, San Marcos y Huehuetenango). Noches frías y heladas. Cultivos: **papa, trigo, haba, brócoli, manzana, durazno**."}]},"id":"s04-pyd-1-4"},{"fase":"construir","areas":["pyd"],"cnb":["pyd:2.5.3"],"prompt":"¿En qué tipo de tierra crece mejor cada cultivo?","hint":"Los cultivos que resisten frío y heladas van en tierra fría; los que necesitan calor todo el año, en tierra caliente; el café está en medio.","explain":"Cada cultivo se adapta a un rango de temperatura. Por eso el tipo de tierra decide qué conviene producir.","type":"sort","props":{"buckets":[{"id":"cal","label":"Tierra caliente","icon":"Sun","color":"var(--c-maiz-strong)"},{"id":"tem","label":"Tierra templada","icon":"CloudSun","color":"var(--c-ok)"},{"id":"fri","label":"Tierra fría","icon":"Snowflake","color":"var(--area-cnt)"}],"items":[{"id":"k1","text":"Caña de azúcar","bucket":"cal"},{"id":"k2","text":"Papa","bucket":"fri"},{"id":"k3","text":"Café","bucket":"tem"},{"id":"k4","text":"Banano","bucket":"cal"},{"id":"k5","text":"Trigo","bucket":"fri"},{"id":"k6","text":"Haba","bucket":"fri"}]},"id":"s04-pyd-1-5"},{"fase":"construir","areas":["pyd"],"cnb":["pyd:2.5.3"],"ambito":"conocer","title":"El calendario de la lluvia y el cuidado del suelo","prompt":"Además del clima, hay que saber **cuándo** sembrar y **cómo** cuidar el suelo. Toca cada tarjeta.","media":{"id":"s04-pyd-1-calendario","kind":"animation","title":"Un año de lluvia en la milpa","aspect":"16:9","duration":45,"alt":"Un calendario circular de 12 meses se colorea de azul en la época lluviosa y amarillo en la seca; una milpa crece desde la siembra en mayo hasta la cosecha.","brief":"Animación 2D de 45 s. Calendario circular con los 12 meses. Noviembre a abril en amarillo con sol (\\"época seca\\"); mayo a octubre en azul con nubes (\\"época lluviosa\\"). En mayo aparece una mano que siembra maíz y frijol; la milpa crece mes a mes; en julio-agosto una franja más clara con el texto \\"canícula: semanas secas\\". Al final, cosecha. Un inserto muestra una ladera con terrazas que detienen el agua. Nota en pantalla: \\"Las fechas cambian un poco según la región\\". Narración en español, subtítulos."},"type":"explain","props":{"icon":"Calendar","body":"Las fechas pueden cambiar un poco en cada región: por eso se escucha también a los agricultores con experiencia.","reveal":[{"icon":"CloudRain","front":"Sembrar con las lluvias","back":"Sin riego, se siembra **al empezar las lluvias** (en muchas regiones, alrededor de **mayo**), para que la semilla tenga humedad y germine."},{"icon":"Sun","front":"La canícula","back":"A mitad de la época lluviosa (julio-agosto) suelen venir **semanas secas**. Conviene guardar agua de lluvia y usar variedades que la resistan."},{"icon":"Layers","front":"Mejorar el suelo","back":"El **abono orgánico** (restos de cosecha, estiércol curado) mejora suelos arenosos y arcillosos: retiene humedad y nutrientes."},{"icon":"Mountain","front":"Cuidar las laderas","back":"**Terrazas**, **curvas a nivel** y **barreras vivas** (hileras de plantas) frenan el agua y evitan que se lleve el suelo."}]},"id":"s04-pyd-1-6"},{"fase":"construir","areas":["pyd"],"cnb":["pyd:2.5.3"],"ambito":"hacer","title":"Ejemplo resuelto: analizar un terreno","prompt":"Mira cómo doña Isabel usa las cinco preguntas para decidir qué sembrar.","type":"worked-example","props":{"icon":"Sprout","problem":"Doña Isabel tiene un terreno en Chimaltenango, en tierra **templada a fría**, **sin riego**, en **ladera**, con suelo **franco**. En diciembre a veces cae helada. ¿Qué siembra, cuándo y cómo?","steps":[{"text":"**Temperatura:** clima fresco con posible helada en diciembre: debe cosechar **antes** de las heladas."},{"text":"**Lluvia:** sin riego, depende de la lluvia: siembra al **empezar las lluvias** (mayo)."},{"text":"**Suelo:** franco, bueno para la **milpa** (maíz, frijol y ayote juntos) y para hortalizas."},{"text":"**Pendiente:** ladera: hará **curvas a nivel** con barreras vivas para que la lluvia no se lleve el suelo.","why":"Sin estas obras, cada aguacero arrastra la capa fértil del suelo."},{"text":"**Fenómenos:** para la canícula, guardará agua de lluvia en toneles para sus hortalizas."}],"answer":"Doña Isabel sembrará **milpa en mayo**, con **curvas a nivel**, y cosechará antes de las heladas. Analizar la naturaleza le ayuda a **no perder** su cosecha.","tip":"Temperatura → lluvia → suelo → pendiente → fenómenos → decisión."},"id":"s04-pyd-1-7"},{"fase":"aplicar","areas":["pyd"],"cnb":["pyd:2.5.3"],"ambito":"emprender","prompt":"Don Tomás tiene un terreno **sin riego** en una región donde las lluvias empiezan como en la mayor parte del país. Mueve el calendario al **mes** en el que conviene sembrar su milpa.","explain":"Sin riego, la semilla necesita humedad para germinar: por eso se siembra al empezar las lluvias, alrededor de mayo (en algunas zonas se adelanta o se atrasa un poco).","type":"slider","props":{"min":1,"max":12,"step":1,"answer":5,"tolerance":1,"start":1,"visual":"line","display":"number","unit":"mes","ticks":[{"value":1,"label":"Ene"},{"value":3,"label":"Mar"},{"value":5,"label":"May"},{"value":7,"label":"Jul"},{"value":9,"label":"Sep"},{"value":11,"label":"Nov"}]},"id":"s04-pyd-1-8"},{"fase":"aplicar","areas":["pyd"],"cnb":["pyd:2.5.3"],"ambito":"hacer","prompt":"Une cada **fenómeno o condición** de la naturaleza con la **medida** que ayuda a producir a pesar de ella.","explain":"Conocer los fenómenos permite prevenir pérdidas: cada uno tiene una respuesta adecuada.","type":"match","props":{"leftTitle":"Fenómeno o condición","rightTitle":"Medida","pairs":[{"id":"m1","left":"Heladas en diciembre","leftIcon":"Snowflake","right":"Cosechar antes o sembrar cultivos que resisten el frío"},{"id":"m2","left":"Canícula a mitad de las lluvias","leftIcon":"Sun","right":"Guardar agua de lluvia y usar variedades resistentes a la sequía"},{"id":"m3","left":"Aguaceros fuertes en una ladera","leftIcon":"CloudRain","right":"Hacer terrazas o curvas a nivel"},{"id":"m4","left":"Suelo arenoso que no guarda agua","leftIcon":"Shovel","right":"Agregar abono orgánico"}]},"id":"s04-pyd-1-9"},{"fase":"aplicar","areas":["pyd"],"cnb":["pyd:2.5.3"],"ambito":"emprender","prompt":"No todo es sembrar. Una comunidad de **tierra caliente** junto a un lago, con mucho sol y bosque cercano, quiere **otra forma de producir** además de sus cultivos. ¿Qué opción aprovecha mejor su naturaleza **sin dañarla**?","explain":"Analizar la naturaleza también sirve para elegir otras actividades: la apicultura aprovecha las flores del bosque (y las abejas ayudan a polinizar), y el turismo comunitario vive de la belleza del lago.","type":"choice","props":{"options":[{"id":"a","text":"Criar abejas para miel y ofrecer turismo comunitario en el lago"},{"id":"b","text":"Sembrar trigo y papa","feedback":"El trigo y la papa necesitan clima frío; en tierra caliente no se darían bien."},{"id":"c","text":"Talar el bosque para sembrar más","feedback":"Talar el bosque daña el agua y el suelo, y acaba con otras formas de producir."}],"correct":["a"]},"id":"s04-pyd-1-10"},{"fase":"comprobar","areas":["pyd"],"cnb":["pyd:2.5.3"],"prompt":"En un terreno **sin riego**, ¿cuándo conviene sembrar la milpa?","type":"choice","props":{"options":[{"id":"a","text":"Al empezar la época de lluvias"},{"id":"b","text":"A mitad de la época seca"},{"id":"c","text":"Cuando caen las heladas"}],"correct":["a"]},"id":"s04-pyd-1-11"},{"fase":"comprobar","areas":["pyd"],"cnb":["pyd:2.5.3"],"prompt":"¿Verdadero o falso?","type":"true-false","props":{"statements":[{"text":"A más altura, la temperatura suele ser más baja.","answer":true},{"text":"El suelo franco es una mezcla equilibrada, buena para la mayoría de cultivos.","answer":true},{"text":"El café es un cultivo típico de tierra fría con heladas.","answer":false,"why":"El café crece en tierra templada; las heladas lo dañan."},{"text":"Las terrazas ayudan a que la lluvia no arrastre el suelo de una ladera.","answer":true}]},"id":"s04-pyd-1-12"},{"fase":"reflexionar","ambito":"ser","prompt":"¿Cómo te fue? Sé honesto: aprender es un camino.","areas":["pyd"],"cnb":["pyd:2.5.3"],"type":"reflection","props":{"statements":["Explico cómo el clima, la lluvia y el suelo deciden qué se puede producir","Relaciono cultivos con tierra caliente, templada y fría","Propongo medidas ante heladas, canícula y lluvias fuertes"],"commitments":["Preguntaré a un agricultor de mi familia o comunidad cómo decide cuándo sembrar"]},"id":"s04-pyd-1-13"}],"kind":"materia","area":"pyd","day":3}},{"missionId":"s04","version":"cnb-sexto-8016f6dc0b95a9c2","lesson":{"id":"s04-ccss-3","title":"De sociedades cazadoras y recolectoras a agricultoras","icon":"History","minutes":15,"gancho":"La agricultura transformo muchas formas de vida, aunque los cambios fueron graduales y diversos.","objetivos":["Comparar caracteristicas, cambios y formas de vida de sociedades cazadoras, recolectoras y agricultoras"],"resumen":["Muchas sociedades cazadoras y recolectoras combinaron movilidad, campamentos y conocimiento estacional.","La agricultura favorecio asentamientos mas permanentes, cultivos, almacenamiento y nuevas tareas.","La transicion fue gradual, ocurrio en momentos distintos y no significa que todas las sociedades siguieran una sola ruta."],"media":{"id":"s04-ccss-3-sociedades","kind":"diagram","title":"Cambios en formas de vida","aspect":"16:9","alt":"Linea comparativa de campamento movil, recoleccion, caza, cultivo y aldea permanente.","brief":"Diagrama historico 1600x900 que compara movilidad y campamentos estacionales de sociedades cazadoras-recolectoras con cultivos, almacenamiento y aldeas de sociedades agricultoras. Incluir flechas discontinuas y nota \\"transiciones graduales y diversas, no una escala de superioridad\\". Alto contraste, texto grande y descripcion accesible."},"steps":[{"fase":"explorar","areas":["ccss"],"cnb":["ccss:6.2.1"],"prompt":"Compara la evolucion y las formas de vida de sociedades cazadoras, recolectoras y agricultoras: movilidad, campamento, cultivo y aldea.","type":"explain","props":{"icon":"History","body":"Los cambios en subsistencia transformaron asentamientos y tareas, pero no ocurrieron igual ni al mismo tiempo en todas partes."},"id":"s04-ccss-3-1"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:6.2.1"],"prompt":"Distingue sociedades cazadoras-recolectoras y agricultoras por movilidad, campamentos, cultivos, almacenamiento y aldeas.","type":"explain","props":{"icon":"GitCompare","body":"Cazar y recolectar suele requerir conocimiento estacional y movilidad entre campamentos. Cultivar puede favorecer sedentarismo relativo, aldeas y almacenamiento. Hubo combinaciones y transiciones graduales."},"id":"s04-ccss-3-2"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:6.2.1"],"title":"Modelo de comparacion","prompt":"Observa como comparar la evolucion y formas de vida cazadora, recolectora y agricultora.","type":"worked-example","props":{"icon":"Columns2","problem":"Dos conjuntos de evidencias muestran campamentos estacionales y una aldea con graneros.","steps":[{"text":"Campamentos y movilidad se relacionan con caza y recoleccion estacional."},{"text":"Cultivos, graneros y aldea estable se relacionan con agricultura."},{"text":"La diferencia indica un cambio gradual de subsistencia y asentamiento, no superioridad."}],"answer":"La evidencia permite comparar formas de vida y procesos de cambio."},"id":"s04-ccss-3-3"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:6.2.1"],"prompt":"Con ayuda, compara evolucion y formas de vida cazadora-recolectora y agricultora: movilidad, campamento, cultivo y aldea.","hint":"Busca desplazamiento estacional o produccion y almacenamiento.","explain":"Algunas sociedades combinaron ambas formas; aqui se clasifica el rasgo predominante.","type":"sort","props":{"buckets":[{"id":"cr","label":"Cazadora-recolectora","icon":"Footprints"},{"id":"ag","label":"Agricultora","icon":"Wheat"}],"items":[{"id":"a","text":"Campamento estacional y movilidad","bucket":"cr"},{"id":"b","text":"Caza y recoleccion de plantas silvestres","bucket":"cr"},{"id":"c","text":"Cultivo y almacenamiento","bucket":"ag"},{"id":"d","text":"Aldea mas permanente","bucket":"ag"}]},"id":"s04-ccss-3-4"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:6.2.1"],"prompt":"Compara la evolucion y formas de vida de cazadores, recolectores y agricultores por movilidad, campamento, cultivo y aldea.","hint":"La transicion fue gradual y diversa.","explain":"La agricultura cambio subsistencia y asentamiento sin borrar de inmediato otras practicas.","type":"choice","props":{"options":[{"id":"a","text":"Muchas comunidades combinaron practicas durante cambios graduales"},{"id":"b","text":"Todas cambiaron el mismo ano"},{"id":"c","text":"La agricultura elimino toda movilidad"}],"correct":["a"]},"id":"s04-ccss-3-5"},{"fase":"aplicar","areas":["ccss"],"cnb":["ccss:6.2.1"],"prompt":"Compara de forma independiente evolucion y formas de vida cazadora-recolectora y agricultora; incluye movilidad, campamento, cultivo, almacenamiento y aldea.","type":"short-answer","props":{"minWords":26,"placeholder":"La primera forma... La segunda... El cambio...","model":"La caza y recoleccion implicaron movilidad y campamentos temporales; la agricultura sumo cultivos, almacenamiento y aldeas permanentes. La transicion fue gradual, diversa y distinta segun cada territorio.","rubric":["Compare subsistencia","Compare asentamiento","Explique el cambio sin una escala de superioridad"]},"id":"s04-ccss-3-6"},{"fase":"aplicar","areas":["ccss"],"cnb":["ccss:6.2.1"],"prompt":"Al comparar evolucion y formas de vida cazadora, recolectora y agricultora, ¿que evidencia distingue movilidad y campamento de cultivo y aldea?","type":"choice","props":{"options":[{"id":"a","text":"Campamentos estacionales frente a campos, almacenamiento y asentamiento mas permanente"},{"id":"b","text":"El color de las herramientas"},{"id":"c","text":"Una fecha unica para todo el mundo"}],"correct":["a"]},"id":"s04-ccss-3-7"},{"fase":"comprobar","areas":["ccss"],"cnb":["ccss:6.2.1"],"prompt":"Salida: compara evolucion y formas de vida cazadora-recolectora y agricultora mediante movilidad, campamento, cultivo y aldea.","type":"choice","props":{"options":[{"id":"a","text":"Movilidad estacional y campamentos; luego cultivos, almacenamiento y aldeas en transiciones diversas"},{"id":"b","text":"Las formas de vida fueron identicas"},{"id":"c","text":"Toda sociedad abandono la recoleccion de inmediato"}],"correct":["a"]},"id":"s04-ccss-3-8"},{"fase":"comprobar","areas":["ccss"],"cnb":["ccss:6.2.1"],"prompt":"Salida nueva: distingue evolucion y formas de vida cazadora, recolectora y agricultora por movilidad, campamento, cultivo y aldea.","type":"true-false","props":{"statements":[{"text":"La movilidad podia seguir ciclos estacionales.","answer":true},{"text":"Cultivo y almacenamiento favorecieron asentamientos mas permanentes.","answer":true},{"text":"La transicion fue instantanea e igual en todas partes.","answer":false}]},"id":"s04-ccss-3-9"}],"kind":"materia","area":"ccss","day":4}},{"missionId":"s04","version":"cnb-sexto-15f38dc681566500","lesson":{"id":"s04-art-2","title":"La música que elijo: mensajes, respeto y cuidado del oído","icon":"Music","minutes":15,"gancho":"Te sabes de memoria muchas canciones. Pero ¿alguna vez te has detenido a pensar **qué dicen** y **qué te hacen sentir**?","objetivos":["Elegir música con criterios de mensaje, respeto y cuidado auditivo"],"resumen":["La música que consumimos transmite ideas y valores. Por eso conviene escuchar la letra: ¿respeta a las personas o se burla de ellas, promueve la violencia o el cuidado?","Valorar con criterio es dar razones: por su música (ritmo, melodía, instrumentos), por su letra y por lo que nos hace sentir.","Cada persona tiene gustos distintos. Se pueden dar opiniones sin burlarse de lo que le gusta a otra persona. Escuchar músicas de otros pueblos y épocas amplía nuestro mundo.","El oído se daña con sonidos muy fuertes por mucho tiempo. Usa volumen moderado, toma descansos y aléjate de las bocinas en fiestas."],"media":{"id":"s04-art-2-oido","kind":"animation","title":"Cómo cuidar tu oído","aspect":"16:9","duration":45,"alt":"Dentro del oído, pequeñas células con forma de pelitos se mueven con el sonido. Con volumen moderado se balancean; con volumen muy fuerte y por mucho tiempo se doblan y se dañan.","brief":"Animación 2D de 45 s, estilo amable, apta para 11-12 años. (1) Una niña con audífonos; zoom a su oído interno: células ciliadas dibujadas como hierbitas que se mecen con ondas suaves (volumen moderado). (2) El volumen sube mucho por largo rato: las hierbitas se doblan y algunas quedan caídas; rótulo \\"este daño no se recupera\\". (3) Consejos con íconos: bajar el volumen, descansar los oídos, alejarse de las bocinas, \\"si alguien a tu lado oye tu música desde tus audífonos, está muy fuerte\\". Sin cifras de decibeles. Narración en español, subtítulos."},"steps":[{"fase":"explorar","areas":["art"],"cnb":["art:3.1.2"],"title":"Idea central","prompt":"Antes de usar música en una campaña, revisa su mensaje, el respeto y el cuidado del oído.","type":"explain","props":{"icon":"BookOpenCheck","body":"La música que consumimos transmite ideas y valores. Por eso conviene escuchar la letra: ¿respeta a las personas o se burla de ellas, promueve la violencia o el cuidado?"},"id":"s04-art-2-1"},{"fase":"construir","areas":["art"],"cnb":["art:3.1.2"],"ambito":"ser","prompt":"Una canción tiene un ritmo pegajoso, pero su letra se burla de las personas de un pueblo. ¿Qué piensas?","explain":"Una canción es **música y mensaje**. Puede tener un ritmo que nos guste y, aun así, un mensaje que no compartimos. Aprender a notarlo es **valorar con criterio**.","type":"choice","props":{"options":[{"id":"a","text":"Si el ritmo es bueno, la letra no importa","icon":"Music","feedback":"El ritmo importa, pero la letra también transmite ideas que repetimos sin darnos cuenta."},{"id":"b","text":"Puedo reconocer que el ritmo es pegajoso y, a la vez, no estar de acuerdo con su mensaje","icon":"Scale"},{"id":"c","text":"Toda la música moderna es mala","icon":"X","feedback":"Hay música moderna con mensajes muy valiosos. Se trata de escuchar cada canción con atención."}],"correct":["b"]},"id":"s04-art-2-2"},{"fase":"construir","areas":["art"],"cnb":["art:3.1.2"],"ambito":"conocer","title":"Tres preguntas para elegir con criterio","prompt":"Además de describir la música (lo que aprendiste el lunes), puedes **valorarla** con estas preguntas. Toca cada tarjeta.","type":"explain","props":{"icon":"Scale","body":"Valorar con criterio no es juzgar a las personas por lo que escuchan: es **pensar** sobre lo que tú eliges escuchar y repetir.","reveal":[{"icon":"Music","front":"¿Cómo está hecha?","back":"Su **música**: ritmo, melodía, instrumentos, voces. ¿Es creativa? ¿Está bien tocada? ¿Qué te llama la atención?"},{"icon":"MessageCircle","front":"¿Qué dice?","back":"Su **letra y mensaje**: ¿respeta a mujeres, hombres y pueblos?, ¿habla de amor, de la tierra, de fiesta, de problemas?, ¿promueve la violencia o las drogas?"},{"icon":"Heart","front":"¿Qué me provoca?","back":"Cómo te **hace sentir** y actuar: ¿te anima, te calma, te hace pensar, te hace sentir mal contigo o con otras personas?"}]},"id":"s04-art-2-3"},{"fase":"construir","areas":["art"],"cnb":["art:3.1.2"],"ambito":"convivir","title":"Respeto por los gustos y oídos abiertos","prompt":"En tu grado hay personas que prefieren marimba, otras reguetón, otras música cristiana o rock. ¿Cómo convivir? Toca cada tarjeta.","type":"explain","props":{"icon":"Users","body":"Cada persona tiene **derecho a sus gustos**. Lo que sí podemos hacer es opinar con respeto y **conocer más músicas**.","reveal":[{"icon":"MessageCircle","front":"Opinar sin burlarse","back":"Di \\"a mí no me gusta porque…\\" en lugar de \\"esa música es horrible\\". Critica la canción, no a la persona."},{"icon":"Globe","front":"Explorar","back":"Escucha música de otros pueblos y épocas: marimba, música garífuna, sones, música de otros países. Tu gusto crece cuando conoce más."},{"icon":"HandHeart","front":"Valorar a quien la hace","back":"Detrás de cada pieza hay horas de práctica. Aplaude a los músicos de tu comunidad y aprende de ellos."}]},"id":"s04-art-2-4"},{"fase":"construir","areas":["art"],"cnb":["art:3.1.2"],"ambito":"hacer","title":"Ejemplo resuelto: una reseña con criterio","prompt":"Mira cómo Diego valora una canción de moda usando las tres preguntas.","type":"worked-example","props":{"icon":"NotebookPen","problem":"A Diego le encanta una canción muy popular. Su maestra le pide una **reseña** corta con criterio.","steps":[{"text":"**¿Cómo está hecha?** \\"Tiene un ritmo en 4 muy bailable y un coro fácil de cantar. Usa sonidos electrónicos y una guitarra.\\""},{"text":"**¿Qué dice?** \\"Habla de salir de fiesta. En una parte dice que las mujeres solo sirven para verse bonitas.\\"","why":"Escuchar la letra con atención revela mensajes que al principio no notamos."},{"text":"**¿Qué me provoca?** \\"Me da energía, pero esa frase no me gusta: mi hermana y mis compañeras son mucho más que eso.\\""},{"text":"**Conclusión:** \\"La música me gusta, pero no comparto parte del mensaje. Cuando la cante, voy a pensar en lo que digo.\\""}],"answer":"Una reseña con criterio **separa la música del mensaje**, da **razones** y termina con una **decisión personal**.","tip":"No hace falta prohibirse canciones: hace falta escuchar con la cabeza, no solo con los pies."},"id":"s04-art-2-5"},{"fase":"construir","areas":["art"],"cnb":["art:3.1.2"],"ambito":"ser","prompt":"Clasifica cada comentario: ¿muestra una **valoración con criterio** o **no**?","hint":"Una valoración con criterio da razones sobre la música, la letra o lo que provoca, y respeta a las personas.","explain":"Los comentarios con criterio explican por qué y respetan a los demás. Burlarse o seguir la moda sin pensar no es valorar.","type":"sort","props":{"buckets":[{"id":"si","label":"Con criterio","icon":"ThumbsUp","color":"var(--c-ok)"},{"id":"no","label":"Sin criterio","icon":"X","color":"var(--c-maiz-strong)"}],"items":[{"id":"c1","text":"\\"Me gusta porque la marimba y el violín dialogan muy bonito\\"","bucket":"si"},{"id":"c2","text":"\\"La escucho porque todos la escuchan\\"","bucket":"no"},{"id":"c3","text":"\\"El ritmo es bueno, pero la letra se burla de la gente del campo\\"","bucket":"si"},{"id":"c4","text":"\\"Lo que tú escuchas es música de abuelitos, ja, ja\\"","bucket":"no","feedback":"Es una burla hacia la persona, no una opinión con razones."},{"id":"c5","text":"\\"No me gusta mucho, pero reconozco que el grupo toca muy bien\\"","bucket":"si"}]},"id":"s04-art-2-6"},{"fase":"aplicar","areas":["art","fc"],"cnb":["art:3.1.2"],"ambito":"convivir","prompt":"¿Qué música elegirían para el acto de la escuela?","type":"dilemma","props":{"scene":{"icon":"Music","text":"Tu grado prepara un acto sobre el **cuidado de la tierra**. **Sebastián** propone una canción de moda cuya letra se burla de las mujeres. **Ixchel** propone un son de marimba. **Keyla** propone una canción moderna con un mensaje positivo sobre la naturaleza."},"options":[{"id":"a","icon":"ThumbsUp","text":"Usar la canción de moda porque \\"a todos les gusta\\"","consequence":"Algunas compañeras se sienten ofendidas y el mensaje de la canción contradice el acto.","values":["Consumo sin reflexión"],"constructive":false},{"id":"b","icon":"Music","text":"Usar el son de marimba, que conecta con nuestra identidad","consequence":"El público reconoce la música y el acto se siente muy nuestro.","values":["Identidad","Valoración cultural"],"constructive":true},{"id":"c","icon":"Headphones","text":"Escuchar juntos las tres opciones, analizar las letras y combinar la marimba con la canción de mensaje positivo","consequence":"El grupo dialoga, aprende a escuchar con criterio y arma un acto que une tradición y música actual.","values":["Pensamiento crítico","Diálogo","Respeto"],"constructive":true}]},"id":"s04-art-2-7"},{"fase":"aplicar","areas":["art","cnt"],"cnb":["art:3.1.2"],"ambito":"ser","prompt":"Mira la animación sobre el oído. ¿Verdadero o falso?","explain":"Las células del oído que captan el sonido se dañan con volúmenes muy altos por mucho tiempo, y ese daño no se recupera. Cuidar el volumen es parte de disfrutar la música toda la vida.","type":"true-false","props":{"statements":[{"text":"Escuchar música muy fuerte por mucho tiempo puede dañar el oído para siempre.","answer":true},{"text":"Si alguien a tu lado oye la música de tus audífonos, el volumen está bien.","answer":false,"why":"Es señal de que está demasiado fuerte."},{"text":"Tomar descansos y alejarse de las bocinas en una fiesta ayuda a cuidar el oído.","answer":true}]},"id":"s04-art-2-8"},{"fase":"aplicar","areas":["art"],"cnb":["art:3.1.2"],"ambito":"ser","prompt":"Arma una **lista de música con criterio** a partir de las tres fichas suministradas. Explorar música local después es opcional.","type":"project","props":{"goal":"Valorar tres piezas ficticias descritas en fichas autosuficientes, sin buscar grabaciones.","steps":[{"title":"Ficha A","detail":"Son de marimba instrumental, tempo moderado y carácter festivo; no tiene letra."},{"title":"Ficha B","detail":"Canción ficticia con guitarra, tempo lento y letra respetuosa sobre cuidar un río."},{"title":"Ficha C","detail":"Canción ficticia de ritmo rápido cuya letra se burla de las personas del campo."},{"title":"Decide","detail":"Ordena las fichas, marca cuáles usarías en un acto escolar y explica una razón sobre música, mensaje o emoción."}],"evidence":"Tu lista de tres fichas suministradas con una decisión y una razón por cada una.","rubric":["Revisé las tres fichas","Di razones sobre música, mensaje o emoción","Elegí sin burlarme de otros gustos"]},"id":"s04-art-2-9"},{"fase":"comprobar","areas":["art"],"cnb":["art:3.1.2"],"prompt":"¿Qué comentario muestra una **valoración crítica** de una canción?","type":"choice","props":{"options":[{"id":"a","text":"\\"Es la mejor porque es la más famosa\\""},{"id":"b","text":"\\"Me gusta su melodía, pero su letra promueve la violencia y no la comparto\\""},{"id":"c","text":"\\"Esa música es para gente aburrida\\""}],"correct":["b"]},"id":"s04-art-2-10"},{"fase":"comprobar","areas":["art"],"cnb":["art:3.1.2"],"prompt":"Vas a una fiesta con bocinas muy grandes. ¿Qué haces para cuidar tu oído? Elige todas las correctas.","type":"choice","props":{"multiple":true,"options":[{"id":"a","text":"Me alejo de las bocinas"},{"id":"b","text":"Salgo a descansar del ruido de vez en cuando"},{"id":"c","text":"Me pego a la bocina para oír mejor"},{"id":"d","text":"Subo al máximo mis audífonos al volver a casa"}],"correct":["a","b"]},"id":"s04-art-2-11"},{"fase":"reflexionar","ambito":"ser","prompt":"¿Cómo te fue? Sé honesto: aprender es un camino.","areas":["art"],"cnb":["art:3.1.2"],"type":"reflection","props":{"statements":["Describo una pieza por sus instrumentos, tempo, intensidad, compás y carácter","Valoro la música con razones sobre su música, su letra y lo que me provoca","Respeto los gustos de otras personas y cuido mi oído"],"commitments":["Escucharé con atención una pieza nueva cada semana","Pondré atención a las letras que canto","Mantendré un volumen moderado"]},"id":"s04-art-2-12"}],"kind":"materia","area":"art","day":4}},{"missionId":"s04","version":"cnb-sexto-0504f2c41da4f891","lesson":{"id":"s04-mat-5","title":"Armo cuatro sólidos con plantillas preparadas","icon":"Hammer","minutes":15,"gancho":"Tienes cuatro plantillas pequeñas listas para doblar. ¿Cómo puedes convertirlas en un prisma, una pirámide, un cilindro y un cono?","objetivos":["Construir un prisma recto, una pirámide recta, un cilindro y un cono con plantillas preparadas"],"resumen":["Cada kit reutilizable incluye cuatro plantillas mini troqueladas y premarcadas: prisma triangular recto, pirámide cuadrangular recta, cilindro y cono.","Línea punteada significa doblar; números iguales indican bordes que se unen con broches de gancho y felpa o encastres ya instalados.","Prisma y pirámide se forman al doblar caras planas. Cilindro y cono se forman al enrollar una superficie curva y colocar su base o sus bases.","El estudiantado recibe piezas listas para reutilizar: solo dobla o enrolla, alinea y cierra los broches o encastres; no usa tijeras, cuchillas, grapas ni adhesivos."],"media":{"id":"s04-mat-5-kit","kind":"diagram","title":"Kit mini de cuatro sólidos","aspect":"4:3","alt":"Ficha de producción de un kit reutilizable con cuatro plantillas pequeñas, dobleces, números de unión y broches ya instalados.","brief":"Activo de software pendiente: paquete SVG/PDF para proveedor y fabricación, con dielines o líneas de troquel vendor-ready para un kit físico reutilizable. Debe incluir medidas, líneas de corte, dobleces premarcados, números de unión, posiciones de broches y una guía con fotografías o diagramas de un prototipo de ensamblaje. Reemplazo físico normal: 15 juegos para parejas, cada uno con prisma triangular recto, pirámide cuadrangular recta, cilindro y cono de 4 a 6 cm, fabricados una sola vez por un proveedor o taller central en cartulina laminada lavable de 300 g/m² o polipropileno delgado lavable de 0.4 a 0.6 mm. Las piezas van troqueladas y pre-scored o premarcadas, con broches de gancho y felpa de perfil bajo, broches a presión seguros o encastres autoajustables preinstalados; las bases curvas usan pestañas segmentadas con cierres ya instalados. Cada juego incluye cuatro rótulos grandes y se guarda plano en un sobre rotulado del 1 al 15. Lista de fabricación o compra: 1. validar los dielines con un prototipo armado de los cuatro sólidos; 2. producir 15 juegos completos más un juego de repuesto; 3. instalar y probar todos los cierres; 4. redondear esquinas y retirar rebabas o piezas pequeñas sueltas; 5. verificar durabilidad con 30 ciclos de apertura, seguridad sin bordes cortantes y accesibilidad mediante alto contraste, números de unión grandes y marcas táctiles distintas para corte, doblez y cierre; 6. colocar cada juego en su sobre etiquetado y registrar piezas. Rutina docente normal, máximo dos minutos: distribuye un sobre por pareja y al final recoge los 15 sobres usando la lista de piezas; no corta, marca ni aplica adhesivo en cada sesión. Alternativa imprimible de baja tecnología, opcional y no requerida para la lección normal: PDF tamaño carta al 100 % para preparación central anticipada en cartulina; una persona adulta recorta y marca los dobleces fuera del tiempo de clase y coloca encastres reutilizables, nunca cinta de un solo uso por sesión. Registrar el SVG/PDF final y una miniatura PNG en el catálogo de medios. Dimensiones: 1200x900."},"steps":[{"fase":"explorar","areas":["mat"],"cnb":["mat:1.3.7"],"title":"Idea central","prompt":"Con plantillas mini ya preparadas puedes construir cuatro sólidos mediante dobleces, rollos y uniones simples.","type":"explain","props":{"icon":"PackageCheck","body":"Hoy terminarás cuatro modelos: un prisma recto, una pirámide recta, un cilindro y un cono."},"id":"s04-mat-5-1"},{"fase":"construir","areas":["mat"],"cnb":["mat:1.3.7"],"ambito":"conocer","title":"Lee el kit antes de armar","prompt":"Cada pareja recibe un kit durable con cuatro plantillas mini troqueladas y premarcadas, cierres reutilizables ya instalados, cuatro etiquetas y un lápiz.","type":"explain","props":{"icon":"PackageOpen","body":"El kit llega listo desde el sobre rotulado: **no se usan tijeras, cuchillas, grapas, cinta ni adhesivos**.","reveal":[{"icon":"FoldHorizontal","front":"Línea punteada","back":"Haz el **doblez** hacia adentro y presiónalo una vez."},{"icon":"ListOrdered","front":"Números iguales","back":"Los bordes con el mismo número deben quedar juntos."},{"icon":"Link","front":"Cierre preparado","back":"Alinea los números iguales y cierra el broche de **gancho y felpa** o el encastre ya instalado."},{"icon":"Rotate3D","front":"Curva","back":"El rectángulo del cilindro y el sector del cono se **enrollan**; sus bases circulares tienen cierres reutilizables segmentados."}]},"id":"s04-mat-5-2"},{"fase":"construir","areas":["mat"],"cnb":["mat:1.3.7"],"ambito":"hacer","title":"Modelo: cerrar el prisma","prompt":"Observa una demostración breve antes de tocar el kit.","type":"worked-example","props":{"icon":"Box","problem":"La docente arma el prisma triangular recto preparado.","steps":[{"text":"Repasa con los dedos las líneas punteadas para levantar las caras."},{"text":"Junta los bordes con números iguales; las pestañas quedan dentro."},{"text":"Alinea los números iguales y cierra el broche de gancho y felpa o el encastre.","why":"Los cierres preinstalados permiten armar, abrir y guardar el modelo muchas veces."}],"answer":"Queda un prisma recto cerrado, con **dos bases triangulares** y **tres caras laterales rectangulares**.","tip":"Primero da forma; después fija. Así puedes corregir una unión antes de cerrarla."},"id":"s04-mat-5-3"},{"fase":"construir","areas":["mat"],"cnb":["mat:1.3.7"],"prompt":"En una plantilla preparada, ¿qué haces con dos bordes marcados con el número 3?","hint":"Revisa la convención de los números iguales.","explain":"Los números iguales señalan bordes que deben encontrarse; se alinean y se cierra el broche o encastre preparado.","type":"choice","props":{"options":[{"id":"a","text":"Los alineas y cierras el broche o encastre","icon":"Link"},{"id":"b","text":"Los dejas en lados opuestos","icon":"MoveHorizontal","feedback":"El mismo número indica que forman una unión."},{"id":"c","text":"Los arrancas","icon":"X","feedback":"El kit ya tiene la forma necesaria; no se quitan bordes."}],"correct":["a"]},"id":"s04-mat-5-4"},{"fase":"aplicar","areas":["mat"],"cnb":["mat:1.3.7"],"ambito":"hacer","prompt":"Ensambla el **kit preparado de cuatro sólidos** con tu pareja. Trabajen en paralelo: cada integrante arma un modelo plano y uno curvo; luego intercambien para comprobar las uniones.","type":"project","props":{"goal":"Obtener cuatro modelos terminados: un prisma recto, una pirámide recta, un cilindro y un cono.","steps":[{"title":"1 min · Organiza el kit","detail":"Separa las cuatro plantillas reutilizables y las etiquetas; identifica las bases y los cierres preparados."},{"title":"3 min · Prisma y pirámide","detail":"En paralelo, dobla las líneas punteadas, une números iguales y cierra los broches o encastres preinstalados."},{"title":"4 min · Cilindro y cono","detail":"En paralelo, enrolla el rectángulo y el sector; cierra sus uniones y las bases circulares con los broches segmentados."},{"title":"1 min · Etiqueta y compara","detail":"Rotula cada modelo con su nombre. Compara cuáles tienen vértices y cuáles tienen superficie curva."}],"evidence":"Cuatro modelos armados y de pie, cada uno con su etiqueta: prisma recto, pirámide recta, cilindro y cono.","rubric":["Armamos los cuatro modelos terminados","Los broches o encastres cierran sin forzarlos","Cada etiqueta corresponde al sólido","Comparamos vértices y superficies curvas"]},"id":"s04-mat-5-5"},{"fase":"aplicar","areas":["mat"],"cnb":["mat:1.3.7","mat:1.3.3"],"prompt":"Mira tus cuatro modelos y clasifica cada observación.","explain":"Prisma y pirámide tienen solo caras planas; cilindro y cono incluyen una superficie curva.","type":"sort","props":{"buckets":[{"id":"p","label":"Solo caras planas","icon":"Box"},{"id":"c","label":"Tiene superficie curva","icon":"Cylinder"}],"items":[{"id":"a","text":"Prisma recto","bucket":"p"},{"id":"b","text":"Pirámide recta","bucket":"p"},{"id":"c","text":"Cilindro","bucket":"c"},{"id":"d","text":"Cono","bucket":"c"}]},"id":"s04-mat-5-6"},{"fase":"comprobar","areas":["mat"],"cnb":["mat:1.3.7"],"prompt":"¿Qué acción convierte correctamente una plantilla preparada en un sólido?","type":"choice","props":{"options":[{"id":"a","text":"Dar forma, unir números iguales y fijar las pestañas"},{"id":"b","text":"Separar todas las caras antes de doblar"},{"id":"c","text":"Cubrir las líneas punteadas sin doblarlas"}],"correct":["a"]},"id":"s04-mat-5-7"},{"fase":"comprobar","areas":["mat"],"cnb":["mat:1.3.7"],"prompt":"Une cada modelo con la pieza que se enrolla o dobla para darle forma.","type":"match","props":{"pairs":[{"id":"a","left":"Prisma recto","right":"Tira de rectángulos con dos bases congruentes"},{"id":"b","left":"Pirámide recta","right":"Base con triángulos que llegan a la cúspide"},{"id":"c","left":"Cilindro","right":"Rectángulo que se enrolla y dos círculos"},{"id":"d","left":"Cono","right":"Sector circular que se enrolla y un círculo"}]},"id":"s04-mat-5-8"},{"fase":"reflexionar","ambito":"ser","prompt":"¿Cómo te fue? Sé honesto: aprender es un camino.","areas":["mat"],"cnb":[],"type":"reflection","props":{"statements":["Construí un prisma recto y una pirámide recta","Construí un cilindro y un cono","Usé dobleces, rollos y cierres reutilizables","Comparé caras, bases, vértices y superficies"],"commitments":["Desarmaré y guardaré las piezas en su sobre","Pediré ayuda si un cierre preparado se daña","Usaré solo los materiales indicados para cada construcción"]},"id":"s04-mat-5-9"}],"kind":"materia","area":"mat","day":5}},{"missionId":"s04","version":"cnb-sexto-05ee8ef7468dfda5","lesson":{"id":"s04-cnt-3","title":"Cuidado sexual informado y respetuoso","icon":"HeartHandshake","minutes":15,"gancho":"Cuidarse exige informacion precisa, respeto y responsabilidades compartidas.","objetivos":["Evaluar decisiones de salud sexual que integren conducta etica, paternidad responsable y la diferencia entre VIH y SIDA"],"resumen":["Las decisiones eticas respetan consentimiento, intimidad, limites y ausencia de presion; cada cuerpo cambia a su ritmo.","La paternidad responsable comparte cuidado, tiempo, proteccion y recursos.","VIH es el virus; SIDA es una fase avanzada de la infeccion por VIH y no son sinonimos. El tratamiento puede evitar esa progresion."],"media":{"id":"s04-cnt-3-cuidado","kind":"diagram","title":"Decisiones de cuidado","aspect":"16:9","alt":"Tarjetas sobre respeto, responsabilidad compartida e informacion precisa de VIH y SIDA.","brief":"Diagrama educativo 1600x900 con tres paneles: consentimiento e intimidad, paternidad responsable compartida, y VIH versus SIDA. Incluir \\"VIH = virus\\" y \\"SIDA = fase avanzada; no son sinonimos\\". Sin estigma, anatomia explicita ni imagenes de enfermedad; texto grande, alto contraste e iconos descriptivos."},"steps":[{"fase":"explorar","areas":["cnt"],"cnb":["cnt:3.3.1","cnt:3.5.1"],"prompt":"Evalua una decision responsable que una conducta etica, paternidad responsable y la diferencia cientifica entre VIH y SIDA.","type":"explain","props":{"icon":"ShieldCheck","body":"El cuidado combina **respeto y consentimiento**, **responsabilidad compartida** e **informacion confiable**. VIH es el virus; SIDA es una fase avanzada, no un sinonimo."},"id":"s04-cnt-3-1"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:3.3.1","cnt:3.5.1"],"title":"Etica, responsabilidad y precision","prompt":"Relaciona conducta etica y paternidad responsable con informacion correcta sobre el virus VIH y el sindrome SIDA.","type":"explain","props":{"icon":"BookOpenCheck","body":"Una conducta etica respeta limites, consentimiento, intimidad y decisiones sin presion; **cada cuerpo cambia a su ritmo**. La **paternidad responsable** comparte crianza, tiempo, proteccion y recursos. El **VIH** es un virus que afecta el sistema inmunitario; el **SIDA** es una fase avanzada que puede aparecer sin tratamiento. Tener VIH no significa tener SIDA, y el tratamiento puede impedir esa progresion. El VIH no se transmite por abrazar, compartir pupitre ni convivir. Una persona adulta de confianza y un profesional de salud son fuentes confiables para dudas personales."},"id":"s04-cnt-3-2"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:3.3.1","cnt:3.5.1"],"title":"Modelo de decision","prompt":"Observa como evaluar conducta etica, paternidad responsable y la diferencia entre virus VIH y sindrome SIDA.","type":"worked-example","props":{"icon":"SearchCheck","problem":"Un rumor dice que VIH y SIDA son iguales y que el cuidado corresponde a una sola persona.","steps":[{"text":"Se corrige: VIH es el virus; SIDA es una fase avanzada, no son sinonimos."},{"text":"Se rechaza la culpa y se busca informacion de un profesional de salud."},{"text":"La paternidad responsable implica cuidado compartido y respeto."}],"answer":"La respuesta precisa evita estigma y propone responsabilidades eticas."},"id":"s04-cnt-3-3"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:3.3.1","cnt:3.5.1"],"prompt":"Con ayuda, evalua conducta etica, paternidad responsable y la diferencia entre el virus VIH y el sindrome SIDA.","hint":"Busca respeto, responsabilidad compartida y precision cientifica.","explain":"VIH y SIDA no son sinonimos; el cuidado no se basa en culpa ni presion.","type":"choice","props":{"options":[{"id":"a","text":"Respetar limites, compartir la crianza y explicar que VIH es el virus y SIDA una fase avanzada"},{"id":"b","text":"Presionar, culpar y decir que VIH siempre significa SIDA"},{"id":"c","text":"Ocultar informacion y dejar todo el cuidado a una persona"}],"correct":["a"]},"id":"s04-cnt-3-4"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:3.3.1","cnt:3.5.1"],"prompt":"Revisa conducta etica, paternidad responsable y diferencia entre virus VIH y sindrome SIDA.","hint":"Distingue virus de fase avanzada.","explain":"El tratamiento y la orientacion profesional importan; la apariencia no permite determinar la condicion de salud de una persona.","type":"true-false","props":{"statements":[{"text":"El consentimiento y la intimidad forman parte del respeto.","answer":true},{"text":"La paternidad responsable comparte cuidado y recursos.","answer":true},{"text":"VIH y SIDA son exactamente lo mismo.","answer":false}]},"id":"s04-cnt-3-5"},{"fase":"aplicar","areas":["cnt"],"cnb":["cnt:3.3.1","cnt:3.5.1"],"prompt":"Evalua de forma independiente un consejo de salud sexual: incluye conducta etica, paternidad responsable y explica que VIH es un virus y SIDA una fase avanzada, no sinonimos.","type":"short-answer","props":{"minWords":18,"placeholder":"La decision responsable...","model":"Una decision etica respeta limites, consentimiento y responsabilidades compartidas. VIH es el virus; SIDA es una fase avanzada de la infeccion sin tratamiento.","rubric":["Inclui respeto y consentimiento","Explique responsabilidad compartida","Diferencie VIH y SIDA sin estigma"]},"id":"s04-cnt-3-6"},{"fase":"aplicar","areas":["cnt"],"cnb":["cnt:3.3.1","cnt:3.5.1"],"prompt":"Al evaluar conducta etica y paternidad responsable con la diferencia entre virus VIH y sindrome SIDA, ¿que respuesta es correcta?","type":"choice","props":{"options":[{"id":"a","text":"Respeto y cuidado compartido; VIH es el virus y SIDA una fase avanzada que el tratamiento puede prevenir"},{"id":"b","text":"La presion es valida y VIH siempre equivale a SIDA"},{"id":"c","text":"La apariencia revela la condicion de salud y una persona carga todo el cuidado"}],"correct":["a"]},"id":"s04-cnt-3-7"},{"fase":"comprobar","areas":["cnt"],"cnb":["cnt:3.3.1","cnt:3.5.1"],"prompt":"Salida: identifica conducta etica y paternidad responsable junto con la diferencia entre el virus VIH y el sindrome SIDA.","type":"choice","props":{"options":[{"id":"a","text":"Consentimiento y crianza compartida; VIH es virus y SIDA una fase avanzada, no sinonimos"},{"id":"b","text":"Presion y abandono; VIH y SIDA son sinonimos"},{"id":"c","text":"Rumores y culpa sustituyen la informacion profesional"}],"correct":["a"]},"id":"s04-cnt-3-8"},{"fase":"comprobar","areas":["cnt"],"cnb":["cnt:3.3.1","cnt:3.5.1"],"prompt":"Salida nueva: comprueba conducta etica, paternidad responsable y diferencia entre virus VIH y sindrome SIDA.","type":"true-false","props":{"statements":[{"text":"Respetar limites y compartir la crianza son decisiones responsables.","answer":true},{"text":"Una persona con VIH necesariamente tiene SIDA.","answer":false},{"text":"Una fuente confiable o profesional de salud orienta mejor que un rumor.","answer":true}]},"id":"s04-cnt-3-9"}],"kind":"materia","area":"cnt","day":5}},{"missionId":"s04","version":"cnb-sexto-91f54fe2754b4888","lesson":{"id":"s04-fc-2","title":"Revisar con criterios a quienes nos dirigen","icon":"ClipboardCheck","minutes":15,"gancho":"Si alguien de tu comunidad prometió arreglar el camino, ¿cómo sabes si cumplió? ¿Basta con lo que dicen los rumores?","objetivos":["Evaluar un liderazgo con hechos, criterios y propuestas de mejora"],"resumen":["Revisar críticamente un liderazgo es evaluar sus acciones con criterios y hechos, no con rumores ni insultos.","Cinco criterios: ¿consulta antes de decidir?, ¿informa y rinde cuentas?, ¿cumple lo que prometió?, ¿incluye a todas las personas?, ¿respeta las reglas y la ley?","Una buena crítica describe un hecho, lo compara con un criterio y propone una mejora.","La ciudadanía puede revisar a sus autoridades: participar en asambleas, pedir información pública (lo permite la Ley de Acceso a la Información Pública) y votar de forma informada. La Contraloría General de Cuentas revisa el uso del dinero público."],"media":{"id":"s04-fc-2-lista-cotejo","kind":"diagram","title":"La lista para revisar un liderazgo","aspect":"3:4","alt":"Una hoja de lista de cotejo con cinco criterios y casillas de sí o no, y una lupa sobre ella.","brief":"Diagrama tipo hoja de cuaderno con título \\"¿Cómo lidera?\\". Cinco filas con ícono y casillas \\"Sí / No\\": (1) Consulta antes de decidir (ícono de mano levantada); (2) Informa y rinde cuentas (hoja con monedas); (3) Cumple lo que prometió (check); (4) Incluye a todas las personas (grupo diverso); (5) Respeta las reglas y la ley (balanza). Al pie: \\"Hecho → criterio → propuesta\\". Una lupa en la esquina. Estilo limpio, fondo claro, letras grandes. Dimensiones: 900x1200. Accesibilidad: contraste alto, rotulos grandes y legibles; la descripcion visual debe corresponder exactamente al texto alternativo."},"steps":[{"fase":"explorar","areas":["fc"],"cnb":["fc:3.1.1"],"title":"Idea central","prompt":"Revisar un liderazgo con hechos protege la participación y evita rumores o ataques.","type":"explain","props":{"icon":"BookOpenCheck","body":"Revisar críticamente un liderazgo es evaluar sus acciones con criterios y hechos, no con rumores ni insultos."},"id":"s04-fc-2-1"},{"fase":"construir","areas":["fc"],"cnb":["fc:3.1.1"],"ambito":"conocer","prompt":"Se dice en la tienda que \\"el comité se robó el dinero del camino\\". ¿Qué deberías hacer **antes** de repetirlo?","explain":"Un rumor no es una prueba. Para revisar un liderazgo de forma justa, se buscan **hechos**: documentos, informes, preguntas directas. Hoy aprenderás a hacerlo con criterios.","type":"choice","props":{"options":[{"id":"a","text":"Buscar información: preguntar al comité por el informe de gastos","icon":"Search"},{"id":"b","text":"Contárselo a todos los vecinos de inmediato","icon":"Megaphone","feedback":"Si el rumor es falso, se daña a personas inocentes. Primero hay que buscar hechos."},{"id":"c","text":"Escribir un insulto en las redes sociales","icon":"Smartphone","feedback":"Un insulto no revisa nada y puede ser injusto. La crítica útil se basa en hechos."}],"correct":["a"]},"id":"s04-fc-2-2"},{"fase":"construir","areas":["fc"],"cnb":["fc:3.1.1"],"ambito":"conocer","title":"Cinco criterios para revisar un liderazgo","prompt":"**Revisar críticamente** es evaluar las acciones de un líder comparándolas con **criterios** claros. Toca cada criterio.","type":"explain","props":{"icon":"ClipboardCheck","body":"Estos cinco criterios sirven igual para el gobierno escolar, un comité, la municipalidad o el Congreso.","reveal":[{"icon":"Hand","front":"1. Consulta","back":"¿Pregunta y escucha a las personas antes de decidir cosas importantes?"},{"icon":"FileText","front":"2. Rinde cuentas","back":"¿Informa qué hizo, cuánto gastó y en qué? ¿Muestra documentos?"},{"icon":"Check","front":"3. Cumple","back":"¿Hizo lo que prometió? ¿En el tiempo acordado?"},{"icon":"Users","front":"4. Incluye","back":"¿Toma en cuenta a mujeres, jóvenes, personas mayores, personas con discapacidad y a todos los pueblos?"},{"icon":"Scale","front":"5. Respeta la ley","back":"¿Sigue las reglas de la organización y las leyes del país? ¿Deja el cargo al terminar su periodo?"}]},"id":"s04-fc-2-3"},{"fase":"construir","areas":["fc"],"cnb":["fc:3.1.1"],"ambito":"convivir","title":"Crítica útil o ataque","prompt":"Criticar es un **derecho y una responsabilidad** ciudadana, pero hay formas que ayudan y formas que dañan. Toca cada tarjeta.","type":"explain","props":{"icon":"MessageCircle","body":"Una **crítica útil** tiene tres partes: **hecho** (qué pasó) → **criterio** (qué debería pasar) → **propuesta** (cómo mejorar).","reveal":[{"icon":"ThumbsUp","front":"Crítica útil","back":"\\"El comité no ha presentado el informe de gastos en seis meses (hecho). Un buen liderazgo rinde cuentas (criterio). Pedimos que lo presente en la próxima asamblea (propuesta).\\""},{"icon":"X","front":"Ataque","back":"\\"¡Todos los del comité son unos ladrones!\\" No da hechos, generaliza e insulta. No ayuda a mejorar y puede ser injusto."},{"icon":"Ear","front":"Rumor","back":"\\"Dicen que…\\". Información sin fuente ni prueba. Antes de repetirla, hay que verificarla."}]},"id":"s04-fc-2-4"},{"fase":"construir","areas":["fc"],"cnb":["fc:3.1.1"],"prompt":"Clasifica cada comentario sobre un líder: ¿es una **crítica útil** o un **ataque o rumor**?","hint":"Una crítica útil menciona un hecho concreto y, de preferencia, propone algo. Un ataque insulta o generaliza; un rumor no tiene prueba.","explain":"La crítica útil se basa en hechos verificables y busca mejorar; el ataque y el rumor dañan la convivencia y no resuelven nada.","type":"sort","props":{"buckets":[{"id":"ok","label":"Crítica útil","icon":"ThumbsUp","color":"var(--c-ok)"},{"id":"no","label":"Ataque o rumor","icon":"X","color":"var(--c-maiz-strong)"}],"items":[{"id":"c1","text":"\\"La presidenta prometió reparar la cancha en marzo y en junio sigue igual. Proponemos pedirle un calendario.\\"","bucket":"ok"},{"id":"c2","text":"\\"Dicen que el alcalde tiene tres carros nuevos.\\"","bucket":"no","feedback":"\\"Dicen que\\" sin fuente es un rumor. Habría que verificarlo con información pública."},{"id":"c3","text":"\\"Ese presidente del grado es un tonto.\\"","bucket":"no"},{"id":"c4","text":"\\"En la asamblea no dejaron hablar a las mujeres. Sugerimos una lista de turnos para que todos opinen.\\"","bucket":"ok"},{"id":"c5","text":"\\"Todos los políticos son iguales.\\"","bucket":"no","feedback":"Generaliza y no permite distinguir a quien hace bien su trabajo de quien no."}]},"id":"s04-fc-2-5"},{"fase":"construir","areas":["fc"],"cnb":["fc:3.1.1"],"ambito":"hacer","title":"Ejemplo resuelto: revisar al comité de agua","prompt":"Así se usa la lista de cinco criterios con un caso. Revela cada paso.","type":"worked-example","props":{"icon":"Droplets","problem":"Supongamos estos **hechos** sobre el comité de agua de la aldea Los Cipreses: (1) hizo asamblea antes de subir la cuota; (2) presentó un informe de gastos con recibos; (3) prometió reparar la tubería en un mes y tardó cuatro; (4) solo participan hombres en la directiva; (5) cambió a su directiva cuando terminó su periodo.","steps":[{"text":"Criterio 1, consulta: **sí** (hizo asamblea)."},{"text":"Criterio 2, rinde cuentas: **sí** (informe con recibos)."},{"text":"Criterio 3, cumple: **no del todo** (tardó cuatro meses en lugar de uno)."},{"text":"Criterio 4, incluye: **no** (no hay mujeres en la directiva).","why":"Las mujeres usan y acarrean el agua a diario: su voz es necesaria en el comité."},{"text":"Criterio 5, respeta las reglas: **sí** (cambió la directiva a tiempo)."}],"answer":"El comité cumple **3 de 5** criterios: es un liderazgo mayormente democrático que debe mejorar en **cumplir a tiempo** e **incluir a mujeres**.","tip":"Una revisión justa reconoce lo que se hace bien y propone mejoras concretas."},"id":"s04-fc-2-6"},{"fase":"aplicar","areas":["fc"],"cnb":["fc:3.1.1"],"ambito":"hacer","prompt":"Revisa al gobierno escolar de una escuela con los cinco criterios. **Hechos:** eligió los proyectos votando en cada grado; no ha informado cuánto dinero recaudó en la kermés; terminó el mural que prometió; su comisión de deportes incluye niñas y niños; respeta el reglamento de la escuela. ¿Cuántos criterios **cumple**?","explain":"Consulta ✔, rinde cuentas ✘, cumple ✔, incluye ✔, respeta reglas ✔ → cumple **4 de 5**. Debe mejorar en informar el dinero de la kermés.","type":"number-input","props":{"answer":4,"unit":"de 5 criterios","misconceptions":[{"value":5,"msg":"Revisa el criterio de rendir cuentas: ¿informó el dinero de la kermés?"},{"value":3,"msg":"Revisa otra vez: votar en cada grado es consultar, y terminar el mural es cumplir."}]},"id":"s04-fc-2-7"},{"fase":"aplicar","areas":["fc"],"cnb":["fc:3.1.1"],"ambito":"conocer","prompt":"Lee sobre las herramientas que tiene la ciudadanía para revisar a las autoridades del país y responde.","type":"reading","props":{"genre":"Texto informativo","heading":"La ciudadanía también vigila","passage":"En Guatemala, la población elige por voto a sus autoridades: al presidente o presidenta, a los diputados del Congreso y a los alcaldes y concejos municipales. Estos cargos duran **cuatro años**. Pero la participación ciudadana no termina el día de la elección.\\n\\nLa **Ley de Acceso a la Información Pública** permite que cualquier persona pida a las instituciones del Estado información sobre cómo usan el dinero y qué proyectos realizan. La **Contraloría General de Cuentas** revisa el uso de los fondos públicos. En las comunidades, los **COCODE** y las asambleas permiten que los vecinos pregunten y propongan.\\n\\nCon esa información, la gente puede revisar si sus autoridades consultan, rinden cuentas, cumplen, incluyen a todos y respetan la ley. Así, en la próxima elección, el voto puede ser **informado** y no solo por simpatía o por un regalo.","questions":[{"q":"¿Cada cuánto se elige a las autoridades nacionales y municipales en Guatemala?","options":[{"id":"a","text":"Cada cuatro años"},{"id":"b","text":"Cada año"},{"id":"c","text":"Nunca, son para siempre"}],"correct":"a"},{"q":"¿Qué permite la Ley de Acceso a la Información Pública?","options":[{"id":"a","text":"Que cualquier persona pida información sobre cómo el Estado usa el dinero y sus proyectos"},{"id":"b","text":"Que las autoridades escondan sus gastos"},{"id":"c","text":"Que solo los diputados sepan lo que pasa"}],"correct":"a"},{"q":"¿Qué significa votar de forma \\"informada\\"?","options":[{"id":"a","text":"Elegir después de revisar lo que cada candidato hizo y propone"},{"id":"b","text":"Votar por quien regala más cosas"},{"id":"c","text":"Votar por el más famoso"}],"correct":"a","why":"Un voto informado se basa en hechos y propuestas, no en regalos ni simpatías."}]},"id":"s04-fc-2-8"},{"fase":"aplicar","areas":["fc"],"cnb":["fc:3.1.1"],"ambito":"hacer","prompt":"Vas a **entrevistar** a una persona que lidera una organización de tu comunidad (COCODE, comité, cooperativa, iglesia, gobierno escolar). Escribe **tres preguntas abiertas** basadas en los criterios, y di qué criterio revisa cada una.","type":"short-answer","props":{"minWords":30,"placeholder":"1. ¿…? (criterio: …)","model":"1. ¿Cómo toman las decisiones importantes en el comité? (criterio: consulta) 2. ¿De qué forma informan a la comunidad sobre el dinero y los proyectos? (criterio: rinde cuentas) 3. ¿Cómo participan las mujeres y los jóvenes en la directiva? (criterio: incluye). Anotaré las respuestas en mi cuaderno con la fecha de la entrevista.","rubric":["Escribí tres preguntas abiertas (no se responden solo con sí o no)","Cada pregunta revisa un criterio distinto","Las preguntas son respetuosas","Dije cómo registraré las respuestas"]},"id":"s04-fc-2-9"},{"fase":"comprobar","areas":["fc"],"cnb":["fc:3.1.1"],"prompt":"¿Cuál de estas frases es una **crítica útil** al gobierno escolar?","type":"choice","props":{"options":[{"id":"a","text":"\\"No han informado cuánto se recaudó en la venta; pedimos que lo publiquen en el periódico mural.\\""},{"id":"b","text":"\\"El gobierno escolar no sirve para nada.\\""},{"id":"c","text":"\\"Dicen que la tesorera se quedó con el dinero.\\""}],"correct":["a"]},"id":"s04-fc-2-10"},{"fase":"comprobar","areas":["fc"],"cnb":["fc:3.1.1"],"prompt":"Une cada hecho con el **criterio** que revisa.","type":"match","props":{"leftTitle":"Hecho","rightTitle":"Criterio","pairs":[{"id":"h1","left":"El alcalde publicó el costo del puente","right":"Rinde cuentas"},{"id":"h2","left":"La presidenta preguntó a los vecinos antes de decidir","right":"Consulta"},{"id":"h3","left":"El comité terminó la obra en la fecha prometida","right":"Cumple"},{"id":"h4","left":"La directiva tiene mujeres, jóvenes y ancianos","right":"Incluye"}]},"id":"s04-fc-2-11"},{"fase":"reflexionar","ambito":"ser","prompt":"¿Cómo te fue? Sé honesto: aprender es un camino.","areas":["fc"],"cnb":["fc:3.1.1"],"type":"reflection","props":{"statements":["Distingo el liderazgo democrático del autoritario","Reviso un liderazgo con cinco criterios y hechos","Diferencio una crítica útil de un ataque o un rumor"],"commitments":["Haré mi entrevista a una persona que lidera en mi comunidad","Antes de repetir un rumor, buscaré si es verdad","Cuando dirija un grupo, consultaré e informaré a todos"]},"id":"s04-fc-2-12"}],"kind":"materia","area":"fc","day":5}},{"missionId":"s04","version":"cnb-sexto-18893eb8c2965e10","lesson":{"id":"s04-ef-2","title":"Cinco formas de lanzar","icon":"Send","minutes":15,"gancho":"En el recreo, para pasar la pelota a alguien cercano, a alguien lejos o por encima de un compañero alto, ¿usas siempre el mismo lanzamiento?","objetivos":["Elegir y ejecutar distintas formas de lanzamiento en una estructura ritmica sencilla segun la situacion"],"resumen":["Rodado: la pelota va por el suelo; es seguro y preciso para distancias cortas (como en el boliche).","A dos manos de pecho: desde el pecho, pulgares detrás de la pelota, se empuja estirando los brazos; rápido y preciso para pases cortos y medios.","Por arriba del hombro (directo): con una mano, para distancias largas. En suspensión: el mismo lanzamiento pero saltando, para lanzar por encima de un defensor.","Con pique: la pelota bota una vez en el suelo antes de llegar al compañero, más cerca de él que de ti; sirve para pasar por debajo de los brazos de un defensor.","Lanzar en movimiento exige coordinar pasos y brazos; practicar con cada mano te hace más completo.","Una estructura ritmica sencilla de cuatro tiempos puede ordenar preparar, apuntar, lanzar y recibir."],"media":{"id":"s04-ef-2-cinco","kind":"animation","title":"Cinco lanzamientos","aspect":"16:9","duration":60,"alt":"Cinco escenas cortas de dos niñas pasándose una pelota: rodando por el suelo, desde el pecho con dos manos, por arriba del hombro, saltando y con un bote en el suelo.","brief":"Animación 2D de 60 s, cinco escenas de 11 s con el mismo par de personajes (una niña maya con trenza y una niña garífuna, ropa deportiva genérica). (1) Rodado: flexión de rodillas, balanceo del brazo abajo, pelota rodando. (2) Pecho a dos manos: pulgares atrás, extensión de brazos, muñecas giran hacia afuera. (3) Por arriba del hombro: pase largo, técnica de 5 pasos. (4) En suspensión: carrera, salto con impulso, lanzamiento en el punto más alto, por encima de un defensor. (5) Con pique: bote en el suelo a unos dos tercios del camino hacia la compañera, por debajo de los brazos de un defensor. Línea punteada de trayectoria en cada caso y rótulo con el nombre. Accesibilidad: subtitulos completos para toda voz y transcripcion audiovisual; rotulos grandes, legibles y de alto contraste."},"steps":[{"fase":"explorar","areas":["ef"],"cnb":["ef:2.1.3"],"title":"Idea central","prompt":"Participar en equipo exige elegir el lanzamiento adecuado y adaptarlo a cada situación.","type":"explain","props":{"icon":"BookOpenCheck","body":"Rodado: la pelota va por el suelo; es seguro y preciso para distancias cortas (como en el boliche)."},"id":"s04-ef-2-1"},{"fase":"construir","areas":["ef"],"cnb":["ef:2.1.3"],"ambito":"conocer","prompt":"Un compañero muy alto está entre tú y tu amiga, con los brazos levantados. ¿Cómo le pasarías la pelota?","explain":"Una buena opción es un pase **con pique**: la pelota bota en el suelo y pasa **por debajo** de sus brazos. Hoy conocerás cinco formas de lanzar y cuándo usar cada una.","type":"choice","props":{"options":[{"id":"a","text":"Directo a la altura de su cara","icon":"ArrowRight","feedback":"Pasaría justo por donde están sus manos: la puede interceptar."},{"id":"b","text":"Haciéndola botar en el suelo para que pase por debajo de sus brazos","icon":"ArrowDown"},{"id":"c","text":"Esperar a que se vaya","icon":"Hourglass","feedback":"En un juego no hay tiempo de esperar: busca una forma de lanzar que lo supere."}],"correct":["b"]},"id":"s04-ef-2-2"},{"fase":"construir","areas":["ef"],"cnb":["ef:2.1.3"],"ambito":"hacer","title":"Tres lanzamientos básicos","prompt":"Mira la animación y toca cada tarjeta. Prueba el movimiento con una pelota imaginaria.","type":"explain","props":{"icon":"Target","body":"Cada lanzamiento tiene su técnica y su momento. Empieza por estos tres.","reveal":[{"icon":"CircleDot","front":"Rodado","back":"Dobla las rodillas, balancea el brazo **por abajo** y suelta la pelota **cerca del suelo** para que ruede. Seguro y preciso de cerca."},{"icon":"Hand","front":"A dos manos de pecho","back":"Pelota frente al pecho, **pulgares detrás**, codos abiertos. **Estira los brazos** hacia tu compañero y al final gira las muñecas hacia afuera. Rápido y preciso."},{"icon":"ArrowUpRight","front":"Por arriba del hombro","back":"Con **una mano**, como aprendiste el martes: de lado, pie contrario adelante, codo alto, giro. Para **distancias largas**."}]},"id":"s04-ef-2-3"},{"fase":"construir","areas":["ef"],"cnb":["ef:1.4.14","ef:2.1.3"],"ambito":"hacer","title":"Defensas y ritmo para coordinar pases","prompt":"Elige una forma de lanzamiento y coordinala con una estructura ritmica sencilla. Toca cada tarjeta.","type":"explain","props":{"icon":"Shield","body":"Segun los brazos del defensor, pasa por arriba o por abajo. Para coordinar cualquier forma, repite **cuatro tiempos**: 1 preparar, 2 apuntar, 3 lanzar y 4 recibir.","reveal":[{"icon":"ArrowDown","front":"Con pique","back":"Lanza la pelota hacia el suelo para que **bote una vez** y llegue a tu compañero a la altura de la cintura. El bote va **más cerca de quien recibe** (a unos dos tercios del camino). Puedes hacerlo a dos manos o a una mano."},{"icon":"ArrowUp","front":"En suspensión","back":"Corre, **salta** con impulso y lanza por arriba del hombro en el **punto más alto** del salto. Así lanzas por encima de un defensor."},{"icon":"Footprints","front":"En movimiento","back":"Lanzar mientras te desplazas exige coordinar pasos y brazo: primero camina, luego trota y al final corre."},{"icon":"RefreshCw","front":"Alternar manos","back":"Practica cada lanzamiento de una mano con la **derecha** y con la **izquierda**: tendrás más opciones en el juego."},{"icon":"ListOrdered","front":"Estructura de cuatro tiempos","back":"**1 preparar, 2 apuntar, 3 lanzar, 4 recibir.** Luego el patron comienza otra vez."}]},"id":"s04-ef-2-4"},{"fase":"construir","areas":["ef"],"cnb":["ef:2.1.3"],"ambito":"hacer","title":"Ejemplo resuelto: elegir el lanzamiento","prompt":"Mira cómo Keyla decide qué lanzamiento usar en cuatro momentos de un juego de pases.","type":"worked-example","props":{"icon":"Brain","problem":"Keyla tiene la pelota en cuatro situaciones distintas. ¿Qué lanzamiento conviene en cada una?","steps":[{"text":"**Situación 1:** su compañera está a 3 pasos y no hay nadie en medio → **a dos manos de pecho**.","why":"Es rápido, preciso y fácil de recibir a corta distancia."},{"text":"**Situación 2:** un defensor está en medio con los brazos arriba → **con pique**, botando la pelota cerca de su compañera.","why":"La pelota pasa por debajo de los brazos del defensor."},{"text":"**Situación 3:** su compañero está libre, lejos, al otro lado de la cancha → **por arriba del hombro**.","why":"Es el lanzamiento que llega más lejos."},{"text":"**Situación 4:** un defensor bajito está muy cerca, con los brazos abajo → **en suspensión**: salta y lanza por encima."}],"answer":"Keyla elige según **distancia**, **obstáculos** y **posición de los brazos del defensor**.","tip":"Antes de lanzar, mira a tu compañero y al defensor: la decisión es parte de la técnica."},"id":"s04-ef-2-5"},{"fase":"construir","areas":["ef"],"cnb":["ef:1.4.14","ef:2.1.3"],"ambito":"conocer","prompt":"Une cada lanzamiento o estructura ritmica con su descripcion.","hint":"Recuerda por donde va la pelota y que ocurre en los cuatro tiempos.","explain":"Cada forma resuelve una situacion; la estructura preparar, apuntar, lanzar y recibir coordina el pase.","type":"match","props":{"leftTitle":"Forma o estructura","rightTitle":"Cómo es","pairs":[{"id":"r","left":"Rodado","right":"La pelota va por el suelo"},{"id":"p","left":"A dos manos de pecho","right":"Se empuja desde el pecho estirando los brazos"},{"id":"h","left":"Por arriba del hombro","right":"Con una mano, para llegar lejos"},{"id":"s","left":"En suspensión","right":"Se lanza en el punto más alto de un salto"},{"id":"q","left":"Con pique","right":"La pelota bota una vez antes de llegar"},{"id":"t","left":"Cuatro tiempos","right":"Preparar, apuntar, lanzar y recibir"}]},"id":"s04-ef-2-6"},{"fase":"aplicar","areas":["ef"],"cnb":["ef:1.4.14","ef:2.1.3"],"ambito":"hacer","prompt":"En pareja, despejen la zona y usen una pelota suave. **Calentamiento:** muevan hombros y muñecas sin pelota. Hagan **8 pases en total**, cada uno con cuatro tiempos: 1 preparar, 2 apuntar, 3 lanzar y 4 recibir. Incluyan uno rodado, uno de pecho, uno por arriba del hombro, uno en suspensión sin carrera y uno con pique; repitan tres formas que la pareja elija. Quien recibe pone una marca por pase controlado. **Poco espacio:** trabajen contra una pared y omitan el salto. **Adaptación:** practiquen sentados y representen la suspensión elevando el brazo. **Vuelta a la calma:** caminen, respiren y estiren los brazos.","type":"pulse-lab","props":{"seconds":15,"rounds":[{"label":"En reposo"},{"label":"Después del calentamiento","exercise":{"name":"Movilidad de hombros y muñecas","icon":"RotateCw","seconds":30}},{"label":"Después de los 8 pases","exercise":{"name":"Cinco formas con registro de control","icon":"Target","seconds":120}}]},"id":"s04-ef-2-7"},{"fase":"aplicar","areas":["ef"],"cnb":["ef:2.1.3"],"ambito":"hacer","prompt":"En el pase con pique, la pelota de Ana llega a los tobillos de su compañero y él no la puede atrapar. ¿Qué debe cambiar?","explain":"El bote debe ir **más cerca de quien recibe** (a unos dos tercios del camino) para que la pelota suba hasta su cintura.","type":"choice","props":{"options":[{"id":"a","text":"Hacer que la pelota bote más cerca de su compañero"},{"id":"b","text":"Hacer que la pelota bote justo frente a sus propios pies","feedback":"Así la pelota pierde fuerza y llega aún más baja."},{"id":"c","text":"Lanzar la pelota sin que bote","feedback":"Entonces ya no sería un pase con pique."}],"correct":["a"]},"id":"s04-ef-2-8"},{"fase":"comprobar","areas":["ef"],"cnb":["ef:1.4.14","ef:2.1.3"],"prompt":"En la estructura de cuatro tiempos, necesitas un pase corto y seguro hacia una companera cercana y libre. ¿Que accion corresponde al tiempo 3?","type":"choice","props":{"options":[{"id":"a","text":"Lanzar a dos manos desde el pecho"},{"id":"b","text":"En suspensión, con salto"},{"id":"c","text":"Por arriba del hombro con toda la fuerza"}],"correct":["a"]},"id":"s04-ef-2-9"},{"fase":"comprobar","areas":["ef"],"cnb":["ef:1.4.14","ef:2.1.3"],"prompt":"Comprueba formas de lanzamiento y la estructura ritmica sencilla de cuatro tiempos.","type":"true-false","props":{"statements":[{"text":"Preparar, apuntar, lanzar y recibir puede repetirse como estructura de cuatro tiempos.","answer":true},{"text":"El lanzamiento en suspensión se hace en el punto más alto de un salto.","answer":true},{"text":"El lanzamiento rodado es el mejor para pasar por encima de un defensor alto.","answer":false,"why":"El rodado va por el suelo; para superar a un defensor alto conviene el pique o, si tiene los brazos abajo, la suspensión."}]},"id":"s04-ef-2-10"},{"fase":"reflexionar","ambito":"ser","prompt":"¿Cómo te fue? Sé honesto: aprender es un camino.","areas":["ef"],"cnb":["ef:2.1.3"],"type":"reflection","props":{"statements":["Lanzo con todo el cuerpo y ajusto la fuerza según la distancia","Reconozco cinco formas de lanzar","Elijo el lanzamiento según la situación del juego"],"commitments":["Practicaré el tiro a la troje y anotaré mis aciertos","Lanzaré también con mi mano no dominante","Revisaré que no haya nadie en la zona antes de lanzar"]},"id":"s04-ef-2-11"}],"kind":"materia","area":"ef","day":5}},{"missionId":"s04","version":"cnb-sexto-e47c97d9241183dc","lesson":{"id":"s04-cnt-2","title":"Ovogénesis y espermatogénesis","icon":"GitCompare","minutes":15,"gancho":"Dos procesos forman células reproductoras, pero no siguen el mismo camino.","objetivos":["Distinguir la ovogénesis de la espermatogénesis por el lugar, el proceso y las células que producen"],"resumen":["La ovogénesis ocurre en los ovarios y produce una célula funcional grande y cuerpos polares.","La espermatogénesis ocurre en los testículos y produce espermatozoides.","En el lenguaje común se dice «óvulo»; con precisión, suele liberarse un ovocito secundario, y su meiosis II se completa solo si hay fecundación."],"media":{"id":"s04-cnt-2-gametogénesis","kind":"diagram","title":"Comparación de gametogénesis","aspect":"16:9","alt":"Dos columnas comparan ovogénesis y espermatogénesis con células esquemáticas.","brief":"Diagrama educativo 1600x900 en dos columnas. Ovogenesis: ovario, una célula funcional grande, cuerpos polares, ovocito secundario y nota de meiosis II. Espermatogenesis: testículo y varios espermatozoides pequeños y móviles. Sin anatomía explícita; texto grande, alto contraste y formas además de color."},"steps":[{"fase":"explorar","areas":["cnt"],"cnb":["cnt:3.2.1"],"prompt":"Hoy compararás dos procesos que forman células reproductoras, llamadas gametos. Fíjate en dónde ocurren y qué producen.","type":"explain","props":{"icon":"GitCompare","body":"Los dos procesos usan un tipo de división celular, pero cambian el lugar, el ritmo y el resultado."},"id":"s04-cnt-2-1"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:3.2.1"],"prompt":"Lee las diferencias entre los dos procesos.","type":"explain","props":{"icon":"Microscope","body":"La **ovogénesis** ocurre en los ovarios. Reparte el citoplasma de forma desigual: queda una célula funcional grande y unos cuerpos polares. La **espermatogénesis** ocurre en los testículos y forma espermatozoides pequeños. Del ovario, el **ovocito secundario** puede ser liberado; su última división (meiosis II) se completa solo si ocurre la fecundación. «Óvulo» es un término común y simplificado para nombrarlo."},"id":"s04-cnt-2-2"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:3.2.1"],"title":"Comparar en dos columnas","prompt":"Mira cómo se comparan los dos procesos.","type":"worked-example","props":{"icon":"Columns2","problem":"Para cada proceso: ¿dónde ocurre, qué produce y en qué se diferencian?","steps":[{"text":"Ovogénesis: en los ovarios; una célula funcional grande y cuerpos polares."},{"text":"Espermatogénesis: en los testículos; espermatozoides pequeños."},{"text":"La diferencia no es solo el nombre: cambia cómo se reparte el citoplasma y qué células resultan."}],"answer":"Los dos procesos forman gametos por caminos diferentes."},"id":"s04-cnt-2-3"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:3.2.1"],"prompt":"Une cada proceso o célula con lo que le corresponde. Si lo necesitas, pide una pista.","hint":"Busca el lugar y el resultado.","explain":"La ovogénesis no produce cuatro células funcionales iguales.","type":"match","props":{"pairs":[{"id":"a","left":"Ovogénesis en los ovarios","right":"Una célula funcional grande y cuerpos polares"},{"id":"b","left":"Espermatogénesis en los testículos","right":"Espermatozoides pequeños"},{"id":"c","left":"Ovocito secundario","right":"Puede ser liberado; su meiosis II se completa solo si ocurre la fecundación"}]},"id":"s04-cnt-2-4"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:3.2.1"],"prompt":"¿Qué opción compara bien los dos procesos?","hint":"No confundas la palabra común «óvulo» con la etapa precisa de la célula.","explain":"La opción correcta diferencia el lugar y el resultado.","type":"choice","props":{"options":[{"id":"a","text":"Ovogénesis: ovarios, ovocito. Espermatogénesis: testículos, espermatozoides"},{"id":"b","text":"Los dos ocurren solo en los ovarios"},{"id":"c","text":"Los dos producen células idénticas"}],"correct":["a"]},"id":"s04-cnt-2-5"},{"fase":"aplicar","areas":["cnt"],"cnb":["cnt:3.2.1"],"title":"Ahora hazlo tú","prompt":"Compara con tus palabras la ovogénesis y la espermatogénesis. Incluye dónde ocurre cada una y qué células produce.","type":"short-answer","props":{"minWords":24,"placeholder":"La ovogénesis… La espermatogénesis…","model":"La ovogénesis ocurre en los ovarios y deja una célula funcional grande con cuerpos polares; la espermatogénesis ocurre en los testículos y forma varios espermatozoides pequeños y móviles.","rubric":["Comparé el lugar","Diferencié los resultados","Usé los términos correctos"]},"id":"s04-cnt-2-6"},{"fase":"aplicar","areas":["cnt"],"cnb":["cnt:3.2.1"],"prompt":"Al comparar la ovogénesis (en los ovarios) y la espermatogénesis (en los testículos), ¿qué diferencia es importante?","type":"choice","props":{"options":[{"id":"a","text":"El lugar y el tipo de células que resultan: un ovocito o espermatozoides"},{"id":"b","text":"Solo el color de la célula"},{"id":"c","text":"No hay ninguna diferencia"}],"correct":["a"]},"id":"s04-cnt-2-7"},{"fase":"comprobar","areas":["cnt"],"cnb":["cnt:3.2.1"],"prompt":"¿Qué opción distingue bien los dos procesos?","type":"choice","props":{"options":[{"id":"a","text":"Ovogénesis, en los ovarios: una célula funcional grande y cuerpos polares. Espermatogénesis, en los testículos: espermatozoides"},{"id":"b","text":"Ovogénesis en los testículos; espermatogénesis en los ovarios"},{"id":"c","text":"Los dos procesos producen resultados idénticos"}],"correct":["a"]},"id":"s04-cnt-2-8"},{"fase":"comprobar","areas":["cnt"],"cnb":["cnt:3.2.1"],"prompt":"Lee cada frase y decide si es verdadera o falsa. Así distingues los dos procesos.","type":"true-false","props":{"statements":[{"text":"La ovogénesis ocurre en los ovarios.","answer":true},{"text":"La espermatogénesis forma espermatozoides en los testículos.","answer":true},{"text":"La meiosis II del ovocito siempre termina antes de cualquier fecundación.","answer":false}]},"id":"s04-cnt-2-9"}],"kind":"materia","area":"cnt","day":3}},{"missionId":"s04","version":"cnb-sexto-ab746190bfd4c540","lesson":{"id":"s04-mat-1","title":"Prismas y pirámides: las bases deciden","icon":"Box","minutes":13,"gancho":"Una troje para guardar maíz, una caja y el techo de una torre. ¿Cómo sabes si un sólido es prisma o pirámide?","objetivos":["Clasificar y nombrar prismas y pirámides a partir de sus bases"],"resumen":["Prisma: tiene DOS bases congruentes y paralelas. En un prisma recto, las caras laterales son rectángulos; en un prisma oblicuo, las caras laterales son paralelogramos inclinados.","Pirámide: tiene UNA base; sus caras laterales son triángulos que se juntan en la cúspide.","Se nombran por el polígono de la base: prisma triangular, prisma hexagonal, pirámide cuadrangular, pirámide pentagonal…","Una pirámide tiene tantas caras laterales como lados tiene su base; un prisma también."],"media":{"id":"s04-mat-1-bases","kind":"diagram","title":"Prismas y pirámides lado a lado","aspect":"16:9","alt":"Arriba, tres prismas rectos (triangular, rectangular y hexagonal) y un prisma oblicuo, con sus dos bases pintadas de azul. Abajo, tres pirámides con su única base pintada de naranja.","brief":"Diagrama en dos filas. Fila de arriba \\"Prismas rectos: 2 bases\\": prisma triangular, rectangular y hexagonal con sus dos bases coloreadas de azul y caras laterales rectangulares en gris claro; al final, un prisma oblicuo con caras laterales en forma de paralelogramo. Fila de abajo \\"Pirámides: 1 base\\": pirámide triangular, cuadrangular y hexagonal con la base en naranja y caras triangulares en gris, cúspide marcada con punto. Debajo de cada sólido, su nombre. Aristas ocultas punteadas. Fondo blanco. Dimensiones: 1600x900. Accesibilidad: contraste alto, rotulos grandes y legibles; la descripcion visual debe corresponder exactamente al texto alternativo."},"steps":[{"fase":"explorar","areas":["mat"],"cnb":["mat:1.3.3"],"title":"Idea central","prompt":"Observa cómo las bases permiten elegir el soporte para un cartel de la campaña.","type":"explain","props":{"icon":"Box","body":"Un prisma tiene dos bases congruentes y paralelas; una pirámide tiene una base y termina en una cúspide. El polígono de la base da nombre al sólido."},"id":"s04-mat-1-1"},{"fase":"construir","areas":["mat"],"cnb":["mat:1.3.3"],"ambito":"conocer","prompt":"Pones una caja de cartón y un adorno en forma de pirámide sobre la mesa. ¿Cuál tiene **arriba** una cara **igual** a la que lo sostiene abajo?","explain":"La caja tiene una cara igual arriba y abajo: **dos bases**. La pirámide termina en punta: tiene **una sola base**.","type":"choice","props":{"options":[{"id":"a","text":"La caja","icon":"Box"},{"id":"b","text":"La pirámide","icon":"Triangle","feedback":"La pirámide termina en una punta; arriba no tiene cara."},{"id":"c","text":"Ninguna de las dos","icon":"X","feedback":"Mira la tapa de la caja: es igual al fondo."}],"correct":["a"]},"id":"s04-mat-1-2"},{"fase":"construir","areas":["mat"],"cnb":["mat:1.3.3"],"ambito":"conocer","title":"Las bases dan el nombre","prompt":"La **base** es la cara que \\"sostiene\\" al sólido y le da su nombre. Contar las bases te dice si es prisma o pirámide. Toca cada tarjeta.","type":"explain","props":{"icon":"Layers","body":"Primero cuenta las bases; después mira qué polígono son.","reveal":[{"icon":"Box","front":"Prisma","back":"**Dos bases** congruentes y paralelas. En los prismas **rectos**, las caras laterales son rectángulos; en los **oblicuos**, son paralelogramos inclinados."},{"icon":"Triangle","front":"Pirámide","back":"**Una base**. Caras laterales: **triángulos** que se juntan en un punto, la **cúspide**."},{"icon":"Tag","front":"Apellido","back":"El polígono de la base es el \\"apellido\\": base de 6 lados → prisma **hexagonal** o pirámide **hexagonal**."}]},"id":"s04-mat-1-3"},{"fase":"construir","areas":["mat"],"cnb":["mat:1.3.3"],"prompt":"Clasifica estos objetos: ¿son **prismas** o **pirámides**?","hint":"Pregúntate: ¿tiene dos bases iguales (prisma) o termina en punta (pirámide)?","explain":"Dos bases congruentes → prisma. Una base y cúspide → pirámide.","type":"sort","props":{"buckets":[{"id":"pr","label":"Prisma","icon":"Box","color":"var(--area-mat)"},{"id":"pi","label":"Pirámide","icon":"Triangle","color":"var(--c-maiz-strong)"}],"items":[{"id":"a","text":"Una caja de cardamomo","bucket":"pr"},{"id":"b","text":"El techo en punta de una torre de base cuadrada","bucket":"pi"},{"id":"c","text":"Un lápiz de 6 caras sin sacarle punta","bucket":"pr"},{"id":"d","text":"Una tienda de campaña con frente triangular","bucket":"pr","feedback":"Tiene dos triángulos congruentes (frente y atrás): es un prisma triangular acostado."},{"id":"e","text":"Un adorno de 4 caras triangulares iguales","bucket":"pi","feedback":"Es una pirámide triangular: cualquier cara puede servir de base."}]},"id":"s04-mat-1-4"},{"fase":"construir","areas":["mat"],"cnb":["mat:1.3.3"],"ambito":"hacer","title":"Ejemplo resuelto: ponerle nombre","prompt":"Así se nombra un sólido en dos pasos.","type":"worked-example","props":{"icon":"Tag","problem":"Una troje moderna tiene **dos hexágonos** congruentes, uno abajo y otro arriba, unidos perpendicularmente por **6 rectángulos**. ¿Cómo se llama?","steps":[{"text":"¿Cuántas bases? **Dos** hexágonos congruentes y paralelos → es un **prisma**."},{"text":"¿Qué polígono es la base? Un **hexágono** (6 lados)."},{"text":"Nombre completo: **prisma hexagonal recto**.","why":"Tiene 6 caras laterales rectangulares, una por cada lado de la base."}],"answer":"Es un **prisma hexagonal recto**.","tip":"Una pirámide con base de 5 lados sería una pirámide pentagonal, con 5 triángulos alrededor."},"id":"s04-mat-1-5"},{"fase":"construir","areas":["mat"],"cnb":["mat:1.3.3"],"prompt":"Une cada descripción con el nombre del sólido.","hint":"Dos bases → prisma; una base con triángulos → pirámide. Luego mira el polígono.","explain":"Cantidad de bases + polígono de la base = nombre completo.","type":"match","props":{"leftTitle":"Descripción","rightTitle":"Sólido","pairs":[{"id":"p1","left":"2 triángulos y 3 rectángulos","right":"Prisma triangular recto"},{"id":"p2","left":"1 cuadrado y 4 triángulos","right":"Pirámide cuadrangular"},{"id":"p3","left":"2 pentágonos y 5 rectángulos","right":"Prisma pentagonal recto"},{"id":"p4","left":"1 hexágono y 6 triángulos","right":"Pirámide hexagonal"}]},"id":"s04-mat-1-6"},{"fase":"construir","areas":["mat"],"cnb":["mat:1.3.3"],"ambito":"conocer","title":"Casos que confunden","prompt":"Revisa estos casos antes de practicar solo. Toca cada tarjeta.","type":"explain","props":{"icon":"AlertTriangle","body":"La posición del sólido no cambia su nombre.","reveal":[{"icon":"Tent","front":"Prisma acostado","back":"Una tienda de campaña tiene sus dos triángulos al frente y atrás: sigue siendo **prisma triangular**, aunque esté acostado."},{"icon":"Dice5","front":"El cubo","back":"Es un **prisma** cuadrangular especial: cualquier par de caras opuestas sirve como bases."},{"icon":"Cylinder","front":"Cilindro y cono","back":"Sus bases son círculos (no polígonos): **no** son prismas ni pirámides, aunque se parecen. El cilindro tiene 2 bases como un prisma; el cono, 1 base y punta como una pirámide."}]},"id":"s04-mat-1-7"},{"fase":"aplicar","areas":["mat"],"cnb":["mat:1.3.3"],"prompt":"Un pedazo de queso tiene forma de sólido con **dos triángulos congruentes** a los lados y **tres rectángulos**. ¿Qué es?","explain":"Dos bases triangulares congruentes y caras laterales rectangulares → **prisma triangular recto**.","type":"choice","props":{"options":[{"id":"a","text":"Pirámide triangular","feedback":"Una pirámide tiene una sola base y termina en punta."},{"id":"b","text":"Prisma triangular recto"},{"id":"c","text":"Prisma rectangular","feedback":"Las bases son las dos caras congruentes que están frente a frente: aquí son triángulos."}],"correct":["b"]},"id":"s04-mat-1-8"},{"fase":"aplicar","areas":["mat"],"cnb":["mat:1.3.3"],"prompt":"Una pirámide tiene **7 caras laterales** triangulares. ¿Cuántos lados tiene su base?","explain":"Hay una cara lateral por cada lado de la base: la base tiene 7 lados (es un heptágono).","type":"number-input","props":{"answer":7,"misconceptions":[{"value":8,"msg":"Las caras laterales no incluyen la base. Hay una por cada lado de la base."}]},"id":"s04-mat-1-9"},{"fase":"aplicar","areas":["mat"],"cnb":["mat:1.3.3"],"prompt":"Clasifica cada sólido por su descripción.","explain":"Bases de polígonos: prisma (2) o pirámide (1). Bases circulares: cuerpos redondos.","type":"sort","props":{"buckets":[{"id":"pr","label":"Prisma","icon":"Box"},{"id":"pi","label":"Pirámide","icon":"Triangle"},{"id":"re","label":"Cuerpo redondo","icon":"Cylinder"}],"items":[{"id":"a","text":"Dos octágonos y ocho rectángulos: prisma recto","bucket":"pr"},{"id":"b","text":"Un pentágono y cinco triángulos","bucket":"pi"},{"id":"c","text":"Dos círculos y una superficie curva","bucket":"re"},{"id":"d","text":"Un círculo, una superficie curva y una punta","bucket":"re"},{"id":"e","text":"Un triángulo abajo y tres triángulos que se juntan arriba","bucket":"pi"}]},"id":"s04-mat-1-10"},{"fase":"comprobar","areas":["mat"],"cnb":["mat:1.3.3"],"prompt":"Un sólido tiene **dos cuadrados congruentes** y **cuatro rectángulos**. ¿Cómo se llama?","type":"choice","props":{"options":[{"id":"a","text":"Pirámide cuadrangular"},{"id":"b","text":"Prisma cuadrangular recto"},{"id":"c","text":"Cilindro"}],"correct":["b"]},"id":"s04-mat-1-11"},{"fase":"comprobar","areas":["mat"],"cnb":["mat:1.3.3"],"prompt":"¿Verdadero o falso?","type":"true-false","props":{"statements":[{"text":"Una pirámide tiene dos bases.","answer":false},{"text":"En los prismas rectos, las caras laterales son rectángulos.","answer":true},{"text":"En los prismas oblicuos, las caras laterales son paralelogramos.","answer":true},{"text":"Una pirámide hexagonal tiene 6 caras laterales.","answer":true},{"text":"Un prisma acostado deja de ser prisma.","answer":false}]},"id":"s04-mat-1-12"}],"kind":"materia","area":"mat","day":1}},{"missionId":"s04","version":"cnb-sexto-feb98b754c748199","lesson":{"id":"s04-ef-2","title":"Cinco formas de lanzar","icon":"Send","minutes":15,"gancho":"En el recreo, para pasar la pelota a alguien cercano, a alguien lejos o por encima de un compañero alto, ¿usas siempre el mismo lanzamiento?","objetivos":["Elegir y ejecutar distintas formas de lanzamiento en una estructura rítmica sencilla según la situación"],"resumen":["Rodado: la pelota va por el suelo; es seguro y preciso para distancias cortas (como en el boliche).","A dos manos de pecho: desde el pecho, pulgares detrás de la pelota, se empuja estirando los brazos; rápido y preciso para pases cortos y medios.","Por arriba del hombro (directo): con una mano, para distancias largas. En suspensión: el mismo lanzamiento pero saltando, para lanzar por encima de un defensor.","Con pique: la pelota bota una vez en el suelo antes de llegar al compañero, más cerca de él que de ti; sirve para pasar por debajo de los brazos de un defensor.","Lanzar en movimiento exige coordinar pasos y brazos; practicar con cada mano te hace más completo.","Una estructura rítmica sencilla de cuatro tiempos puede ordenar preparar, apuntar, lanzar y recibir."],"media":{"id":"s04-ef-2-cinco","kind":"animation","title":"Cinco lanzamientos","aspect":"16:9","duration":60,"alt":"Cinco escenas cortas de dos niñas pasándose una pelota: rodando por el suelo, desde el pecho con dos manos, por arriba del hombro, saltando y con un bote en el suelo.","brief":"Animación 2D de 60 s, cinco escenas de 11 s con el mismo par de personajes (una niña maya con trenza y una niña garífuna, ropa deportiva genérica). (1) Rodado: flexión de rodillas, balanceo del brazo abajo, pelota rodando. (2) Pecho a dos manos: pulgares atrás, extensión de brazos, muñecas giran hacia afuera. (3) Por arriba del hombro: pase largo, técnica de 5 pasos. (4) En suspensión: carrera, salto con impulso, lanzamiento en el punto más alto, por encima de un defensor. (5) Con pique: bote en el suelo a unos dos tercios del camino hacia la compañera, por debajo de los brazos de un defensor. Línea punteada de trayectoria en cada caso y rótulo con el nombre. Accesibilidad: subtitulos completos para toda voz y transcripcion audiovisual; rotulos grandes, legibles y de alto contraste."},"steps":[{"fase":"explorar","areas":["ef"],"cnb":["ef:2.1.3"],"title":"Idea central","prompt":"Participar en equipo exige elegir el lanzamiento adecuado y adaptarlo a cada situación.","type":"explain","props":{"icon":"BookOpenCheck","body":"Rodado: la pelota va por el suelo; es seguro y preciso para distancias cortas (como en el boliche)."},"id":"s04-ef-2-1"},{"fase":"construir","areas":["ef"],"cnb":["ef:2.1.3"],"ambito":"conocer","prompt":"Un compañero muy alto está entre tú y tu amiga, con los brazos levantados. ¿Cómo le pasarías la pelota?","explain":"Una buena opción es un pase **con pique**: la pelota bota en el suelo y pasa **por debajo** de sus brazos. Hoy conocerás cinco formas de lanzar y cuándo usar cada una.","type":"choice","props":{"options":[{"id":"a","text":"Directo a la altura de su cara","icon":"ArrowRight","feedback":"Pasaría justo por donde están sus manos: la puede interceptar."},{"id":"b","text":"Haciéndola botar en el suelo para que pase por debajo de sus brazos","icon":"ArrowDown"},{"id":"c","text":"Esperar a que se vaya","icon":"Hourglass","feedback":"En un juego no hay tiempo de esperar: busca una forma de lanzar que lo supere."}],"correct":["b"]},"id":"s04-ef-2-2"},{"fase":"construir","areas":["ef"],"cnb":["ef:2.1.3"],"ambito":"hacer","title":"Tres lanzamientos básicos","prompt":"Mira la animación y toca cada tarjeta. Prueba el movimiento con una pelota imaginaria.","type":"explain","props":{"icon":"Target","body":"Cada lanzamiento tiene su técnica y su momento. Empieza por estos tres.","reveal":[{"icon":"CircleDot","front":"Rodado","back":"Dobla las rodillas, balancea el brazo **por abajo** y suelta la pelota **cerca del suelo** para que ruede. Seguro y preciso de cerca."},{"icon":"Hand","front":"A dos manos de pecho","back":"Pelota frente al pecho, **pulgares detrás**, codos abiertos. **Estira los brazos** hacia tu compañero y al final gira las muñecas hacia afuera. Rápido y preciso."},{"icon":"ArrowUpRight","front":"Por arriba del hombro","back":"Con **una mano**, como aprendiste el martes: de lado, pie contrario adelante, codo alto, giro. Para **distancias largas**."}]},"id":"s04-ef-2-3"},{"fase":"construir","areas":["ef"],"cnb":["ef:1.4.14","ef:2.1.3"],"ambito":"hacer","title":"Defensas y ritmo para coordinar pases","prompt":"Elige una forma de lanzamiento y coordinala con una estructura rítmica sencilla. Toca cada tarjeta.","type":"explain","props":{"icon":"Shield","body":"Según los brazos del defensor, pasa por arriba o por abajo. Para coordinar cualquier forma, repite **cuatro tiempos**: 1 preparar, 2 apuntar, 3 lanzar y 4 recibir.","reveal":[{"icon":"ArrowDown","front":"Con pique","back":"Lanza la pelota hacia el suelo para que **bote una vez** y llegue a tu compañero a la altura de la cintura. El bote va **más cerca de quien recibe** (a unos dos tercios del camino). Puedes hacerlo a dos manos o a una mano."},{"icon":"ArrowUp","front":"En suspensión","back":"Corre, **salta** con impulso y lanza por arriba del hombro en el **punto más alto** del salto. Así lanzas por encima de un defensor."},{"icon":"Footprints","front":"En movimiento","back":"Lanzar mientras te desplazas exige coordinar pasos y brazo: primero camina, luego trota y al final corre."},{"icon":"RefreshCw","front":"Alternar manos","back":"Practica cada lanzamiento de una mano con la **derecha** y con la **izquierda**: tendrás más opciones en el juego."},{"icon":"ListOrdered","front":"Estructura de cuatro tiempos","back":"**1 preparar, 2 apuntar, 3 lanzar, 4 recibir.** Luego el patrón comienza otra vez."}]},"id":"s04-ef-2-4"},{"fase":"construir","areas":["ef"],"cnb":["ef:2.1.3"],"ambito":"hacer","title":"Ejemplo resuelto: elegir el lanzamiento","prompt":"Mira cómo Keyla decide qué lanzamiento usar en cuatro momentos de un juego de pases.","type":"worked-example","props":{"icon":"Brain","problem":"Keyla tiene la pelota en cuatro situaciones distintas. ¿Qué lanzamiento conviene en cada una?","steps":[{"text":"**Situación 1:** su compañera está a 3 pasos y no hay nadie en medio → **a dos manos de pecho**.","why":"Es rápido, preciso y fácil de recibir a corta distancia."},{"text":"**Situación 2:** un defensor está en medio con los brazos arriba → **con pique**, botando la pelota cerca de su compañera.","why":"La pelota pasa por debajo de los brazos del defensor."},{"text":"**Situación 3:** su compañero está libre, lejos, al otro lado de la cancha → **por arriba del hombro**.","why":"Es el lanzamiento que llega más lejos."},{"text":"**Situación 4:** un defensor bajito está muy cerca, con los brazos abajo → **en suspensión**: salta y lanza por encima."}],"answer":"Keyla elige según **distancia**, **obstáculos** y **posición de los brazos del defensor**.","tip":"Antes de lanzar, mira a tu compañero y al defensor: la decisión es parte de la técnica."},"id":"s04-ef-2-5"},{"fase":"construir","areas":["ef"],"cnb":["ef:1.4.14","ef:2.1.3"],"ambito":"conocer","prompt":"Une cada lanzamiento o estructura rítmica con su descripción.","hint":"Recuerda por donde va la pelota y que ocurre en los cuatro tiempos.","explain":"Cada forma resuelve una situación; la estructura preparar, apuntar, lanzar y recibir coordina el pase.","type":"match","props":{"leftTitle":"Forma o estructura","rightTitle":"Cómo es","pairs":[{"id":"r","left":"Rodado","right":"La pelota va por el suelo"},{"id":"p","left":"A dos manos de pecho","right":"Se empuja desde el pecho estirando los brazos"},{"id":"h","left":"Por arriba del hombro","right":"Con una mano, para llegar lejos"},{"id":"s","left":"En suspensión","right":"Se lanza en el punto más alto de un salto"},{"id":"q","left":"Con pique","right":"La pelota bota una vez antes de llegar"},{"id":"t","left":"Cuatro tiempos","right":"Preparar, apuntar, lanzar y recibir"}]},"id":"s04-ef-2-6"},{"fase":"aplicar","areas":["ef"],"cnb":["ef:1.4.14","ef:2.1.3"],"ambito":"hacer","prompt":"En pareja, despejen la zona y usen una pelota suave. **Calentamiento:** muevan hombros y muñecas sin pelota. Hagan **8 pases en total**, cada uno con cuatro tiempos: 1 preparar, 2 apuntar, 3 lanzar y 4 recibir. Incluyan uno rodado, uno de pecho, uno por arriba del hombro, uno en suspensión sin carrera y uno con pique; repitan tres formas que la pareja elija. Quien recibe pone una marca por pase controlado. **Poco espacio:** trabajen contra una pared y omitan el salto. **Adaptación:** practiquen sentados y representen la suspensión elevando el brazo. **Vuelta a la calma:** caminen, respiren y estiren los brazos.","type":"pulse-lab","props":{"seconds":15,"rounds":[{"label":"En reposo"},{"label":"Después del calentamiento","exercise":{"name":"Movilidad de hombros y muñecas","icon":"RotateCw","seconds":30}},{"label":"Después de los 8 pases","exercise":{"name":"Cinco formas con registro de control","icon":"Target","seconds":120}}]},"id":"s04-ef-2-7"},{"fase":"aplicar","areas":["ef"],"cnb":["ef:2.1.3"],"ambito":"hacer","prompt":"En el pase con pique, la pelota de Ana llega a los tobillos de su compañero y él no la puede atrapar. ¿Qué debe cambiar?","explain":"El bote debe ir **más cerca de quien recibe** (a unos dos tercios del camino) para que la pelota suba hasta su cintura.","type":"choice","props":{"options":[{"id":"a","text":"Hacer que la pelota bote más cerca de su compañero"},{"id":"b","text":"Hacer que la pelota bote justo frente a sus propios pies","feedback":"Así la pelota pierde fuerza y llega aún más baja."},{"id":"c","text":"Lanzar la pelota sin que bote","feedback":"Entonces ya no sería un pase con pique."}],"correct":["a"]},"id":"s04-ef-2-8"},{"fase":"comprobar","areas":["ef"],"cnb":["ef:1.4.14","ef:2.1.3"],"prompt":"En la estructura de cuatro tiempos, necesitas un pase corto y seguro hacia una companera cercana y libre. ¿Que acción corresponde al tiempo 3?","type":"choice","props":{"options":[{"id":"a","text":"Lanzar a dos manos desde el pecho"},{"id":"b","text":"En suspensión, con salto"},{"id":"c","text":"Por arriba del hombro con toda la fuerza"}],"correct":["a"]},"id":"s04-ef-2-9"},{"fase":"comprobar","areas":["ef"],"cnb":["ef:1.4.14","ef:2.1.3"],"prompt":"Comprueba formas de lanzamiento y la estructura rítmica sencilla de cuatro tiempos.","type":"true-false","props":{"statements":[{"text":"Preparar, apuntar, lanzar y recibir puede repetirse como estructura de cuatro tiempos.","answer":true},{"text":"El lanzamiento en suspensión se hace en el punto más alto de un salto.","answer":true},{"text":"El lanzamiento rodado es el mejor para pasar por encima de un defensor alto.","answer":false,"why":"El rodado va por el suelo; para superar a un defensor alto conviene el pique o, si tiene los brazos abajo, la suspensión."}]},"id":"s04-ef-2-10"},{"fase":"reflexionar","ambito":"ser","prompt":"¿Cómo te fue? Responde con sinceridad: aprender es un camino.","areas":["ef"],"cnb":["ef:2.1.3"],"type":"reflection","props":{"statements":["Lanzo con todo el cuerpo y ajusto la fuerza según la distancia","Reconozco cinco formas de lanzar","Elijo el lanzamiento según la situación del juego"],"commitments":["Practicaré el tiro a la troje y anotaré mis aciertos","Lanzaré también con mi mano no dominante","Revisaré que no haya nadie en la zona antes de lanzar"]},"id":"s04-ef-2-11"}],"kind":"materia","area":"ef","day":5}},{"missionId":"s04","version":"cnb-sexto-82e4cf4e616226a7","lesson":{"id":"s04-d5-reto","kind":"reto","day":5,"title":"Reto de la semana 4","icon":"Trophy","minutes":14,"objetivos":["Demostrar lo aprendido en las diez áreas de la semana"],"resumen":["Resolví situaciones nuevas sobre crecimiento, comunicación, participación, arte, movimiento y producción."],"media":{"id":"s04-d5-reto","kind":"image","title":"Medalla Comunicador del cuidado","aspect":"1:1","alt":"Medalla dorada con un libro abierto, dos globos de diálogo y manos que se apoyan.","brief":"Medalla circular dorada. En el centro, un libro abierto con una marca de verificación; detrás, dos globos de diálogo y dos manos que se apoyan. Borde con un patrón geométrico inspirado en tejidos guatemaltecos. Fondo transparente, sin texto ni marcas. Dimensiones: 1200x1200."},"steps":[{"fase":"comprobar","areas":["mat"],"cnb":["mat:1.3.4"],"prompt":"Un soporte para carteles es un prisma nonagonal. ¿Cuántos vértices tiene?","type":"number-input","props":{"answer":18,"unit":"vértices"},"id":"s04-d5-reto-1"},{"fase":"comprobar","areas":["l1"],"cnb":["l1:5.1.8"],"prompt":"¿Cuál fragmento combina diálogo y acotación con formato teatral correcto?","type":"choice","props":{"options":[{"id":"a","text":"PAULA: (respira hondo) Voy a pedir ayuda."},{"id":"b","text":"Paula respiró hondo y dijo que iba a pedir ayuda."},{"id":"c","text":"(PAULA respira hondo: voy a pedir ayuda.)"}],"correct":["a"]},"id":"s04-d5-reto-2"},{"fase":"comprobar","areas":["cnt"],"cnb":["cnt:3.1.1"],"prompt":"Completa el análisis de una ruta anatómica nueva.","type":"fill-blank","props":{"text":"Si el paso desde el epidídimo hacia las glándulas se interrumpe, la estructura de transporte afectada es el [[conducto deferente]].","distractors":["uretra","próstata"]},"id":"s04-d5-reto-3"},{"fase":"comprobar","areas":["ccss"],"cnb":["ccss:5.1.1"],"prompt":"Un grupo investiga cómo participan estudiantes de distintas edades en el gobierno escolar. ¿Qué ciencia social estudia principalmente los grupos y sus relaciones?","type":"choice","props":{"options":[{"id":"a","text":"Sociología"},{"id":"b","text":"Arqueología"},{"id":"c","text":"Geografía física"}],"correct":["a"]},"id":"s04-d5-reto-4"},{"fase":"comprobar","areas":["l3"],"cnb":["l3:2.2.1"],"prompt":"Complete the new sentence with the correctly spelled **ee** words.","type":"fill-blank","props":{"text":"I see a [[green]] [[sheep]] near the [[tree]].","distractors":["grin","ship","tre"]},"id":"s04-d5-reto-5"},{"fase":"comprobar","areas":["fc"],"cnb":["fc:3.1.1"],"prompt":"La coordinadora escucha dos propuestas, publica los costos y luego organiza una votación. ¿Qué rasgo demuestra?","type":"choice","props":{"options":[{"id":"a","text":"Liderazgo democrático con información y participación"},{"id":"b","text":"Liderazgo autoritario porque permite votar"},{"id":"c","text":"Falta de liderazgo porque escucha antes de decidir"}],"correct":["a"]},"id":"s04-d5-reto-6"},{"fase":"comprobar","areas":["art"],"cnb":["art:3.1.2"],"prompt":"Clasifica decisiones musicales para una campaña escolar.","type":"sort","props":{"buckets":[{"id":"a","label":"Aporta al mensaje","icon":"Volume2"},{"id":"d","label":"Distrae o falta al respeto","icon":"VolumeX"}],"items":[{"id":"m1","text":"Entrada instrumental breve y de volumen moderado","bucket":"a"},{"id":"m2","text":"Letra que se burla de los cuerpos de otras personas","bucket":"d"},{"id":"m3","text":"Cierre tranquilo que permite oír la última orientación","bucket":"a"}]},"id":"s04-d5-reto-7"},{"fase":"comprobar","areas":["ef"],"cnb":["ef:2.1.3"],"prompt":"Completa con la forma de lanzamiento adecuada para una situación nueva.","type":"fill-blank","props":{"text":"Para enviar la pelota por el aire hasta una compañera distante, sin bote ni salto, uso el lanzamiento [[directo]] por arriba del hombro.","distractors":["rodado","en suspensión"]},"id":"s04-d5-reto-8"},{"fase":"comprobar","areas":["l2"],"cnb":["l2:2.2.1"],"prompt":"Une cada parte del mensaje oral con la manera de decirla.","type":"match","props":{"pairs":[{"id":"a","left":"¿Dónde puedo preguntar?","right":"Entonación ascendente de pregunta"},{"id":"b","left":"Cada cuerpo tiene su ritmo.","right":"Volumen claro y final descendente"},{"id":"c","left":"¡Tratémonos con respeto!","right":"Energía expresiva sin gritar"}]},"id":"s04-d5-reto-9"},{"fase":"comprobar","areas":["pyd"],"cnb":["pyd:2.5.3"],"prompt":"Antes de recomendar un cultivo nuevo, ¿qué conjunto de datos permite justificar la decisión?","type":"choice","props":{"options":[{"id":"a","text":"Temperatura, lluvias, tipo de suelo, pendiente y disponibilidad de agua"},{"id":"b","text":"Solo el color preferido de quien compra la semilla"},{"id":"c","text":"Únicamente el nombre del terreno"}],"correct":["a"]},"id":"s04-d5-reto-10"}]}},{"missionId":"s04","version":"cnb-sexto-41db3f8ed42b8a13","lesson":{"id":"s04-l1-2","title":"Juego de roles: ponerse en el lugar del otro","icon":"Users","minutes":13,"gancho":"¿Alguna vez has jugado a ser vendedor, maestra o doctor? Sin saberlo, ya hacías teatro.","objetivos":["Improvisar un juego de roles que escucha, acepta y responde con respeto"],"resumen":["El juego dramático es una forma sencilla de empezar a hacer teatro: se juega a ser otra persona, sin necesidad de escenario ni guion completo.","En el juego de roles cada participante representa un papel en una situación (vendedor y comprador, vecinos, autoridades) y actúa como lo haría esa persona.","Reglas: escuchar al compañero, aceptar lo que propone y agregar algo (\\"sí, y además…\\"), mantenerse en el personaje y respetar a todos.","El juego de roles ayuda a ensayar situaciones reales y a entender cómo piensan y sienten otras personas."],"media":{"id":"s04-l1-2-roles","kind":"video","title":"Juego de roles en el mercado","aspect":"16:9","duration":55,"alt":"Dos estudiantes improvisan una escena entre una vendedora y un comprador en un mercado hecho con pupitres; el resto del grupo observa.","brief":"Video de 55 s en un aula. Con pupitres y canastos se arma un \\"mercado\\". Una niña hace de vendedora de frutas y un niño de comprador que quiere regatear. Improvisan con respeto y humor: él pide rebaja, ella le ofrece una ñapa (fruta de regalo) si compra más. En pantalla aparecen tres rótulos en momentos clave: \\"Escucha\\", \\"Acepta y agrega\\", \\"Mantente en tu personaje\\". El grupo aplaude al final. Sin marcas. Accesibilidad: subtitulos completos para toda voz y transcripcion audiovisual; rotulos grandes, legibles y de alto contraste."},"steps":[{"fase":"explorar","areas":["l1"],"cnb":["l1:5.1.8"],"title":"Idea central","prompt":"Un juego de roles permite ensayar cómo pedir información confiable y escuchar sin burlas.","type":"explain","props":{"icon":"BookOpenCheck","body":"El juego dramático es una forma sencilla de empezar a hacer teatro: se juega a ser otra persona, sin necesidad de escenario ni guion completo."},"id":"s04-l1-2-1"},{"fase":"construir","areas":["l1"],"cnb":["l1:5.1.8"],"ambito":"conocer","prompt":"En un juego de roles, tu compañera hace de vendedora y dice: **\\"¡Aguacates frescos, a cinco quetzales!\\"**. Tú eres el comprador. ¿Qué respuesta **mantiene vivo** el juego?","hint":"Elige la respuesta que acepta la situación y permite que el diálogo continúe.","explain":"La primera respuesta acepta la situación y agrega algo nuevo (la duda sobre el precio). Así la escena avanza. Hoy aprenderás cómo funciona el juego de roles.","type":"choice","props":{"options":[{"id":"a","text":"\\"¡Buenos días, seño! ¿Y si le compro tres, me los deja a doce?\\"","icon":"MessageCircle"},{"id":"b","text":"\\"No quiero jugar a esto.\\"","icon":"X","feedback":"Así el juego se acaba antes de empezar."},{"id":"c","text":"\\"Yo no soy comprador, soy astronauta.\\"","icon":"Rocket","feedback":"Cambiar de personaje sin razón rompe la escena: la compañera no sabe cómo seguir."}],"correct":["a"]},"id":"s04-l1-2-2"},{"fase":"construir","areas":["l1"],"cnb":["l1:5.1.8"],"ambito":"conocer","title":"El juego dramático","prompt":"El **juego dramático** es la puerta de entrada al teatro. Toca cada tarjeta.","type":"explain","props":{"icon":"Drama","body":"En el juego dramático no importa tener un escenario perfecto: importa **imaginar**, **representar** y **comunicarse**.","reveal":[{"icon":"Users","front":"Juego de roles","back":"Cada quien representa un **papel** en una situación: vecinos que resuelven un problema, una entrevista, una visita al centro de salud. Se actúa como lo haría esa persona."},{"icon":"Sparkles","front":"Improvisación","back":"Se inventan los diálogos **en el momento**, sin guion escrito. Solo se acuerda la situación y los personajes."},{"icon":"Heart","front":"Para qué sirve","back":"Para **ensayar** situaciones reales (pedir ayuda, resolver un conflicto) y **ponerse en el lugar del otro**: entender qué piensa y siente."}]},"id":"s04-l1-2-3"},{"fase":"construir","areas":["l1"],"cnb":["l1:5.1.8"],"ambito":"convivir","title":"Las cuatro reglas del juego de roles","prompt":"Para que el juego funcione, todos siguen estas reglas. Toca cada tarjeta.","type":"explain","props":{"icon":"ListChecks","body":"Las reglas hacen que el juego sea **seguro y divertido** para todos.","reveal":[{"icon":"Ear","front":"1. Escucha","back":"Pon atención a lo que dice tu compañero: tu respuesta depende de eso."},{"icon":"Plus","front":"2. Acepta y agrega","back":"No niegues lo que el otro propone: acéptalo y **agrega** algo nuevo. Es la regla del \\"**sí, y además…**\\"."},{"icon":"User","front":"3. Mantente en tu personaje","back":"Habla y muévete como lo haría tu personaje hasta que termine la escena."},{"icon":"HeartHandshake","front":"4. Respeta","back":"Nada de burlas hacia personas reales, grupos o culturas. Se representa un **papel**, no se ridiculiza a nadie."}]},"id":"s04-l1-2-4"},{"fase":"construir","areas":["l1"],"cnb":["l1:5.1.8"],"ambito":"hacer","title":"Ejemplo resuelto: \\"sí, y además…\\"","prompt":"Mira cómo avanza una improvisación cuando cada quien acepta y agrega.","type":"worked-example","props":{"icon":"MessagesSquare","problem":"Situación: dos vecinos encuentran un perro perdido en la calle. Personajes: DOÑA ELENA y JOSUÉ.","steps":[{"text":"DOÑA ELENA: \\"¡Mira, Josué! Este perrito anda solo y tiene collar.\\""},{"text":"JOSUÉ **acepta y agrega**: \\"Sí, y además el collar tiene una plaquita con un número de teléfono.\\"","why":"Acepta lo que propuso Elena y aporta una idea nueva que hace avanzar la historia."},{"text":"DOÑA ELENA **acepta y agrega**: \\"Entonces llamemos. Y mientras, démosle agua, que se ve cansado.\\""},{"text":"Si Josué hubiera dicho \\"No, no tiene collar\\", la escena se habría trabado.","why":"Negar lo que el otro propone deja a tu compañero sin camino."}],"answer":"Cada intervención acepta lo anterior y agrega algo: la historia fluye y los personajes resuelven la situación juntos.","tip":"\\"Sí, y además…\\" es la frase mágica de la improvisación."},"id":"s04-l1-2-5"},{"fase":"aplicar","areas":["l1"],"cnb":["l1:5.1.8"],"ambito":"hacer","prompt":"Ahora tú. Situación: dos estudiantes ven que el chorro de la escuela está goteando. MARÍA dice: **\\"¡Se está desperdiciando el agua!\\"** ¿Qué respuesta sigue la regla \\"sí, y además\\"?","explain":"La respuesta correcta acepta el problema y propone una acción: la escena avanza.","type":"choice","props":{"options":[{"id":"a","text":"\\"Sí, y además se va a inundar el pasillo. Vamos a avisarle al director.\\""},{"id":"b","text":"\\"No está goteando, estás viendo mal.\\"","feedback":"Niega lo que propuso María: la escena se traba."},{"id":"c","text":"(Se queda callado y se va.)","feedback":"Abandonar la escena deja sola a tu compañera."}],"correct":["a"]},"id":"s04-l1-2-6"},{"fase":"aplicar","areas":["l1","fc"],"cnb":["l1:5.1.8"],"ambito":"convivir","prompt":"Durante un juego de roles, a Byron le toca hacer de abuelo. Algunos compañeros le piden que imite de forma burlona la manera de hablar de un señor real de la comunidad. ¿Qué harías tú?","type":"dilemma","props":{"scene":{"icon":"Users","text":"Todos se ríen y esperan que Byron haga la imitación. El señor es muy conocido en la aldea."},"options":[{"id":"a","icon":"HeartHandshake","text":"Hacer un abuelo inventado, sabio y divertido, sin imitar a nadie real","consequence":"La escena es graciosa y nadie sale herido. El grupo aprende que el humor no necesita burlarse de nadie.","values":["respeto","creatividad"],"constructive":true},{"id":"b","icon":"Megaphone","text":"Hacer la imitación porque todos se están riendo","consequence":"El grupo se ríe un momento, pero si el señor o su familia se enteran, se sentirán ofendidos. Se rompió la regla del respeto.","values":["presión del grupo"],"constructive":false},{"id":"c","icon":"MessageCircle","text":"Decir con calma: \\"Mejor hagamos un personaje inventado; burlarse de alguien real no es justo\\"","consequence":"Algunos se quejan al principio, pero la maestra y varios compañeros te apoyan. La escena sigue con respeto.","values":["valentía","respeto"],"constructive":true}]},"id":"s04-l1-2-7"},{"fase":"aplicar","areas":["l1"],"cnb":["l1:5.1.8"],"ambito":"hacer","prompt":"Prepara un **juego de roles** sobre una persona joven que busca información confiable acerca de un cambio de la pubertad. Escribe la situación, dos personajes respetuosos y las tres primeras líneas usando \\"sí, y además…\\". No inventes diagnósticos.","type":"short-answer","props":{"minWords":30,"placeholder":"Situación: …\\nPersonajes: …\\nLínea 1: …\\nLínea 2: …\\nLínea 3: …","model":"Situación: una estudiante pregunta dónde aclarar una duda sobre su crecimiento.\\nPersonajes: ESTUDIANTE, curiosa. TÍA, escucha con calma.\\nESTUDIANTE: Me preocupa crecer a un ritmo distinto que mis amigas.\\nTÍA: Sí, y además es común que cada cuerpo cambie a su ritmo. Podemos revisar tu libro de Ciencias.\\nESTUDIANTE: Gracias, y además quisiera anotar mis preguntas para hablar con una profesional de salud.","rubric":["Describí una situación clara","Cada personaje tiene una característica","Las líneas aceptan lo anterior y agregan algo nuevo","La escena es respetuosa con todas las personas"]},"id":"s04-l1-2-8"},{"fase":"comprobar","areas":["l1"],"cnb":["l1:5.1.8"],"prompt":"¿Qué es un **juego de roles**?","type":"choice","props":{"options":[{"id":"a","text":"Representar un papel en una situación, actuando como lo haría esa persona"},{"id":"b","text":"Leer en silencio un guion completo"},{"id":"c","text":"Mover muñecos con hilos"}],"correct":["a"]},"id":"s04-l1-2-9"},{"fase":"comprobar","areas":["l1"],"cnb":["l1:5.1.8"],"prompt":"¿Verdadero o falso?","type":"true-false","props":{"statements":[{"text":"En la improvisación los diálogos se inventan en el momento.","answer":true},{"text":"La regla \\"sí, y además\\" consiste en negar lo que propone tu compañero.","answer":false,"why":"Consiste en aceptar lo que propone y agregar algo nuevo."},{"text":"Mantenerse en el personaje ayuda a que la escena sea creíble.","answer":true}]},"id":"s04-l1-2-10"}],"kind":"materia","area":"l1","day":2}},{"missionId":"s04","version":"cnb-sexto-cca184cda91043af","lesson":{"id":"s04-l2-1","title":"Mi voz comunica: volumen, entonación y fluidez","icon":"Mic","minutes":13,"gancho":"\\"Ya llegó.\\" \\"¿Ya llegó?\\" \\"¡Ya llegó!\\" Son las mismas palabras… ¿por qué dicen cosas distintas?","objetivos":["Comunicar un mensaje oral con volumen, entonación, fluidez y pausas adecuados"],"resumen":["Volumen: qué tan fuerte hablas. Se ajusta al lugar y a la cantidad de personas que escuchan.","Entonación: la \\"música\\" de la voz. En preguntas de sí o no la voz sube al final (¿?); en exclamaciones se dice con fuerza y emoción (¡!); en afirmaciones baja al final (.).","Fluidez: leer o hablar sin cortar las palabras, a una velocidad cómoda, con pausas cortas en las comas y más largas en los puntos."],"media":{"id":"s04-l2-1-tres-voces","kind":"audio","title":"Una frase, tres entonaciones","duration":30,"alt":"Una voz dice \\"Ya llegó\\" como afirmación, como pregunta y como exclamación; después, una lectura cortada y la misma lectura fluida.","brief":"Audio de 30 s, voz de niña o niño de 11-12 años, español de Guatemala, grabación limpia. Parte 1: \\"Ya llegó.\\" (tono que baja) — pausa — \\"¿Ya llegó?\\" (tono que sube al final) — pausa — \\"¡Ya llegó!\\" (alegre, con fuerza). Parte 2: la oración \\"Mañana, si no llueve, iremos al río con mi abuelo.\\" leída primero sílaba por sílaba, sin pausas correctas; después leída con fluidez, con pausa corta en cada coma y bajando el tono en el punto. Rotular en pantalla (si hay versión visual) la curva de entonación con flechas. Accesibilidad: transcripcion del contenido sonoro y guion exacto de las voces, si las hay."},"steps":[{"fase":"explorar","areas":["l2"],"cnb":["l2:2.2.1"],"title":"Idea central","prompt":"Un mensaje de cuidado se entiende mejor cuando ajustas volumen, entonación y fluidez al público.","type":"explain","props":{"icon":"BookOpenCheck","body":"Volumen: qué tan fuerte hablas. Se ajusta al lugar y a la cantidad de personas que escuchan."},"id":"s04-l2-1-1"},{"fase":"construir","areas":["l2"],"cnb":["l2:2.2.1"],"ambito":"conocer","prompt":"Escucha el audio: la misma frase se dice de tres maneras. ¿En cuál la persona **pregunta** si alguien ya llegó?","explain":"En la pregunta la voz **sube al final**. Las palabras son las mismas, pero la **entonación** cambia el mensaje. Hoy aprenderás a usar tu voz para comunicar mejor.","type":"choice","props":{"options":[{"id":"a","text":"\\"Ya llegó.\\" (la voz baja al final)","icon":"ArrowDown","feedback":"Cuando la voz baja al final, se está afirmando algo."},{"id":"b","text":"\\"¿Ya llegó?\\" (la voz sube al final)","icon":"ArrowUp"},{"id":"c","text":"\\"¡Ya llegó!\\" (con fuerza y alegría)","icon":"PartyPopper","feedback":"Esa es una exclamación: expresa emoción."}],"correct":["b"]},"id":"s04-l2-1-2"},{"fase":"construir","areas":["l2"],"cnb":["l2:2.2.1"],"ambito":"conocer","title":"Tres destrezas de la voz","prompt":"Cuando hablas o lees en voz alta, tu voz tiene tres controles, como un radio. Toca cada tarjeta.","type":"explain","props":{"icon":"Mic","body":"Una misma información puede entenderse bien o mal según **cómo** la digas.","reveal":[{"icon":"Volume2","front":"Volumen","back":"Qué tan **fuerte** hablas. Súbelo si el grupo es grande o estás al aire libre; bájalo en la biblioteca, el centro de salud o una conversación cercana. Nunca grites sin necesidad."},{"icon":"Music","front":"Entonación","back":"La **\\"música\\"** de la voz. **¿Pregunta de sí o no?** → sube al final (en preguntas con qué, quién o dónde, la voz se eleva al inicio). **¡Exclamación!** → fuerza y emoción. **Afirmación.** → baja al final."},{"icon":"Waves","front":"Fluidez","back":"Hablar o leer **sin cortar las palabras**, a velocidad cómoda. Pausa **corta** en la coma (,) y **más larga** en el punto (.)."}]},"id":"s04-l2-1-3"},{"fase":"construir","areas":["l2"],"cnb":["l2:2.2.1"],"ambito":"hacer","title":"Ejemplo resuelto","prompt":"Mira cómo Andrea prepara un aviso que leerá en la formación, frente a toda la escuela.","type":"worked-example","props":{"icon":"Megaphone","problem":"Andrea debe leer: _\\"Compañeros, el viernes habrá feria de ciencias. ¿Ya tienen su experimento? ¡Los esperamos!\\"_","steps":[{"text":"**Volumen:** es en el patio y hay muchas personas → volumen **alto** y claro, sin gritar."},{"text":"**Pausas:** marca con una raya las comas y los puntos: \\"Compañeros, / el viernes habrá feria de ciencias. // ¿Ya tienen su experimento? // ¡Los esperamos!\\"","why":"Una raya = pausa corta; dos rayas = pausa larga."},{"text":"**Entonación:** la primera oración baja al final (afirma); la segunda **sube** al final (pregunta de sí o no); la tercera va con **alegría y fuerza** (exclamación)."},{"text":"**Fluidez:** lo lee en voz alta tres veces, hasta decir cada oración sin trabarse."}],"answer":"Andrea ajustó el **volumen** al patio, marcó las **pausas** y eligió la **entonación** de cada oración.","tip":"Los signos ¿? y ¡! se escriben al inicio y al final en español: te avisan desde el principio cómo leer."},"id":"s04-l2-1-4"},{"fase":"construir","areas":["l2"],"cnb":["l2:2.2.1"],"ambito":"hacer","prompt":"Ahora tú, con ayuda: une cada oración con la forma de decirla.","hint":"Mira los signos: ¿ ? pide subir al final; ¡ ! pide emoción; el punto pide bajar.","explain":"Los signos de puntuación son instrucciones para tu voz.","type":"match","props":{"leftTitle":"Oración","rightTitle":"Cómo se dice","pairs":[{"id":"e1","left":"¿Vienes mañana a la cancha?","leftIcon":"HelpCircle","right":"La voz sube al final"},{"id":"e2","left":"¡Ganamos el campeonato!","leftIcon":"Trophy","right":"Con fuerza y alegría"},{"id":"e3","left":"Mañana hay clases a las siete.","leftIcon":"Clock","right":"La voz baja al final"},{"id":"e4","left":"Shh, el bebé está dormido.","leftIcon":"Moon","right":"Con volumen muy bajo"}]},"id":"s04-l2-1-5"},{"fase":"construir","areas":["l2"],"cnb":["l2:2.2.1"],"ambito":"hacer","prompt":"¿Qué **volumen** conviene en cada situación?","hint":"Piensa en cuántas personas escuchan, qué tan lejos están y si el lugar pide silencio.","explain":"Ajustar el volumen es una forma de respeto: que te oigan todos, sin molestar a nadie.","type":"sort","props":{"buckets":[{"id":"alto","label":"Alto","icon":"Volume2","color":"var(--c-maiz-strong)"},{"id":"medio","label":"Moderado","icon":"Volume1","color":"var(--area-l2)"},{"id":"bajo","label":"Bajo","icon":"VolumeX","color":"var(--c-ok)"}],"items":[{"id":"v1","text":"Dar un aviso en el patio a toda la escuela, sin micrófono","bucket":"alto"},{"id":"v2","text":"Exponer en tu aula ante tu grado","bucket":"medio"},{"id":"v3","text":"Preguntar algo en la biblioteca","bucket":"bajo"},{"id":"v4","text":"Leer un cuento a tres compañeros en tu mesa","bucket":"medio"},{"id":"v5","text":"Hablar en la sala de espera del centro de salud","bucket":"bajo"},{"id":"v6","text":"Llamar a tu equipo desde el otro lado de la cancha","bucket":"alto"}]},"id":"s04-l2-1-6"},{"fase":"aplicar","areas":["l2"],"cnb":["l2:2.2.1"],"ambito":"hacer","title":"Lee en voz alta","prompt":"Lee este mensaje **en voz alta** dos veces, como si lo dijeras por la radio de la escuela. Luego responde.","type":"reading","props":{"genre":"Aviso","heading":"Radio escolar","passage":"¡Buenos días, escuela Tecún Umán! Les habla Diego, de sexto grado.\\n\\nHoy, a la hora del recreo, el equipo de sexto jugará contra el de quinto. ¿Quién ganará? ¡Vengan a apoyar!\\n\\nRecuerden: no dejen basura en la cancha, y lleven su botella de agua.","questions":[{"q":"¿Cómo debe decir Diego \\"¿Quién ganará?\\"?","options":[{"id":"a","text":"Con tono de pregunta"},{"id":"b","text":"En voz muy baja, como un secreto"},{"id":"c","text":"Sin cambiar la voz"}],"correct":"a","why":"Los signos ¿? indican una pregunta. Esta no se responde con sí o no, así que la voz sube en \\"quién\\" y baja suavemente al final, pero se nota que pregunta."},{"q":"¿Dónde debe hacer una pausa **corta** en la última oración?","options":[{"id":"a","text":"Después de \\"Recuerden:\\" y de \\"cancha,\\""},{"id":"b","text":"Entre \\"botella\\" y \\"de\\""},{"id":"c","text":"En ningún lugar: debe leerla de corrido"}],"correct":"a","why":"Los dos puntos y la coma piden pausas cortas. Cortar \\"botella / de agua\\" rompe la fluidez."},{"q":"¿Qué **volumen** conviene si el mensaje sale por los parlantes de toda la escuela?","options":[{"id":"a","text":"Claro y moderado: los parlantes ya aumentan el sonido"},{"id":"b","text":"Gritando lo más fuerte posible"},{"id":"c","text":"Susurrando"}],"correct":"a","why":"Con micrófono y parlantes no hace falta gritar: basta una voz clara."}]},"id":"s04-l2-1-7"},{"fase":"aplicar","areas":["l2"],"cnb":["l2:2.2.1"],"ambito":"hacer","prompt":"Tres estudiantes leen la oración _\\"Cuando llegué a casa, mi abuela estaba tortilleando.\\"_ ¿Quién lee con **fluidez**?","explain":"La fluidez agrupa las palabras con sentido y hace la pausa en la coma, no en cualquier lugar.","type":"choice","props":{"options":[{"id":"a","text":"Luis: \\"Cuan-do-lle-gué-a-ca-sa-mi-a-bue-la…\\"","feedback":"Leer sílaba por sílaba hace que se pierda el sentido."},{"id":"b","text":"Marta: \\"Cuando llegué a casa (pausa) mi abuela estaba tortilleando.\\""},{"id":"c","text":"Beto: \\"Cuando llegué (pausa) a casa mi abuela (pausa) estaba tortilleando.\\"","feedback":"Las pausas no coinciden con la coma: corta las ideas en lugares extraños."}],"correct":["b"]},"id":"s04-l2-1-8"},{"fase":"aplicar","areas":["l2"],"cnb":["l2:2.2.1"],"ambito":"hacer","prompt":"Escribe un aviso corto para la campaña **Crecer con cuidado**: una afirmación respetuosa, una pregunta sobre dónde buscar información y una exclamación que invite a participar. Después léelo cuidando volumen, entonación y pausas.","type":"short-answer","props":{"minWords":18,"placeholder":"Buenos días, compañeros…","model":"Buenos días, compañeros: cada cuerpo cambia a su propio ritmo. ¿Con qué persona adulta de confianza podemos aclarar una duda? ¡Escuchemos y participemos con respeto!","rubric":["Escribí una afirmación, una pregunta y una exclamación","Usé los signos ¿? y ¡! al inicio y al final","Lo leí en voz alta con la entonación correcta","Hice pausas en las comas y los puntos"]},"id":"s04-l2-1-9"},{"fase":"comprobar","areas":["l2"],"cnb":["l2:2.2.1"],"prompt":"Boleto de salida: ¿cómo se dice _\\"¿Me prestas tu lápiz?\\"_?","type":"choice","props":{"options":[{"id":"a","text":"La voz sube al final"},{"id":"b","text":"La voz baja al final, como una orden"},{"id":"c","text":"Gritando, con enojo"}],"correct":["a"]},"id":"s04-l2-1-10"},{"fase":"comprobar","areas":["l2"],"cnb":["l2:2.2.1"],"prompt":"¿Verdadero o falso?","type":"true-false","props":{"statements":[{"text":"En la coma se hace una pausa corta y en el punto, una más larga.","answer":true},{"text":"En la biblioteca conviene hablar con volumen alto.","answer":false,"why":"En la biblioteca se habla bajo para no interrumpir a quienes leen."},{"text":"Leer sílaba por sílaba es leer con fluidez.","answer":false,"why":"La fluidez agrupa las palabras con sentido, sin cortarlas."}]},"id":"s04-l2-1-11"}],"kind":"materia","area":"l2","day":2}},{"missionId":"s04","version":"cnb-sexto-57d427b74c205104","lesson":{"id":"s04-pyd-1","title":"Leer la naturaleza antes de sembrar","icon":"CloudSun","minutes":15,"gancho":"¿Por qué en Totonicapán se cosechan papas y duraznos, pero no bananos, y en Escuintla crece la caña pero no el trigo?","objetivos":["Analizar clima, suelo, estaciones y relieve para proponer una actividad productiva adecuada"],"resumen":["Antes de producir se analiza la naturaleza: temperatura (depende mucho de la altura), lluvias y estaciones, tipo de suelo, pendiente del terreno y fenómenos como heladas, canícula o tormentas.","En Guatemala, a grandes rasgos: tierra caliente (costas y tierras bajas) para caña, banano, palma y mango; tierra templada (laderas y valles medios) para café, cítricos y aguacate; tierra fría (altiplano alto) para papa, trigo, haba, hortalizas y frutas como manzana y durazno. El maíz y el frijol se siembran en casi todo el país con variedades distintas.","La época lluviosa va aproximadamente de mayo a octubre y la seca de noviembre a abril; a mitad de las lluvias suele venir la canícula (unas semanas secas). Sin riego, se siembra al empezar las lluvias.","Suelo arenoso: el agua se va rápido. Arcilloso: se encharca y se endurece. Franco: mezcla equilibrada, el mejor para la mayoría de cultivos. En laderas se usan terrazas y curvas a nivel."],"media":{"id":"s04-pyd-1-pisos","kind":"diagram","title":"De la costa al altiplano","aspect":"16:9","alt":"Corte de una montaña de Guatemala desde la costa hasta el altiplano, con tres franjas (caliente, templada y fría) y los cultivos de cada una.","brief":"Diagrama en corte lateral de un paisaje guatemalteco: a la izquierda el mar y la costa sur, subiendo hacia volcanes y el altiplano a la derecha. Tres franjas de color: \\"Tierra caliente\\" (naranja, abajo) con caña, banano y palma; \\"Tierra templada\\" (verde, en medio) con cafetales bajo sombra, naranjos y aguacates; \\"Tierra fría\\" (azul, arriba) con papa, trigo, haba y árboles de durazno, y un pequeño símbolo de helada. Un termómetro a un lado que baja al subir. Milpa dibujada en las tres franjas. Nota al pie: \\"A más altura, menos temperatura\\". Sin cifras exactas de altura. Dimensiones: 1600x900. Accesibilidad: contraste alto, rotulos grandes y legibles; la descripcion visual debe corresponder exactamente al texto alternativo."},"steps":[{"fase":"explorar","areas":["pyd"],"cnb":["pyd:2.5.3"],"title":"Idea central","prompt":"Cuidar la vida comunitaria incluye analizar clima, suelo y agua antes de proponer una actividad productiva.","type":"explain","props":{"icon":"BookOpenCheck","body":"Antes de producir se analiza la naturaleza: temperatura (depende mucho de la altura), lluvias y estaciones, tipo de suelo, pendiente del terreno y fenómenos como heladas, canícula o tormentas."},"id":"s04-pyd-1-1"},{"fase":"construir","areas":["pyd"],"cnb":["pyd:2.5.3"],"ambito":"conocer","prompt":"¿Por qué crees que en el altiplano de Totonicapán **no** se cultivan bananos?","explain":"El banano necesita **calor todo el año**. En el altiplano alto hace frío y en algunos meses caen **heladas**, que queman las hojas de las plantas de tierra caliente.","type":"choice","props":{"options":[{"id":"a","text":"Porque hace frío y puede haber heladas","icon":"Snowflake"},{"id":"b","text":"Porque a la gente de allí no le gustan","icon":"Smile","feedback":"El gusto no es la razón: el banano simplemente no crece bien con frío."},{"id":"c","text":"Porque llueve demasiado","icon":"CloudRain","feedback":"El banano necesita bastante agua; el problema en el altiplano es la temperatura."}],"correct":["a"]},"id":"s04-pyd-1-2"},{"fase":"construir","areas":["pyd"],"cnb":["pyd:2.5.3"],"ambito":"conocer","title":"Cinco preguntas a la naturaleza","prompt":"Quien produce **analiza la naturaleza** antes de decidir qué sembrar o criar. Toca cada pregunta.","type":"explain","props":{"icon":"Search","body":"Sembrar sin analizar es arriesgar la semilla, el trabajo y el dinero de la familia.","reveal":[{"icon":"Thermometer","front":"1. ¿Qué temperatura hay?","back":"Depende sobre todo de la **altura**: a más altura, más frío. Cada cultivo tiene su rango de temperatura."},{"icon":"CloudRain","front":"2. ¿Cuándo y cuánto llueve?","back":"Hay una **época lluviosa** (aprox. mayo a octubre) y una **seca** (noviembre a abril). Sin riego, se depende de la lluvia."},{"icon":"Shovel","front":"3. ¿Cómo es el suelo?","back":"**Arenoso** (el agua se va rápido), **arcilloso** (se encharca y se endurece) o **franco** (equilibrado, el mejor para casi todo)."},{"icon":"Mountain","front":"4. ¿Es plano o ladera?","back":"En **laderas**, la lluvia arrastra el suelo. Hay que hacer **terrazas** o **curvas a nivel**."},{"icon":"Snowflake","front":"5. ¿Qué fenómenos hay?","back":"**Heladas** en el altiplano (sobre todo entre diciembre y febrero), **canícula** (semanas secas a mitad de las lluvias), tormentas y huracanes."}]},"id":"s04-pyd-1-3"},{"fase":"construir","areas":["pyd"],"cnb":["pyd:2.5.3"],"ambito":"conocer","title":"Tierra caliente, templada y fría","prompt":"En Guatemala, las familias campesinas hablan de **tres tipos de tierra** según su clima. Toca cada una.","type":"explain","props":{"icon":"Thermometer","body":"El **maíz** y el **frijol** se siembran en casi todo el país: cada región tiene sus propias **variedades** adaptadas a su clima.","reveal":[{"icon":"Sun","front":"Tierra caliente","back":"Costas y tierras bajas (costa sur, oriente bajo, Petén). Calor todo el año. Cultivos: **caña de azúcar, banano, palma, mango, ajonjolí**."},{"icon":"CloudSun","front":"Tierra templada","back":"Laderas y valles de altura media (bocacosta, parte de las Verapaces y del centro). Clima agradable. Cultivos: **café, cítricos, aguacate**."},{"icon":"Snowflake","front":"Tierra fría","back":"Altiplano alto (Totonicapán, partes de Quetzaltenango, San Marcos y Huehuetenango). Noches frías y heladas. Cultivos: **papa, trigo, haba, brócoli, manzana, durazno**."}]},"id":"s04-pyd-1-4"},{"fase":"construir","areas":["pyd"],"cnb":["pyd:2.5.3"],"prompt":"¿En qué tipo de tierra crece mejor cada cultivo?","hint":"Los cultivos que resisten frío y heladas van en tierra fría; los que necesitan calor todo el año, en tierra caliente; el café está en medio.","explain":"Cada cultivo se adapta a un rango de temperatura. Por eso el tipo de tierra decide qué conviene producir.","type":"sort","props":{"buckets":[{"id":"cal","label":"Tierra caliente","icon":"Sun","color":"var(--c-maiz-strong)"},{"id":"tem","label":"Tierra templada","icon":"CloudSun","color":"var(--c-ok)"},{"id":"fri","label":"Tierra fría","icon":"Snowflake","color":"var(--area-cnt)"}],"items":[{"id":"k1","text":"Caña de azúcar","bucket":"cal"},{"id":"k2","text":"Papa","bucket":"fri"},{"id":"k3","text":"Café","bucket":"tem"},{"id":"k4","text":"Banano","bucket":"cal"},{"id":"k5","text":"Trigo","bucket":"fri"},{"id":"k6","text":"Haba","bucket":"fri"}]},"id":"s04-pyd-1-5"},{"fase":"construir","areas":["pyd"],"cnb":["pyd:2.5.3"],"ambito":"conocer","title":"El calendario de la lluvia y el cuidado del suelo","prompt":"Además del clima, hay que saber **cuándo** sembrar y **cómo** cuidar el suelo. Toca cada tarjeta.","media":{"id":"s04-pyd-1-calendario","kind":"animation","title":"Un año de lluvia en la milpa","aspect":"16:9","duration":45,"alt":"Un calendario circular de 12 meses se colorea de azul en la época lluviosa y amarillo en la seca; una milpa crece desde la siembra en mayo hasta la cosecha.","brief":"Animación 2D de 45 s. Calendario circular con los 12 meses. Noviembre a abril en amarillo con sol (\\"época seca\\"); mayo a octubre en azul con nubes (\\"época lluviosa\\"). En mayo aparece una mano que siembra maíz y frijol; la milpa crece mes a mes; en julio-agosto una franja más clara con el texto \\"canícula: semanas secas\\". Al final, cosecha. Un inserto muestra una ladera con terrazas que detienen el agua. Nota en pantalla: \\"Las fechas cambian un poco según la región\\". Narración en español, subtítulos."},"type":"explain","props":{"icon":"Calendar","body":"Las fechas pueden cambiar un poco en cada región: por eso se escucha también a los agricultores con experiencia.","reveal":[{"icon":"CloudRain","front":"Sembrar con las lluvias","back":"Sin riego, se siembra **al empezar las lluvias** (en muchas regiones, alrededor de **mayo**), para que la semilla tenga humedad y germine."},{"icon":"Sun","front":"La canícula","back":"A mitad de la época lluviosa (julio-agosto) suelen venir **semanas secas**. Conviene guardar agua de lluvia y usar variedades que la resistan."},{"icon":"Layers","front":"Mejorar el suelo","back":"El **abono orgánico** (restos de cosecha, estiércol curado) mejora suelos arenosos y arcillosos: retiene humedad y nutrientes."},{"icon":"Mountain","front":"Cuidar las laderas","back":"**Terrazas**, **curvas a nivel** y **barreras vivas** (hileras de plantas) frenan el agua y evitan que se lleve el suelo."}]},"id":"s04-pyd-1-6"},{"fase":"construir","areas":["pyd"],"cnb":["pyd:2.5.3"],"ambito":"hacer","title":"Ejemplo resuelto: analizar un terreno","prompt":"Mira cómo doña Isabel usa las cinco preguntas para decidir qué sembrar.","type":"worked-example","props":{"icon":"Sprout","problem":"Doña Isabel tiene un terreno en Chimaltenango, en tierra **templada a fría**, **sin riego**, en **ladera**, con suelo **franco**. En diciembre a veces cae helada. ¿Qué siembra, cuándo y cómo?","steps":[{"text":"**Temperatura:** clima fresco con posible helada en diciembre: debe cosechar **antes** de las heladas."},{"text":"**Lluvia:** sin riego, depende de la lluvia: siembra al **empezar las lluvias** (mayo)."},{"text":"**Suelo:** franco, bueno para la **milpa** (maíz, frijol y ayote juntos) y para hortalizas."},{"text":"**Pendiente:** ladera: hará **curvas a nivel** con barreras vivas para que la lluvia no se lleve el suelo.","why":"Sin estas obras, cada aguacero arrastra la capa fértil del suelo."},{"text":"**Fenómenos:** para la canícula, guardará agua de lluvia en toneles para sus hortalizas."}],"answer":"Doña Isabel sembrará **milpa en mayo**, con **curvas a nivel**, y cosechará antes de las heladas. Analizar la naturaleza le ayuda a **no perder** su cosecha.","tip":"Temperatura → lluvia → suelo → pendiente → fenómenos → decisión."},"id":"s04-pyd-1-7"},{"fase":"aplicar","areas":["pyd"],"cnb":["pyd:2.5.3"],"ambito":"emprender","prompt":"Don Tomás tiene un terreno **sin riego** en una región donde las lluvias empiezan como en la mayor parte del país. Mueve el calendario al **mes** en el que conviene sembrar su milpa.","explain":"Sin riego, la semilla necesita humedad para germinar: por eso se siembra al empezar las lluvias, alrededor de mayo (en algunas zonas se adelanta o se atrasa un poco).","type":"slider","props":{"min":1,"max":12,"step":1,"answer":5,"tolerance":1,"start":1,"visual":"line","display":"number","unit":"mes","ticks":[{"value":1,"label":"Ene"},{"value":3,"label":"Mar"},{"value":5,"label":"May"},{"value":7,"label":"Jul"},{"value":9,"label":"Sep"},{"value":11,"label":"Nov"}]},"id":"s04-pyd-1-8"},{"fase":"aplicar","areas":["pyd"],"cnb":["pyd:2.5.3"],"ambito":"hacer","prompt":"Une cada **fenómeno o condición** de la naturaleza con la **medida** que ayuda a producir a pesar de ella.","explain":"Conocer los fenómenos permite prevenir pérdidas: cada uno tiene una respuesta adecuada.","type":"match","props":{"leftTitle":"Fenómeno o condición","rightTitle":"Medida","pairs":[{"id":"m1","left":"Heladas en diciembre","leftIcon":"Snowflake","right":"Cosechar antes o sembrar cultivos que resisten el frío"},{"id":"m2","left":"Canícula a mitad de las lluvias","leftIcon":"Sun","right":"Guardar agua de lluvia y usar variedades resistentes a la sequía"},{"id":"m3","left":"Aguaceros fuertes en una ladera","leftIcon":"CloudRain","right":"Hacer terrazas o curvas a nivel"},{"id":"m4","left":"Suelo arenoso que no guarda agua","leftIcon":"Shovel","right":"Agregar abono orgánico"}]},"id":"s04-pyd-1-9"},{"fase":"aplicar","areas":["pyd"],"cnb":["pyd:2.5.3"],"ambito":"emprender","prompt":"No todo es sembrar. Una comunidad de **tierra caliente** junto a un lago, con mucho sol y bosque cercano, quiere **otra forma de producir** además de sus cultivos. ¿Qué opción aprovecha mejor su naturaleza **sin dañarla**?","explain":"Analizar la naturaleza también sirve para elegir otras actividades: la apicultura aprovecha las flores del bosque (y las abejas ayudan a polinizar), y el turismo comunitario vive de la belleza del lago.","type":"choice","props":{"options":[{"id":"a","text":"Criar abejas para miel y ofrecer turismo comunitario en el lago"},{"id":"b","text":"Sembrar trigo y papa","feedback":"El trigo y la papa necesitan clima frío; en tierra caliente no se darían bien."},{"id":"c","text":"Talar el bosque para sembrar más","feedback":"Talar el bosque daña el agua y el suelo, y acaba con otras formas de producir."}],"correct":["a"]},"id":"s04-pyd-1-10"},{"fase":"comprobar","areas":["pyd"],"cnb":["pyd:2.5.3"],"prompt":"En un terreno **sin riego**, ¿cuándo conviene sembrar la milpa?","type":"choice","props":{"options":[{"id":"a","text":"Al empezar la época de lluvias"},{"id":"b","text":"A mitad de la época seca"},{"id":"c","text":"Cuando caen las heladas"}],"correct":["a"]},"id":"s04-pyd-1-11"},{"fase":"comprobar","areas":["pyd"],"cnb":["pyd:2.5.3"],"prompt":"¿Verdadero o falso?","type":"true-false","props":{"statements":[{"text":"A más altura, la temperatura suele ser más baja.","answer":true},{"text":"El suelo franco es una mezcla equilibrada, buena para la mayoría de cultivos.","answer":true},{"text":"El café es un cultivo típico de tierra fría con heladas.","answer":false,"why":"El café crece en tierra templada; las heladas lo dañan."},{"text":"Las terrazas ayudan a que la lluvia no arrastre el suelo de una ladera.","answer":true}]},"id":"s04-pyd-1-12"},{"fase":"reflexionar","ambito":"ser","prompt":"¿Cómo te fue? Responde con sinceridad: aprender es un camino.","areas":["pyd"],"cnb":["pyd:2.5.3"],"type":"reflection","props":{"statements":["Explico cómo el clima, la lluvia y el suelo deciden qué se puede producir","Relaciono cultivos con tierra caliente, templada y fría","Propongo medidas ante heladas, canícula y lluvias fuertes"],"commitments":["Preguntaré a un agricultor de mi familia o comunidad cómo decide cuándo sembrar"]},"id":"s04-pyd-1-13"}],"kind":"materia","area":"pyd","day":3}},{"missionId":"s04","version":"cnb-sexto-2a8bd7f56f0a2a38","lesson":{"id":"s04-l1-4","title":"Títeres y marionetas","icon":"Smile","minutes":14,"gancho":"Con un calcetín viejo y dos botones puedes crear un personaje que hable, cante y haga reír. ¿Cómo es posible?","objetivos":["Distinguir y manejar títeres y marionetas para comunicar un mensaje"],"resumen":["Títeres de guante (o guiñol): se meten en la mano como un guante; con los dedos se mueven la cabeza y los brazos.","Títeres de dedo: pequeños, uno en cada dedo. Títeres de varilla: se mueven con palitos desde abajo. Títeres de sombra: siluetas que se proyectan con luz sobre una tela.","Marionetas: muñecos que se mueven desde arriba con hilos atados a una cruceta.","Para manejar un títere: el muñeco mira al público, mueve la boca solo cuando habla y se mantiene a la misma altura, como si caminara sobre un piso."],"media":{"id":"s04-l1-4-titeres","kind":"image","title":"Familia de títeres","aspect":"16:9","alt":"Cinco tipos de muñecos teatrales rotulados: títere de guante hecho con calcetín, títeres de dedo, títere de varilla, silueta de sombra detrás de una tela iluminada y una marioneta con hilos.","brief":"Ilustración en cinco paneles en fila: (1) títere de guante hecho con calcetín, botones y lana, con la mano visible dentro; (2) cuatro títeres de dedo de papel (quetzal, jaguar, niña, abuelo); (3) títere de varilla de cartón con palitos de bambú; (4) una tela blanca iluminada por una linterna, con la silueta de un venado en sombra; (5) marioneta de madera con hilos atados a una cruceta sostenida desde arriba. Rótulos grandes bajo cada panel. Materiales reciclados, colores alegres. Dimensiones: 1600x900."},"steps":[{"fase":"explorar","areas":["l1"],"cnb":["l1:5.1.8"],"title":"Idea central","prompt":"Un títere puede comunicar una duda con respeto si se maneja con técnica y una voz clara.","type":"explain","props":{"icon":"BookOpenCheck","body":"Títeres de guante (o guiñol): se meten en la mano como un guante; con los dedos se mueven la cabeza y los brazos."},"id":"s04-l1-4-1"},{"fase":"construir","areas":["l1"],"cnb":["l1:5.1.8"],"ambito":"conocer","prompt":"Observa la imagen. ¿Qué diferencia hay entre el títere de calcetín y la marioneta?","explain":"El títere de guante se mueve con la mano **desde abajo, por dentro**; la marioneta se mueve **desde arriba, con hilos**. Hoy conocerás todos los tipos.","type":"choice","props":{"options":[{"id":"a","text":"El títere de calcetín se mueve con la mano por dentro; la marioneta, desde arriba con hilos","icon":"Hand"},{"id":"b","text":"Ninguna: son exactamente lo mismo","icon":"Copy","feedback":"Mira de dónde sale la mano o los hilos en cada uno."},{"id":"c","text":"La marioneta solo se usa en el cine","icon":"Film","feedback":"Las marionetas se usan en el teatro desde hace muchísimos años."}],"correct":["a"]},"id":"s04-l1-4-2"},{"fase":"construir","areas":["l1"],"cnb":["l1:5.1.8"],"ambito":"conocer","title":"Tipos de títeres","prompt":"Los **títeres** son muñecos que cobran vida gracias a una persona llamada **titiritero** o **titiritera**. Toca cada tarjeta.","type":"explain","props":{"icon":"Smile","body":"El teatro de títeres existe en muchas culturas del mundo desde hace siglos. Se presenta en un **teatrino**: un pequeño escenario detrás del cual se esconden quienes manejan los muñecos.","reveal":[{"icon":"Hand","front":"De guante (guiñol)","back":"Se meten en la mano **como un guante**. Un dedo mueve la cabeza y otros dos los brazos. Los de calcetín abren y cierran la boca."},{"icon":"PenTool","front":"De dedo","back":"**Pequeños**, uno por dedo. Ideales para historias con muchos personajes y poco espacio."},{"icon":"Ruler","front":"De varilla","back":"Se sostienen y mueven con **palitos o varillas desde abajo**. Pueden mover brazos con varillas extra."},{"icon":"Sun","front":"De sombra","back":"Siluetas recortadas que se colocan entre una **luz** y una **tela o papel**: el público ve la sombra."},{"icon":"Link","front":"Marionetas","back":"Muñecos que se mueven **desde arriba con hilos** atados a una cruz de madera (cruceta). Son las más difíciles de manejar."}]},"id":"s04-l1-4-3"},{"fase":"construir","areas":["l1"],"cnb":["l1:5.1.8"],"ambito":"hacer","prompt":"Clasifica cada descripción según el tipo de muñeco.","hint":"Pregunta clave: ¿desde dónde se mueve? ¿Por dentro, desde abajo con palitos, desde arriba con hilos, o con luz?","explain":"La forma de moverlo define el tipo: guante (por dentro), varilla (desde abajo), marioneta (desde arriba), sombra (con luz).","type":"sort","props":{"buckets":[{"id":"gua","label":"Títere de guante","icon":"Hand","color":"var(--area-l1)"},{"id":"var","label":"Títere de varilla","icon":"Ruler","color":"var(--c-ok)"},{"id":"mar","label":"Marioneta","icon":"Link","color":"var(--c-maiz-strong)"},{"id":"som","label":"Títere de sombra","icon":"Sun","color":"var(--area-art)"}],"items":[{"id":"s1","text":"Un calcetín con botones de ojos que abre la boca","bucket":"gua"},{"id":"s2","text":"Un jaguar de cartón pegado a un palito de bambú","bucket":"var"},{"id":"s3","text":"Un muñeco de madera colgado de cinco hilos","bucket":"mar"},{"id":"s4","text":"La silueta de un venado detrás de una sábana iluminada","bucket":"som"},{"id":"s5","text":"Un muñeco de tela en el que metes toda la mano","bucket":"gua"}]},"id":"s04-l1-4-4"},{"fase":"construir","areas":["l1"],"cnb":["l1:5.1.8"],"ambito":"hacer","title":"Cómo dar vida a un títere","prompt":"Un títere mal manejado parece un trapo; uno bien manejado parece vivo. Toca cada tarjeta.","type":"explain","props":{"icon":"Sparkles","body":"El secreto está en que **el público olvide la mano** y solo vea al personaje.","reveal":[{"icon":"Eye","front":"Mira al público","back":"El títere debe mirar hacia el público (o hacia el personaje con quien habla), no al techo."},{"icon":"MessageCircle","front":"Boca con las sílabas","back":"Abre la boca del títere **una vez por sílaba** mientras habla. Cuando otro habla, el tuyo se queda quieto y escucha."},{"icon":"Minus","front":"Altura constante","back":"Mantén el títere a la **misma altura**, como si caminara sobre un piso invisible. Si baja y sube sin razón, parece que se hunde."},{"icon":"Volume2","front":"Una voz propia","back":"Dale a cada títere una **voz diferente** (más aguda, más grave, más lenta) y úsala siempre igual."}]},"id":"s04-l1-4-5"},{"fase":"aplicar","areas":["l1"],"cnb":["l1:5.1.8"],"ambito":"hacer","prompt":"Mientras el títere de la abuela habla, el títere del niño **mueve la boca sin parar**. ¿Qué problema causa?","explain":"El público no sabe quién está hablando. Solo mueve la boca el títere que habla; los demás se quedan quietos y \\"escuchan\\".","type":"choice","props":{"options":[{"id":"a","text":"El público no sabe cuál de los dos está hablando"},{"id":"b","text":"Ninguno: se ve más divertido","feedback":"Puede ser gracioso un momento, pero confunde al público."},{"id":"c","text":"Que el títere se rompe","feedback":"El problema no es del material, sino de la comunicación."}],"correct":["a"]},"id":"s04-l1-4-6"},{"fase":"aplicar","areas":["l1","art"],"cnb":["l1:5.1.9"],"ambito":"hacer","title":"Actividad en casa: tu títere de calcetín","prompt":"Sigue los pasos para hacer tu propio títere. Materiales: un calcetín viejo, dos botones o tapitas, lana o tiras de tela, un pedazo de cartón y pegamento (o hilo y aguja con ayuda de un adulto).","type":"worked-example","props":{"icon":"Scissors","problem":"Hacer un títere de guante que abra y cierre la boca.","steps":[{"text":"Mete la mano en el calcetín: los cuatro dedos arriba y el pulgar abajo. Empuja la punta del calcetín hacia adentro para formar la **boca**."},{"text":"Recorta un óvalo de cartón, dóblalo a la mitad y pégalo dentro de la boca para que sea firme.","why":"El cartón hace que la boca se abra y cierre con claridad."},{"text":"Pega o cose los **ojos** (botones o tapitas) arriba de la boca."},{"text":"Agrega **pelo** con lana y detalles con tela: un sombrero, un rebozo, orejas de animal."},{"text":"Ponle un **nombre** y elige su **voz**."}],"answer":"¡Listo! Tu títere de guante tiene boca, ojos, pelo, nombre y voz propia.","tip":"Si usas aguja o tijeras, pide ayuda a un adulto. Los materiales reciclados funcionan igual de bien."},"id":"s04-l1-4-7"},{"fase":"aplicar","areas":["l1"],"cnb":["l1:5.1.8"],"ambito":"hacer","prompt":"Presenta a tu títere de la campaña: escribe cómo se llama, qué tipo es, cómo es su voz y una línea de diálogo respetuosa que recomiende comprobar información o pedir apoyo.","type":"short-answer","props":{"minWords":20,"placeholder":"Nombre: …\\nTipo: …\\nVoz: …\\nDiálogo: NOMBRE: (…) …","model":"Nombre: Clara\\nTipo: títere de guante hecho con un calcetín\\nVoz: cálida y pausada\\nDiálogo: CLARA: (muestra un libro al público) Antes de repetir un rumor sobre el cuerpo, comprobemos la información con una fuente confiable.","rubric":["Dije el nombre y el tipo de títere","Describí cómo es su voz","Escribí una línea con formato de guion y una acotación"]},"id":"s04-l1-4-8"},{"fase":"comprobar","areas":["l1"],"cnb":["l1:5.1.8"],"prompt":"Un muñeco que se mueve **desde arriba con hilos** es…","type":"choice","props":{"options":[{"id":"a","text":"Una marioneta"},{"id":"b","text":"Un títere de guante"},{"id":"c","text":"Un títere de sombra"}],"correct":["a"]},"id":"s04-l1-4-9"},{"fase":"comprobar","areas":["l1"],"cnb":["l1:5.1.8"],"prompt":"Al manejar un títere, ¿cuándo debe moverse su boca?","type":"choice","props":{"options":[{"id":"a","text":"Solo cuando ese personaje habla, una vez por sílaba"},{"id":"b","text":"Todo el tiempo, para que parezca vivo"},{"id":"c","text":"Nunca"}],"correct":["a"]},"id":"s04-l1-4-10"}],"kind":"materia","area":"l1","day":4}},{"missionId":"s04","version":"cnb-sexto-043692b31e90cf1f","lesson":{"id":"s04-l1-5","title":"Recursos para escenificar: máscaras, vestuario, decorado y sonido","icon":"Palette","minutes":15,"gancho":"Con una luz tranquila, un libro de utilería y un sonido breve, el público puede reconocer un lugar de escucha y cuidado. ¿Cómo lo logra el teatro?","objetivos":["Elegir recursos de escenificación que apoyen una escena sin distraer"],"resumen":["Recursos que caracterizan al personaje: vestuario, maquillaje, máscaras y utilería personal (un bastón, un canasto). Ayudan a saber quién es, su edad y su carácter.","Recursos que crean el ambiente: decorado o escenografía (el lugar), iluminación (el momento del día o la emoción) y efectos de sonido (lluvia, viento, pasos).","Los efectos de sonido se pueden hacer con objetos: semillas en un bote suenan a lluvia; sacudir una lámina, a trueno; dos medios cocos, a caballo.","Los recursos se eligen según lo que pide la escena: deben ayudar a contar la historia, no distraer."],"media":{"id":"s04-l1-5-teatrino","kind":"video","title":"Crecer con cuidado en el teatrino","aspect":"16:9","duration":75,"alt":"Dos títeres representan a una estudiante que tiene una duda y a una persona adulta que escucha y muestra un libro de Ciencias.","brief":"Video de 75 s de un teatrino de cartón con fondo de biblioteca escolar. Dos títeres de guante representan a una estudiante con una duda y a una persona adulta que escucha sin juzgar y muestra un libro de Ciencias. Una campanilla suave marca el inicio, una tarjeta grande dice “Fuente confiable” y una luz cálida ilumina el diálogo. Al final se muestran los recursos detrás del teatrino. No representar cambios corporales ni usar disfraces que caricaturicen profesiones o identidades. Accesibilidad: subtitulos completos para toda voz y transcripcion audiovisual; rotulos grandes, legibles y de alto contraste."},"steps":[{"fase":"explorar","areas":["l1"],"cnb":["l1:5.1.9"],"title":"Idea central","prompt":"La campaña necesita recursos de escena que aclaren el mensaje sin exponer ni caricaturizar a nadie.","type":"explain","props":{"icon":"BookOpenCheck","body":"Recursos que caracterizan al personaje: vestuario, maquillaje, máscaras y utilería personal (un bastón, un canasto). Ayudan a saber quién es, su edad y su carácter."},"id":"s04-l1-5-1"},{"fase":"construir","areas":["l1"],"cnb":["l1:5.1.9"],"ambito":"conocer","prompt":"Mira el video. ¿Qué recursos hacen que la escena parezca un espacio tranquilo para escuchar y comprobar información?","explain":"El fondo de biblioteca, la luz cálida, la campanilla y el libro de utilería construyen el ambiente y apoyan la acción.","type":"choice","props":{"options":[{"id":"a","text":"El fondo de biblioteca, la luz cálida, la campanilla y el libro","icon":"BookOpenCheck"},{"id":"b","text":"Solo los diálogos","icon":"MessageCircle","feedback":"Los diálogos cuentan la historia, pero el ambiente lo crean otros recursos."},{"id":"c","text":"Que lo filmaron en un centro de salud verdadero","icon":"Camera","feedback":"Fue en un teatrino de cartón: el ambiente se creó con recursos sencillos."}],"correct":["a"]},"id":"s04-l1-5-2"},{"fase":"construir","areas":["l1"],"cnb":["l1:5.1.9"],"ambito":"conocer","title":"Recursos que caracterizan al personaje","prompt":"Algunos recursos ayudan a saber **quién es** cada personaje. Toca cada tarjeta.","type":"explain","props":{"icon":"Shirt","body":"Al ver a un personaje, el público debe entender rápido su edad, su oficio, su carácter o si es humano, animal o ser mágico.","reveal":[{"icon":"Shirt","front":"Vestuario","back":"La ropa del personaje: un delantal para la vendedora, un sombrero y un morral para el agricultor, un rebozo para la abuela."},{"icon":"Brush","front":"Maquillaje","back":"Cambia el rostro: arrugas para parecer mayor, manchas para un jaguar, mejillas rojas para mostrar frío. Usa pinturas lavables y seguras para la piel."},{"icon":"Drama","front":"Máscaras","back":"Cubren el rostro y transforman al actor en otro ser. En Guatemala hay una gran tradición de **máscaras de madera** para danzas como la del Venado."},{"icon":"Hand","front":"Títeres","back":"Otra forma de dar vida a un personaje: el muñeco **es** el personaje."}]},"id":"s04-l1-5-3"},{"fase":"construir","areas":["l1"],"cnb":["l1:5.1.9"],"ambito":"conocer","title":"Recursos que crean el ambiente","prompt":"Otros recursos ayudan a saber **dónde y cuándo** ocurre la escena, y qué se siente. Toca cada tarjeta.","type":"explain","props":{"icon":"Mountain","body":"El **ambiente** transporta al público a otro lugar sin moverse de su asiento.","reveal":[{"icon":"Image","front":"Decorado (escenografía)","back":"Representa el **lugar**: un fondo pintado con volcanes, un petate y una olla para una cocina, pupitres para una escuela."},{"icon":"Lightbulb","front":"Iluminación","back":"Indica el **momento** (luz naranja = amanecer; luz tenue = noche) y la **emoción** (luz fuerte = alegría; penumbra = misterio). Con linternas y papel de colores se logra mucho."},{"icon":"Volume2","front":"Efectos de sonido","back":"Semillas en un bote = **lluvia**. Sacudir una lámina = **trueno**. Dos medios cocos = **caballo**. Soplar por un tubo = **viento**."},{"icon":"Music","front":"Música","back":"Una melodía de marimba, una flauta o un tambor pueden marcar el inicio, un cambio de escena o una emoción."}]},"id":"s04-l1-5-4"},{"fase":"construir","areas":["l1"],"cnb":["l1:5.1.9"],"ambito":"hacer","prompt":"Organiza los recursos de escenificación para la obra de títeres \\"Crecer con cuidado\\".","hint":"¿Este recurso cambia al personaje, o cambia el lugar y el ambiente?","explain":"Unos recursos transforman al personaje y otros transforman el espacio. Los dos son necesarios para que el público \\"entre\\" en la historia.","media":{"id":"s04-l1-5-mesa","kind":"image","title":"Detrás del teatrino","aspect":"4:3","alt":"Mesa con dos títeres, un libro de cartón, un gafete, un fondo de biblioteca, una campanilla y una linterna con papel amarillo.","brief":"Fotografía o ilustración cenital de una mesa escolar con materiales reciclados: dos títeres de calcetín, un libro de cartón, un gafete sencillo, un fondo pintado como biblioteca, una tarjeta “Fuente confiable”, una campanilla y una linterna con papel amarillo. Cada objeto tiene una etiqueta pequeña. Sin símbolos médicos engañosos ni marcas. Dimensiones: 1200x900. Accesibilidad: contraste alto, rotulos grandes y legibles; la descripcion visual debe corresponder exactamente al texto alternativo."},"type":"sort","props":{"buckets":[{"id":"per","label":"Caracteriza al personaje","icon":"User","color":"var(--area-l1)"},{"id":"amb","label":"Crea el ambiente","icon":"Mountain","color":"var(--area-art)"}],"items":[{"id":"r1","text":"Libro que lleva quien comprueba el dato","bucket":"per"},{"id":"r2","text":"Gafete de la persona orientadora","bucket":"per"},{"id":"r3","text":"Mochila de la estudiante","bucket":"per"},{"id":"r4","text":"Fondo pintado como biblioteca","bucket":"amb"},{"id":"r5","text":"Campanilla suave al inicio","bucket":"amb","feedback":"Es un efecto de sonido que marca el inicio sin tapar las voces."},{"id":"r6","text":"Luz cálida y moderada para el diálogo","bucket":"amb"}]},"id":"s04-l1-5-5"},{"fase":"aplicar","areas":["l1"],"cnb":["l1:5.1.9"],"ambito":"hacer","prompt":"Une cada acotación del guion con el recurso que la hace posible.","explain":"Las acotaciones del guion le dicen al equipo técnico qué recursos preparar.","type":"match","props":{"leftTitle":"Acotación","rightTitle":"Recurso","pairs":[{"id":"a1","left":"(Suena una notificación.)","right":"Dos golpecitos suaves en una campanilla"},{"id":"a2","left":"(La conversación se vuelve tranquila.)","right":"Luz cálida de intensidad moderada"},{"id":"a3","left":"(La orientadora muestra dónde comprobó el dato.)","right":"Libro de utilería con una marca visible"},{"id":"a4","left":"(Aparece el mensaje final.)","right":"Tarjeta grande: “Pregunta y comprueba”"}]},"id":"s04-l1-5-6"},{"fase":"aplicar","areas":["l1"],"cnb":["l1:5.1.9","l1:5.1.8"],"ambito":"hacer","prompt":"Lee este fragmento de la campaña y decide qué recursos necesita la escena.","type":"reading","props":{"genre":"Guion para títeres","heading":"Pregunta y comprueba (fragmento)","passage":"**Personajes:** ESTUDIANTE (títere con mochila). ORIENTADORA (títere con un libro).\\n\\n**Escena 1**\\n\\n_(Biblioteca escolar. Suena una notificación breve. Una luz cálida ilumina la mesa.)_\\n\\nESTUDIANTE: _(muestra una tarjeta, inquieta)_ Recibí un mensaje sobre los cambios del cuerpo. No dice quién lo escribió.\\n\\nORIENTADORA: _(escucha y abre el libro)_ Hiciste bien en preguntar antes de compartirlo. Busquemos una fuente confiable.\\n\\nESTUDIANTE: _(más tranquila)_ ¿Y si todavía tengo una pregunta personal?\\n\\nORIENTADORA: Puedes conversar con una persona adulta de confianza o un profesional de salud. _(Muestra la tarjeta “Pregunta y comprueba”.)_","questions":[{"q":"¿Qué efecto de sonido se necesita **al inicio**?","options":[{"id":"a","text":"Una notificación breve"},{"id":"b","text":"Un caballo galopando"},{"id":"c","text":"Un trueno fuerte"}],"correct":"a","why":"La acotación inicial indica una notificación breve."},{"q":"¿Qué recurso usa la orientadora para mostrar que comprueba el mensaje?","options":[{"id":"a","text":"Un libro de utilería"},{"id":"b","text":"Una máscara"},{"id":"c","text":"Una capa"}],"correct":"a","why":"La acotación indica que abre el libro y busca una fuente."},{"q":"¿Qué tarjeta debe aparecer al final?","options":[{"id":"a","text":"Pregunta y comprueba"},{"id":"b","text":"Comparte de inmediato"},{"id":"c","text":"Guarda todas tus dudas"}],"correct":"a","why":"La última acotación nombra esa tarjeta."}]},"id":"s04-l1-5-7"},{"fase":"aplicar","areas":["l1"],"cnb":["l1:5.1.9"],"ambito":"hacer","prompt":"Eres parte del equipo técnico de **\\"Crecer con cuidado\\"**. Haz una lista de recursos para la escena: dos que caractericen a los personajes sin estereotipos y dos que creen un ambiente tranquilo. Para cada uno, di con qué material sencillo lo harías.","type":"short-answer","props":{"minWords":30,"placeholder":"Personajes:\\n1. …\\n2. …\\nAmbiente:\\n3. …\\n4. …","model":"Personajes:\\n1. Libro para quien comprueba el dato: cartón doblado con una portada.\\n2. Gafete de la orientadora: papel y lana, sin disfrazar ni caricaturizar.\\nAmbiente:\\n3. Música instrumental tranquila: palmas suaves o un audio a volumen moderado.\\n4. Letrero “Escuchamos con respeto”: cartón reutilizado y marcadores.","rubric":["Incluí dos recursos para los personajes","Incluí dos recursos para el ambiente","Para cada recurso dije un material sencillo","Los recursos corresponden a lo que pide el guion"]},"id":"s04-l1-5-8"},{"fase":"comprobar","areas":["l1"],"cnb":["l1:5.1.9"],"prompt":"Una campanilla que marca el inicio de la escena es…","type":"choice","props":{"options":[{"id":"a","text":"Un efecto de sonido"},{"id":"b","text":"Un vestuario"},{"id":"c","text":"Un maquillaje"}],"correct":["a"]},"id":"s04-l1-5-9"},{"fase":"comprobar","areas":["l1"],"cnb":["l1:5.1.9"],"prompt":"Clasifica cada recurso.","type":"sort","props":{"buckets":[{"id":"per","label":"Caracteriza al personaje","icon":"User","color":"var(--area-l1)"},{"id":"amb","label":"Crea el ambiente","icon":"Mountain","color":"var(--area-art)"}],"items":[{"id":"z1","text":"Libro que lleva la orientadora","bucket":"per"},{"id":"z2","text":"Luz cálida para una conversación tranquila","bucket":"amb"},{"id":"z3","text":"Mochila de la estudiante","bucket":"per"},{"id":"z4","text":"Fondo pintado como biblioteca","bucket":"amb"}]},"id":"s04-l1-5-10"},{"fase":"reflexionar","areas":["l1"],"cnb":[],"ambito":"ser","prompt":"¿Cómo te fue esta semana en el mundo del teatro?","type":"reflection","props":{"statements":["Escribo un guion con la tipografía correcta","Participo en un juego de roles con respeto","Cuento una historia con pantomima","Distingo títeres, marionetas y recursos para escenificar"],"commitments":["Terminaré mi títere de calcetín y le daré una voz","Presentaré una pantomima o un juego de roles a mi familia","Buscaré en mi casa objetos que sirvan para efectos de sonido"]},"id":"s04-l1-5-11"}],"kind":"materia","area":"l1","day":5}},{"missionId":"s04","version":"cnb-sexto-8558625cdfd110eb","lesson":{"id":"s04-fc-2","title":"Revisar con criterios a quienes nos dirigen","icon":"ClipboardCheck","minutes":15,"gancho":"Si alguien de tu comunidad prometió arreglar el camino, ¿cómo sabes si cumplió? ¿Basta con lo que dicen los rumores?","objetivos":["Evaluar un liderazgo con hechos, criterios y propuestas de mejora"],"resumen":["Revisar críticamente un liderazgo es evaluar sus acciones con criterios y hechos, no con rumores ni insultos.","Cinco criterios: ¿consulta antes de decidir?, ¿informa y rinde cuentas?, ¿cumple lo que prometió?, ¿incluye a todas las personas?, ¿respeta las reglas y la ley?","Una buena crítica describe un hecho, lo compara con un criterio y propone una mejora.","La ciudadanía puede revisar a sus autoridades: participar en asambleas, pedir información pública (lo permite la Ley de Acceso a la Información Pública) y votar de forma informada. La Contraloría General de Cuentas revisa el uso del dinero público."],"media":{"id":"s04-fc-2-lista-cotejo","kind":"diagram","title":"La lista para revisar un liderazgo","aspect":"3:4","alt":"Una hoja de lista de cotejo con cinco criterios y casillas de sí o no, y una lupa sobre ella.","brief":"Diagrama tipo hoja de cuaderno con título \\"¿Cómo lidera?\\". Cinco filas con ícono y casillas \\"Sí / No\\": (1) Consulta antes de decidir (ícono de mano levantada); (2) Informa y rinde cuentas (hoja con monedas); (3) Cumple lo que prometió (check); (4) Incluye a todas las personas (grupo diverso); (5) Respeta las reglas y la ley (balanza). Al pie: \\"Hecho → criterio → propuesta\\". Una lupa en la esquina. Estilo limpio, fondo claro, letras grandes. Dimensiones: 900x1200. Accesibilidad: contraste alto, rotulos grandes y legibles; la descripcion visual debe corresponder exactamente al texto alternativo."},"steps":[{"fase":"explorar","areas":["fc"],"cnb":["fc:3.1.1"],"title":"Idea central","prompt":"Revisar un liderazgo con hechos protege la participación y evita rumores o ataques.","type":"explain","props":{"icon":"BookOpenCheck","body":"Revisar críticamente un liderazgo es evaluar sus acciones con criterios y hechos, no con rumores ni insultos."},"id":"s04-fc-2-1"},{"fase":"construir","areas":["fc"],"cnb":["fc:3.1.1"],"ambito":"conocer","prompt":"Se dice en la tienda que \\"el comité se robó el dinero del camino\\". ¿Qué deberías hacer **antes** de repetirlo?","explain":"Un rumor no es una prueba. Para revisar un liderazgo de forma justa, se buscan **hechos**: documentos, informes, preguntas directas. Hoy aprenderás a hacerlo con criterios.","type":"choice","props":{"options":[{"id":"a","text":"Buscar información: preguntar al comité por el informe de gastos","icon":"Search"},{"id":"b","text":"Contárselo a todos los vecinos de inmediato","icon":"Megaphone","feedback":"Si el rumor es falso, se daña a personas inocentes. Primero hay que buscar hechos."},{"id":"c","text":"Escribir un insulto en las redes sociales","icon":"Smartphone","feedback":"Un insulto no revisa nada y puede ser injusto. La crítica útil se basa en hechos."}],"correct":["a"]},"id":"s04-fc-2-2"},{"fase":"construir","areas":["fc"],"cnb":["fc:3.1.1"],"ambito":"conocer","title":"Cinco criterios para revisar un liderazgo","prompt":"**Revisar críticamente** es evaluar las acciones de un líder comparándolas con **criterios** claros. Toca cada criterio.","type":"explain","props":{"icon":"ClipboardCheck","body":"Estos cinco criterios sirven igual para el gobierno escolar, un comité, la municipalidad o el Congreso.","reveal":[{"icon":"Hand","front":"1. Consulta","back":"¿Pregunta y escucha a las personas antes de decidir cosas importantes?"},{"icon":"FileText","front":"2. Rinde cuentas","back":"¿Informa qué hizo, cuánto gastó y en qué? ¿Muestra documentos?"},{"icon":"Check","front":"3. Cumple","back":"¿Hizo lo que prometió? ¿En el tiempo acordado?"},{"icon":"Users","front":"4. Incluye","back":"¿Toma en cuenta a mujeres, jóvenes, personas mayores, personas con discapacidad y a todos los pueblos?"},{"icon":"Scale","front":"5. Respeta la ley","back":"¿Sigue las reglas de la organización y las leyes del país? ¿Deja el cargo al terminar su periodo?"}]},"id":"s04-fc-2-3"},{"fase":"construir","areas":["fc"],"cnb":["fc:3.1.1"],"ambito":"convivir","title":"Crítica útil o ataque","prompt":"Criticar es un **derecho y una responsabilidad** ciudadana, pero hay formas que ayudan y formas que dañan. Toca cada tarjeta.","type":"explain","props":{"icon":"MessageCircle","body":"Una **crítica útil** tiene tres partes: **hecho** (qué pasó) → **criterio** (qué debería pasar) → **propuesta** (cómo mejorar).","reveal":[{"icon":"ThumbsUp","front":"Crítica útil","back":"\\"El comité no ha presentado el informe de gastos en seis meses (hecho). Un buen liderazgo rinde cuentas (criterio). Pedimos que lo presente en la próxima asamblea (propuesta).\\""},{"icon":"X","front":"Ataque","back":"\\"¡Todos los del comité son unos ladrones!\\" No da hechos, generaliza e insulta. No ayuda a mejorar y puede ser injusto."},{"icon":"Ear","front":"Rumor","back":"\\"Dicen que…\\". Información sin fuente ni prueba. Antes de repetirla, hay que verificarla."}]},"id":"s04-fc-2-4"},{"fase":"construir","areas":["fc"],"cnb":["fc:3.1.1"],"prompt":"Clasifica cada comentario sobre un líder: ¿es una **crítica útil** o un **ataque o rumor**?","hint":"Una crítica útil menciona un hecho concreto y, de preferencia, propone algo. Un ataque insulta o generaliza; un rumor no tiene prueba.","explain":"La crítica útil se basa en hechos verificables y busca mejorar; el ataque y el rumor dañan la convivencia y no resuelven nada.","type":"sort","props":{"buckets":[{"id":"ok","label":"Crítica útil","icon":"ThumbsUp","color":"var(--c-ok)"},{"id":"no","label":"Ataque o rumor","icon":"X","color":"var(--c-maiz-strong)"}],"items":[{"id":"c1","text":"\\"La presidenta prometió reparar la cancha en marzo y en junio sigue igual. Proponemos pedirle un calendario.\\"","bucket":"ok"},{"id":"c2","text":"\\"Dicen que el alcalde tiene tres carros nuevos.\\"","bucket":"no","feedback":"\\"Dicen que\\" sin fuente es un rumor. Habría que verificarlo con información pública."},{"id":"c3","text":"\\"Ese presidente del grado es un tonto.\\"","bucket":"no"},{"id":"c4","text":"\\"En la asamblea no dejaron hablar a las mujeres. Sugerimos una lista de turnos para que todos opinen.\\"","bucket":"ok"},{"id":"c5","text":"\\"Todos los políticos son iguales.\\"","bucket":"no","feedback":"Generaliza y no permite distinguir a quien hace bien su trabajo de quien no."}]},"id":"s04-fc-2-5"},{"fase":"construir","areas":["fc"],"cnb":["fc:3.1.1"],"ambito":"hacer","title":"Ejemplo resuelto: revisar al comité de agua","prompt":"Así se usa la lista de cinco criterios con un caso. Revela cada paso.","type":"worked-example","props":{"icon":"Droplets","problem":"Supongamos estos **hechos** sobre el comité de agua de la aldea Los Cipreses: (1) hizo asamblea antes de subir la cuota; (2) presentó un informe de gastos con recibos; (3) prometió reparar la tubería en un mes y tardó cuatro; (4) solo participan hombres en la directiva; (5) cambió a su directiva cuando terminó su periodo.","steps":[{"text":"Criterio 1, consulta: **sí** (hizo asamblea)."},{"text":"Criterio 2, rinde cuentas: **sí** (informe con recibos)."},{"text":"Criterio 3, cumple: **no del todo** (tardó cuatro meses en lugar de uno)."},{"text":"Criterio 4, incluye: **no** (no hay mujeres en la directiva).","why":"Las mujeres usan y acarrean el agua a diario: su voz es necesaria en el comité."},{"text":"Criterio 5, respeta las reglas: **sí** (cambió la directiva a tiempo)."}],"answer":"El comité cumple **3 de 5** criterios: es un liderazgo mayormente democrático que debe mejorar en **cumplir a tiempo** e **incluir a mujeres**.","tip":"Una revisión justa reconoce lo que se hace bien y propone mejoras concretas."},"id":"s04-fc-2-6"},{"fase":"aplicar","areas":["fc"],"cnb":["fc:3.1.1"],"ambito":"hacer","prompt":"Revisa al gobierno escolar de una escuela con los cinco criterios. **Hechos:** eligió los proyectos votando en cada grado; no ha informado cuánto dinero recaudó en la kermés; terminó el mural que prometió; su comisión de deportes incluye niñas y niños; respeta el reglamento de la escuela. ¿Cuántos criterios **cumple**?","explain":"Consulta ✔, rinde cuentas ✘, cumple ✔, incluye ✔, respeta reglas ✔ → cumple **4 de 5**. Debe mejorar en informar el dinero de la kermés.","type":"number-input","props":{"answer":4,"unit":"de 5 criterios","misconceptions":[{"value":5,"msg":"Revisa el criterio de rendir cuentas: ¿informó el dinero de la kermés?"},{"value":3,"msg":"Revisa otra vez: votar en cada grado es consultar, y terminar el mural es cumplir."}]},"id":"s04-fc-2-7"},{"fase":"aplicar","areas":["fc"],"cnb":["fc:3.1.1"],"ambito":"conocer","prompt":"Lee sobre las herramientas que tiene la ciudadanía para revisar a las autoridades del país y responde.","type":"reading","props":{"genre":"Texto informativo","heading":"La ciudadanía también vigila","passage":"En Guatemala, la población elige por voto a sus autoridades: al presidente o presidenta, a los diputados del Congreso y a los alcaldes y concejos municipales. Estos cargos duran **cuatro años**. Pero la participación ciudadana no termina el día de la elección.\\n\\nLa **Ley de Acceso a la Información Pública** permite que cualquier persona pida a las instituciones del Estado información sobre cómo usan el dinero y qué proyectos realizan. La **Contraloría General de Cuentas** revisa el uso de los fondos públicos. En las comunidades, los **COCODE** y las asambleas permiten que los vecinos pregunten y propongan.\\n\\nCon esa información, la gente puede revisar si sus autoridades consultan, rinden cuentas, cumplen, incluyen a todos y respetan la ley. Así, en la próxima elección, el voto puede ser **informado** y no solo por simpatía o por un regalo.","questions":[{"q":"¿Cada cuánto se elige a las autoridades nacionales y municipales en Guatemala?","options":[{"id":"a","text":"Cada cuatro años"},{"id":"b","text":"Cada año"},{"id":"c","text":"Nunca, son para siempre"}],"correct":"a"},{"q":"¿Qué permite la Ley de Acceso a la Información Pública?","options":[{"id":"a","text":"Que cualquier persona pida información sobre cómo el Estado usa el dinero y sus proyectos"},{"id":"b","text":"Que las autoridades escondan sus gastos"},{"id":"c","text":"Que solo los diputados sepan lo que pasa"}],"correct":"a"},{"q":"¿Qué significa votar de forma \\"informada\\"?","options":[{"id":"a","text":"Elegir después de revisar lo que cada candidato hizo y propone"},{"id":"b","text":"Votar por quien regala más cosas"},{"id":"c","text":"Votar por el más famoso"}],"correct":"a","why":"Un voto informado se basa en hechos y propuestas, no en regalos ni simpatías."}]},"id":"s04-fc-2-8"},{"fase":"aplicar","areas":["fc"],"cnb":["fc:3.1.1"],"ambito":"hacer","prompt":"Vas a **entrevistar** a una persona que lidera una organización de tu comunidad (COCODE, comité, cooperativa, iglesia, gobierno escolar). Escribe **tres preguntas abiertas** basadas en los criterios, y di qué criterio revisa cada una.","type":"short-answer","props":{"minWords":30,"placeholder":"1. ¿…? (criterio: …)","model":"1. ¿Cómo toman las decisiones importantes en el comité? (criterio: consulta) 2. ¿De qué forma informan a la comunidad sobre el dinero y los proyectos? (criterio: rinde cuentas) 3. ¿Cómo participan las mujeres y los jóvenes en la directiva? (criterio: incluye). Anotaré las respuestas en mi cuaderno con la fecha de la entrevista.","rubric":["Escribí tres preguntas abiertas (no se responden solo con sí o no)","Cada pregunta revisa un criterio distinto","Las preguntas son respetuosas","Dije cómo registraré las respuestas"]},"id":"s04-fc-2-9"},{"fase":"comprobar","areas":["fc"],"cnb":["fc:3.1.1"],"prompt":"¿Cuál de estas frases es una **crítica útil** al gobierno escolar?","type":"choice","props":{"options":[{"id":"a","text":"\\"No han informado cuánto se recaudó en la venta; pedimos que lo publiquen en el periódico mural.\\""},{"id":"b","text":"\\"El gobierno escolar no sirve para nada.\\""},{"id":"c","text":"\\"Dicen que la tesorera se quedó con el dinero.\\""}],"correct":["a"]},"id":"s04-fc-2-10"},{"fase":"comprobar","areas":["fc"],"cnb":["fc:3.1.1"],"prompt":"Une cada hecho con el **criterio** que revisa.","type":"match","props":{"leftTitle":"Hecho","rightTitle":"Criterio","pairs":[{"id":"h1","left":"El alcalde publicó el costo del puente","right":"Rinde cuentas"},{"id":"h2","left":"La presidenta preguntó a los vecinos antes de decidir","right":"Consulta"},{"id":"h3","left":"El comité terminó la obra en la fecha prometida","right":"Cumple"},{"id":"h4","left":"La directiva tiene mujeres, jóvenes y ancianos","right":"Incluye"}]},"id":"s04-fc-2-11"},{"fase":"reflexionar","ambito":"ser","prompt":"¿Cómo te fue? Responde con sinceridad: aprender es un camino.","areas":["fc"],"cnb":["fc:3.1.1"],"type":"reflection","props":{"statements":["Distingo el liderazgo democrático del autoritario","Reviso un liderazgo con cinco criterios y hechos","Diferencio una crítica útil de un ataque o un rumor"],"commitments":["Haré mi entrevista a una persona que lidera en mi comunidad","Antes de repetir un rumor, buscaré si es verdad","Cuando dirija un grupo, consultaré e informaré a todos"]},"id":"s04-fc-2-12"}],"kind":"materia","area":"fc","day":5}},{"missionId":"s04","version":"cnb-sexto-c6cbd7d0f50a8582","lesson":{"id":"s04-d5-taller","kind":"taller","day":5,"title":"Campaña: crecer con cuidado","icon":"Drama","minutes":19,"gancho":"¿Cómo puede una escena breve responder una duda sobre crecer sin asustar, avergonzar ni repetir rumores?","objetivos":["Crear una campaña informativa con una escena dramática científicamente correcta, respetuosa y participativa, acompañada por música elegida con criterio"],"resumen":["Una campaña de salud usa información comprobable y dice de dónde procede.","Una escena informativa presenta una duda, una respuesta clara y una acción de cuidado.","El lenguaje respetuoso reconoce que cada cuerpo cambia a su ritmo y evita burlas, estereotipos y diagnósticos.","Un fragmento instrumental se elige por su carácter e intensidad: debe apoyar el mensaje sin tapar las voces.","Un liderazgo democrático escucha al equipo, reparte tareas y revisa el producto con criterios comunes."],"media":{"id":"s04-d5-taller-campana","kind":"image","title":"Mesa de campaña escolar","aspect":"16:9","alt":"Guion de una escena breve, tarjetas de fuentes confiables, títeres sencillos y una lista de revisión sobre ciencia y respeto.","brief":"Vista cenital de una mesa escolar. Se ven un guion titulado \\"Crecer con cuidado\\", dos títeres de papel, tarjetas que dicen \\"libro de Ciencias\\", \\"persona adulta de confianza\\" y \\"centro de salud\\", una nota anónima marcada como rumor, y una lista de revisión con dos casillas: exactitud científica y lenguaje respetuoso. Sin imágenes anatómicas ni marcas comerciales. Dimensiones: 1600x900. Accesibilidad: contraste alto, rotulos grandes y legibles; la descripcion visual debe corresponder exactamente al texto alternativo."},"steps":[{"fase":"explorar","areas":["cnt"],"cnb":["cnt:3.3.1"],"ambito":"conocer","title":"Punto de partida · 1 min","prompt":"La campaña no diagnostica ni promete que todos los cuerpos cambian igual. Presenta información general, reconoce la variación normal y orienta a pedir ayuda cuando una duda preocupa.","type":"explain","props":{"icon":"ShieldCheck","body":"Una respuesta responsable combina un dato científico sencillo, lenguaje respetuoso y una fuente confiable.","reveal":[{"icon":"BookOpenCheck","front":"Dato","back":"Debe coincidir con lo estudiado en Ciencias y no convertir una variación normal en un problema."},{"icon":"HeartHandshake","front":"Respeto","back":"Habla de personas y cuerpos sin burlas, culpa, vergüenza ni estereotipos."},{"icon":"Stethoscope","front":"Orientación","back":"Ante dolor, preocupación o una pregunta personal, recomienda hablar con una persona adulta de confianza o un profesional de salud."}]},"id":"s04-d5-taller-1"},{"fase":"construir","areas":["cnt","fc"],"cnb":["cnt:3.3.1","fc:3.1.1"],"ambito":"convivir","title":"Etapa 1: acuerdo compartido · 2 min","prompt":"En pareja, escuchen dos propuestas y acuerden una sola duda para la campaña: ritmos de la pubertad, cuidado de la intimidad o información confiable. Elijan juntos quién preguntará y quién responderá.","type":"project","props":{"goal":"Negociar un mensaje y dos roles para una escena dramática informativa.","steps":[{"title":"Escuchen","detail":"Cada integrante propone una duda y explica por qué puede ayudar a otras personas."},{"title":"Acuerden","detail":"Elijan juntos una duda y repartan los dos roles; ninguna persona decide por todo el equipo."}],"evidence":"Una duda compartida y dos roles acordados.","rubric":["La decisión incorpora las voces de ambas personas","La escena tendrá una sola idea central"]},"id":"s04-d5-taller-2"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:3.3.1"],"ambito":"conocer","title":"Etapa 2: verifica la ciencia · 2 min","prompt":"Anota el dato científico que usarás y la fuente confiable que permite comprobarlo.","type":"project","props":{"goal":"Sostener la campaña informativa con información verificable.","steps":[{"title":"Dato","detail":"Escribe un dato enseñado esta semana, sin añadir diagnósticos ni reglas absolutas."},{"title":"Fuente","detail":"Nombra el libro o lección de Ciencias y una persona adulta de confianza o profesional de salud a quien se podría consultar."}],"evidence":"Dato científicamente correcto y fuente confiable identificada.","rubric":["El dato tiene exactitud científica","La fuente confiable se puede identificar"]},"id":"s04-d5-taller-3"},{"fase":"aplicar","areas":["l1","cnt"],"cnb":["l1:5.1.8","cnt:3.3.1"],"ambito":"hacer","title":"Etapa 3: mensaje de la escena · 2 min","prompt":"Escriban un mensaje de 18 a 24 palabras que pueda repartirse entre dos voces: dato científico, respeto y una orientación hacia una fuente confiable.","type":"short-answer","props":{"minWords":18,"placeholder":"VOZ 1: Cada cuerpo...\\nVOZ 2: Si algo te preocupa...","model":"Cada cuerpo cambia a su ritmo. Si algo te preocupa, consulta una fuente confiable y habla con una persona adulta.","rubric":["Tiene entre 18 y 24 palabras","Comunica un dato científico sin diagnosticar","Usa lenguaje respetuoso y orienta hacia una fuente confiable"]},"id":"s04-d5-taller-4"},{"fase":"aplicar","areas":["art"],"cnb":["art:3.1.2"],"ambito":"hacer","title":"Etapa 4: elige el fragmento · 2 min","prompt":"Escuchen dos fragmentos instrumentales de cinco segundos. Elijan A o B según su carácter e intensidad y escriban una oración: “Elegimos ___ porque ___”.","media":{"id":"s04-d5-taller-fragmentos","kind":"audio","title":"Dos fragmentos para la escena","duration":12,"alt":"Fragmento A: marimba instrumental tranquila y suave. Fragmento B: percusión instrumental festiva de intensidad moderada.","brief":"Audio de 12 s, sin voces ni marcas. Fragmento A: 5 s de marimba instrumental original o de dominio público, tempo lento, carácter tranquilo e intensidad suave. Pausa de 1 s. Fragmento B: 5 s de percusión instrumental original o de dominio público, tempo moderado, carácter festivo e intensidad moderada. Cierre con 1 s de silencio. Ambos fragmentos deben oírse con claridad a volumen moderado. Accesibilidad: transcripcion del contenido sonoro y guion exacto de las voces, si las hay."},"type":"project","props":{"goal":"Valorar música breve y elegir la que apoye mejor la campaña.","steps":[{"title":"Comparen","detail":"Identifiquen el carácter y la intensidad de A y B; no hace falta describir otros elementos."},{"title":"Decidan","detail":"Escojan un fragmento y anoten una razón de una sola oración vinculada con el mensaje, el respeto o la claridad de las voces."}],"evidence":"Fragmento A o B seleccionado y una oración que justifica la decisión con un criterio musical aprendido.","rubric":["La razón usa carácter, intensidad o volumen","La elección apoya el mensaje y permite escuchar las voces"]},"id":"s04-d5-taller-5"},{"fase":"aplicar","areas":["cnt","l1"],"cnb":["cnt:3.3.1","l1:5.1.8"],"ambito":"conocer","title":"Control de concisión · 1 min","prompt":"Antes de ensayar, ¿qué debe conservar el mensaje breve?","type":"choice","props":{"options":[{"id":"a","text":"Dejar la duda, un dato, una fuente confiable y la orientación final"},{"id":"b","text":"Agregar otros tres cambios corporales y dos consejos"},{"id":"c","text":"Quitar la fuente y sustituirla por “lo vi en internet”"}],"correct":["a"]},"id":"s04-d5-taller-6"},{"fase":"aplicar","areas":["l1","fc","art"],"cnb":["l1:5.1.8","fc:3.1.1","art:3.1.2"],"ambito":"hacer","title":"Etapa 5: ensayo breve · 1 min","prompt":"Hagan una lectura en voz alta de 30 segundos: reproduzcan solo cinco segundos del fragmento elegido, deténganlo y representen los dos roles; después intercambien una observación.","type":"project","props":{"goal":"Ensayar la escena informativa con la música elegida, voz clara y escucha mutua.","steps":[{"title":"Inicien","detail":"Usen el fragmento seleccionado durante 5 segundos y deténganlo antes de hablar para que no tape las voces."},{"title":"Lean y comprueben","detail":"Representen la escena una vez; confirmen que se entiendan la idea central y la orientación final, y que el carácter musical apoye el mensaje."}],"evidence":"Una lectura completa que usa cinco segundos del fragmento elegido y una observación oral.","rubric":["Ambas personas cumplen el rol acordado","La música se detiene antes de las voces","El mensaje se entiende sin hablar deprisa"]},"id":"s04-d5-taller-7"},{"fase":"aplicar","areas":["cnt","l1","fc"],"cnb":["cnt:3.3.1","l1:5.1.8","fc:3.1.1"],"ambito":"convivir","title":"Etapa 6: revisión entre pares · 2 min","prompt":"Otra pareja escucha la escena y marca solo dos criterios: exactitud científica y lenguaje respetuoso.","type":"project","props":{"goal":"Revisar la campaña informativa antes de presentarla.","steps":[{"title":"Ciencia","detail":"Marca sí o por revisar: el dato es científicamente correcto, tiene fuente confiable y no diagnostica."},{"title":"Respeto","detail":"Marca sí o por revisar: reconoce variaciones normales y evita burlas, culpa y estereotipos."}],"evidence":"Dos marcas y una observación breve sobre uno de los criterios.","rubric":["La revisión comprueba exactitud científica","La revisión comprueba respeto"]},"id":"s04-d5-taller-8"},{"fase":"aplicar","areas":["cnt","l1"],"cnb":["cnt:3.3.1","l1:5.1.8"],"ambito":"hacer","title":"Etapa 7: revisión dirigida · 1 min","prompt":"Corrige una sola frase según la observación recibida. Conserva el mensaje entre 18 y 24 palabras y encierra el cambio.","type":"short-answer","props":{"minWords":18,"placeholder":"Versión corregida del mensaje...","model":"Cada cuerpo cambia a su ritmo. Si algo te preocupa, consulta una fuente confiable y habla con una persona adulta.","rubric":["La corrección dirigida responde a la observación","Mantiene exactitud científica y respeto","Conserva la fuente confiable"]},"id":"s04-d5-taller-9"},{"fase":"aplicar","areas":["cnt","l1","fc"],"cnb":["cnt:3.3.1","l1:5.1.8","fc:3.1.1"],"ambito":"hacer","title":"Etapa 8: presentación final · 1 min","prompt":"Representen o lean la escena final de 30 segundos con los dos roles acordados.","type":"project","props":{"goal":"Presentar una escena dramática informativa breve y revisada.","steps":[{"title":"Presenten","detail":"Una voz plantea la duda y la otra comunica el dato, la fuente y la acción de cuidado."},{"title":"Entreguen","detail":"Junten el mensaje corregido, las dos marcas de revisión y la razón de la elección musical."}],"evidence":"Campaña informativa presentada y producto breve revisado.","rubric":["Mantiene exactitud científica y fuente confiable","Usa lenguaje respetuoso","Ambas personas participan en la escena"]},"id":"s04-d5-taller-10"},{"fase":"reflexionar","areas":["cnt","l1","fc","art"],"cnb":["cnt:3.3.1","l1:5.1.8","fc:3.1.1","art:3.1.2"],"ambito":"ser","prompt":"Cierre · 1 min. Revisa tu aporte y elige un compromiso para comunicar cuidado.","type":"reflection","props":{"statements":["Comprobé la ciencia","Usé lenguaje respetuoso","Escuché al equipo","Mejoré el producto después de revisarlo"],"commitments":["Consultaré una fuente confiable antes de compartir información de salud","No haré bromas sobre los cambios del cuerpo","Pediré ayuda adulta o profesional ante una preocupación de salud"]},"id":"s04-d5-taller-11"}]}},{"missionId":"s04","version":"cnb-sexto-1566c94b829d7f51","lesson":{"id":"s04-cnt-1","title":"Estructura del aparato reproductor masculino","icon":"ScanLine","minutes":14,"gancho":"Para entender cómo funciona una parte del cuerpo, conviene saber dónde está, qué hace y qué recorrido sigue.","objetivos":["Explicar la ubicación, la función y el recorrido de las partes del aparato reproductor masculino"],"resumen":["Los testículos forman los espermatozoides.","El epidídimo los guarda por un tiempo y el conducto deferente los transporta.","Las vesículas seminales y la próstata aportan líquidos; la uretra atraviesa el pene y conduce el semen al exterior."],"media":{"id":"s04-cnt-1-estructura","kind":"diagram","title":"Aparato reproductor masculino","aspect":"4:3","alt":"Diagrama anatómico esquemático y no explícito con las estructuras internas rotuladas.","brief":"Diagrama anatómico educativo 1200x900, vista lateral esquemática y no explícita. Rotular testículos, epidídimo, conducto deferente, vesículas seminales, próstata, uretra y pene; usar flechas para el recorrido sin representar actividad sexual. Texto grande, alto contraste, patrón además de color y descripción lineal accesible."},"steps":[{"fase":"explorar","areas":["cnt"],"cnb":["cnt:3.1.1"],"prompt":"Hoy estudiarás el aparato reproductor masculino con lenguaje científico, como cualquier otra parte del cuerpo.","type":"explain","props":{"icon":"Route","body":"Cada parte tiene una ubicación y una función dentro de un recorrido. Conocer los nombres correctos te ayuda a entender tu cuerpo, a cuidarlo y a hablar de él con respeto."},"id":"s04-cnt-1-1"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:3.1.1"],"title":"Partes y funciones","prompt":"Lee qué hace cada parte. Fíjate en el orden: así se entiende el recorrido.","type":"explain","props":{"icon":"ListTree","body":"**Testículos:** forman los espermatozoides. **Epidídimo:** allí maduran y se guardan por un tiempo. **Conducto deferente:** los transporta. **Vesículas seminales y próstata:** aportan líquidos. **Uretra:** es el conducto de salida que atraviesa el **pene**."},"id":"s04-cnt-1-2"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:3.1.1"],"title":"El recorrido paso a paso","prompt":"Sigue el recorrido de las células reproductoras, desde donde se forman hasta la salida.","type":"worked-example","props":{"icon":"MapPinned","problem":"¿Qué recorrido siguen las células reproductoras masculinas?","steps":[{"text":"Se forman en los testículos y pasan al epidídimo."},{"text":"Viajan por el conducto deferente; las vesículas seminales y la próstata aportan líquidos."},{"text":"El semen pasa por la uretra, que atraviesa el pene, hacia el exterior."}],"answer":"Testículos → epidídimo → conducto deferente → líquidos de las glándulas → uretra en el pene."},"id":"s04-cnt-1-3"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:3.1.1"],"prompt":"Ordena el recorrido, desde donde se forman los espermatozoides hasta la salida. Si lo necesitas, pide una pista.","hint":"Empieza donde se forman los espermatozoides y termina en el conducto de salida.","explain":"Las glándulas aportan líquidos antes de que el semen recorra la uretra.","type":"order","props":{"labels":{"start":"Inicio","end":"Salida"},"items":[{"id":"a","text":"Testículos: formación"},{"id":"b","text":"Epidídimo: maduración y almacenamiento"},{"id":"c","text":"Conducto deferente: transporte"},{"id":"d","text":"Vesículas seminales y próstata: líquidos"},{"id":"e","text":"Uretra a través del pene: salida"}]},"id":"s04-cnt-1-4"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:3.1.1"],"prompt":"Une cada parte con su función.","hint":"Distingue formación, almacenamiento, transporte, aporte de líquidos y salida.","explain":"Cada pareja te ayuda a reconstruir el recorrido.","type":"match","props":{"pairs":[{"id":"a","left":"Testículos y epidídimo","right":"Formación, maduración y almacenamiento por un tiempo"},{"id":"b","left":"Conducto deferente","right":"Transporte"},{"id":"c","left":"Vesículas seminales y próstata","right":"Aporte de líquidos"},{"id":"d","left":"Uretra y pene","right":"Conducto y estructura de salida"}]},"id":"s04-cnt-1-5"},{"fase":"aplicar","areas":["cnt"],"cnb":["cnt:3.1.1"],"title":"Ahora hazlo tú","prompt":"Explica con tus palabras el recorrido completo: qué hace cada parte y en qué orden participa.","type":"short-answer","props":{"minWords":24,"placeholder":"El recorrido empieza en…","model":"Los testículos forman las células reproductoras; el epidídimo las guarda; el conducto deferente las transporta; las vesículas seminales y la próstata aportan líquidos; y la uretra atraviesa el pene hacia el exterior.","rubric":["Nombré todas las estructuras","Relacioné la función con la ubicación","Ordené el recorrido"]},"id":"s04-cnt-1-6"},{"fase":"aplicar","areas":["cnt"],"cnb":["cnt:3.1.1"],"prompt":"¿Qué secuencia describe bien el recorrido por testículos, epidídimo, conducto deferente, vesículas seminales, próstata, uretra y pene?","type":"choice","props":{"options":[{"id":"a","text":"Formación en los testículos y paso al epidídimo; transporte; líquidos de las glándulas; uretra a través del pene"},{"id":"b","text":"Uretra; testículos; epidídimo; sin glándulas"},{"id":"c","text":"La próstata forma todos los espermatozoides"}],"correct":["a"]},"id":"s04-cnt-1-7"},{"fase":"comprobar","areas":["cnt"],"cnb":["cnt:3.1.1"],"prompt":"¿Qué explicación de la función de cada parte es correcta?","type":"choice","props":{"options":[{"id":"a","text":"Los testículos forman; el epidídimo almacena; el conducto deferente transporta; las vesículas seminales y la próstata aportan líquidos; la uretra atraviesa el pene"},{"id":"b","text":"El pene forma espermatozoides y la uretra los almacena"},{"id":"c","text":"Todas las partes cumplen la misma función"}],"correct":["a"]},"id":"s04-cnt-1-8"},{"fase":"comprobar","areas":["cnt"],"cnb":["cnt:3.1.1"],"prompt":"Lee cada frase sobre la función y el recorrido de estas partes, y decide si es verdadera o falsa.","type":"true-false","props":{"statements":[{"text":"El epidídimo participa en la maduración y el almacenamiento de los espermatozoides que se forman en los testículos.","answer":true},{"text":"Las vesículas seminales y la próstata aportan líquidos al recorrido que viene del conducto deferente.","answer":true},{"text":"La uretra no tiene relación con el pene.","answer":false}]},"id":"s04-cnt-1-9"}],"kind":"materia","area":"cnt","day":1}},{"missionId":"s04","version":"cnb-sexto-2373eafa2dfaac6a","lesson":{"id":"s04-ef-1","title":"Lanzar lejos, alto y con puntería","icon":"Target","minutes":15,"gancho":"Para lanzar una bolsita de frijol dentro de un canasto a 2 pasos o a 8 pasos, ¿haces el mismo movimiento?","objetivos":["Ejecutar lanzamientos por encima del hombro con control, ajuste y seguridad"],"resumen":["Un objeto de mediano peso (pelota de trapo, bolsita de arena o de frijol bien cerrada) necesita la fuerza de todo el cuerpo, no solo del brazo.","Técnica por encima del hombro: de lado a la meta, pie contrario al brazo que lanza adelante; el peso pasa del pie de atrás al de adelante, gira el tronco, el codo sube a la altura del hombro y el brazo sigue el movimiento al soltar.","Para llegar más lejos: más impulso de piernas y tronco y salida en diagonal hacia arriba. Para más altura: salida más vertical. Para puntería de cerca: menos fuerza y mirada fija en la meta.","Seguridad: lanza solo cuando no haya nadie en la dirección del lanzamiento y recoge los objetos todos juntos, cuando se dé la señal."],"media":{"id":"s04-ef-1-tecnica","kind":"video","title":"Técnica del lanzamiento por encima del hombro","aspect":"9:16","duration":50,"alt":"Una niña diestra se pone de lado, adelanta el pie izquierdo, lleva el brazo atrás, pasa el peso adelante girando el tronco y lanza una pelota de trapo que vuela en diagonal hacia un canasto.","brief":"Video vertical de 50 s en un campo o patio. Una niña diestra (ropa deportiva, rostro no protagonista) lanza una pelota de trapo o bolsita de arena: vista lateral en cámara lenta con 5 rótulos numerados: \\"1. De lado\\", \\"2. Pie contrario adelante\\", \\"3. Brazo atrás, codo alto\\", \\"4. Peso adelante y giro de tronco\\", \\"5. Suelta y sigue el movimiento\\". Luego tres lanzamientos a canastos a 2, 4 y 6 pasos, con una línea punteada que muestra la trayectoria (más alta y larga para el más lejano). Repetición con un niño zurdo (pie derecho adelante). Aviso \\"Nadie en la zona de lanzamiento\\". Accesibilidad: subtitulos completos para toda voz y transcripcion audiovisual; rotulos grandes, legibles y de alto contraste."},"steps":[{"fase":"explorar","areas":["ef"],"cnb":["ef:2.1.2"],"title":"Idea central","prompt":"Cuidarse al lanzar significa usar todo el cuerpo, ajustar la fuerza y despejar la zona.","type":"explain","props":{"icon":"BookOpenCheck","body":"Un objeto de mediano peso (pelota de trapo, bolsita de arena o de frijol bien cerrada) necesita la fuerza de todo el cuerpo, no solo del brazo."},"id":"s04-ef-1-1"},{"fase":"construir","areas":["ef"],"cnb":["ef:2.1.2"],"ambito":"conocer","prompt":"En el video, compara un lanzamiento hecho solo con el brazo y otro con paso y giro del cuerpo. ¿Cuál llega más lejos?","explain":"Llega más lejos cuando usas **todo el cuerpo**: piernas, tronco y brazo trabajan en cadena. El brazo solo tiene poca fuerza.","type":"choice","props":{"options":[{"id":"a","text":"Solo con el brazo","icon":"Hand","feedback":"El brazo solo aporta poca fuerza: le falta el impulso de las piernas y del tronco."},{"id":"b","text":"Con el paso y el giro del cuerpo","icon":"RotateCw"},{"id":"c","text":"Llega igual de las dos formas","icon":"Minus","feedback":"Repite la prueba y fíjate bien: la diferencia suele ser grande."}],"correct":["b"]},"id":"s04-ef-1-2"},{"fase":"construir","areas":["ef"],"cnb":["ef:2.1.2"],"ambito":"hacer","title":"La técnica en cinco pasos","prompt":"Mira el video y toca cada paso. Si eres **zurda o zurdo**, cambia los lados: pie **derecho** adelante.","type":"explain","props":{"icon":"Target","body":"El lanzamiento es una **cadena**: la fuerza nace en las piernas, pasa por el tronco y sale por el brazo.","reveal":[{"icon":"PersonStanding","front":"1. De lado","back":"Ponte **de lado** a la meta, con el hombro contrario al brazo que lanza apuntando hacia ella."},{"icon":"Footprints","front":"2. Pie contrario adelante","back":"Si lanzas con la derecha, el pie **izquierdo** va adelante (y al revés). Así el cuerpo puede girar."},{"icon":"ArrowUp","front":"3. Brazo atrás, codo alto","back":"Lleva el objeto atrás con el **codo a la altura del hombro** o más arriba."},{"icon":"RotateCw","front":"4. Peso adelante y giro","back":"Pasa el peso del pie de atrás al de adelante y **gira el tronco** hacia la meta."},{"icon":"Target","front":"5. Suelta y sigue","back":"Suelta el objeto adelante y deja que el brazo **siga el movimiento** hacia abajo, cruzando el cuerpo. Mirada en la meta."}]},"id":"s04-ef-1-3"},{"fase":"construir","areas":["ef"],"cnb":["ef:2.1.2"],"ambito":"conocer","title":"Distancia, altura y puntería","prompt":"No todos los lanzamientos buscan lo mismo. Ajusta **dos cosas**: la **fuerza** y la **dirección de salida**. Toca cada tarjeta.","media":{"id":"s04-ef-1-trayectorias","kind":"diagram","title":"Tres trayectorias","aspect":"16:9","alt":"Una niña de perfil lanza tres veces: una curva baja y corta hacia un canasto cercano, una curva en diagonal que llega lejos y una curva muy alta que pasa sobre una cuerda y cae en un canasto.","brief":"Diagrama lateral sobre fondo claro con suelo marcado en pasos (1 a 8). Desde la mano de una niña salen tres trayectorias curvas punteadas de colores: (1) verde, corta y baja, termina en un canasto a 2 pasos: \\"puntería, poca fuerza\\"; (2) azul, salida en diagonal, llega a 7 pasos: \\"lejos, salida diagonal\\"; (3) naranja, salida casi vertical, pasa sobre una cuerda alta y cae en un canasto a 3 pasos: \\"alto\\". Flechas pequeñas indican el ángulo de salida. Rótulos grandes. Dimensiones: 1600x900."},"type":"explain","props":{"icon":"Route","body":"La trayectoria del objeto es una **curva**: sube, llega a un punto alto y baja.","reveal":[{"icon":"MoveHorizontal","front":"Lejos","back":"Mucha fuerza de piernas y tronco, y salida **en diagonal hacia arriba** (a medio camino entre horizontal y vertical)."},{"icon":"ArrowUp","front":"Alto","back":"Salida más **vertical**, para pasar por encima de un obstáculo o caer dentro de un recipiente alto."},{"icon":"Target","front":"Puntería de cerca","back":"**Menos fuerza**, movimiento más corto y controlado, mirada fija en el centro de la meta."},{"icon":"Scale","front":"Mediano peso","back":"Un objeto más pesado necesita **más impulso** del cuerpo y llega menos lejos con la misma fuerza."}]},"id":"s04-ef-1-4"},{"fase":"construir","areas":["ef"],"cnb":["ef:2.1.2"],"ambito":"hacer","title":"Ejemplo resuelto: tiro a la troje","prompt":"Mira cómo Lucía ajusta su lanzamiento para tres distancias.","type":"worked-example","props":{"icon":"ShoppingBasket","problem":"Lucía lanza una bolsita de frijol a un canasto grande colocado a **2**, **4** y **6** pasos. En los primeros intentos, a 2 pasos se le pasa y a 6 no llega.","steps":[{"text":"**A 2 pasos** se le pasa porque usa demasiada fuerza. Acorta el movimiento: brazo menos atrás y casi sin giro de tronco.","why":"De cerca importa más el control que la fuerza."},{"text":"**A 4 pasos** usa el paso adelante y un giro medio; la bolsita sale en diagonal suave."},{"text":"**A 6 pasos** no llegaba porque lanzaba \\"plano\\". Ahora usa la técnica completa: pie contrario adelante, peso atrás → adelante, giro fuerte y salida **en diagonal hacia arriba**.","why":"Una salida más alta da más tiempo de vuelo para recorrer más distancia."},{"text":"Registra cada intento con una marca de acierto o todavía no; así puede comparar sin hacer una gráfica."}],"answer":"Lucía ajusta la **fuerza** (menos de cerca, más de lejos) y la **dirección de salida** (más diagonal para distancias largas).","tip":"Cambia una sola cosa por intento: así sabes qué funcionó."},"id":"s04-ef-1-5"},{"fase":"construir","areas":["ef"],"cnb":["ef:2.1.2"],"ambito":"hacer","prompt":"Ordena los pasos del lanzamiento por encima del hombro.","hint":"Primero la posición, luego el brazo, después el peso y el giro, y al final soltar.","explain":"De lado → pie contrario adelante → brazo atrás con codo alto → peso adelante y giro → soltar y seguir el movimiento.","type":"order","props":{"items":[{"id":"a","text":"Ponerse de lado a la meta"},{"id":"b","text":"Adelantar el pie contrario al brazo que lanza"},{"id":"c","text":"Llevar el brazo atrás con el codo alto"},{"id":"d","text":"Pasar el peso adelante y girar el tronco"},{"id":"e","text":"Soltar y seguir el movimiento con el brazo"}],"labels":{"start":"Primero","end":"Al final"}},"id":"s04-ef-1-6"},{"fase":"aplicar","areas":["ef"],"cnb":["ef:2.1.2"],"ambito":"hacer","prompt":"¡Tiro a la troje! Usa una bolsita bien cerrada o una pelota de trapo y un canasto como meta. **Calentamiento:** rota hombros, brazos y muñecas sin lanzar. **Prueba:** haz **8 lanzamientos en total**: 2 cercanos con poca fuerza, 3 lejanos con paso y giro, y 3 altos hacia el canasto sin usar obstáculos. Tu pareja anota una marca por intento y encierra los aciertos. **Seguridad:** nadie frente a ti y todos recogen al recibir la señal. **Poco espacio:** acerca la meta y usa una bola de papel. **Adaptación:** lanza sentado o acerca la meta. **Vuelta a la calma:** respira, estira brazos y hombros y toma agua.","type":"pulse-lab","props":{"seconds":15,"rounds":[{"label":"En reposo"},{"label":"Después del calentamiento","exercise":{"name":"Movilidad de hombros y muñecas","icon":"RotateCw","seconds":30}},{"label":"Después de los 8 lanzamientos","exercise":{"name":"Prueba breve con registro de marcas","icon":"Target","seconds":120}}]},"id":"s04-ef-1-7"},{"fase":"aplicar","areas":["ef"],"cnb":["ef:2.1.2"],"ambito":"hacer","prompt":"Carlos es diestro. Al lanzar adelanta el pie **derecho** y la pelota no llega lejos. ¿Qué debe corregir?","explain":"Con el pie del mismo lado adelante, el tronco no puede girar. Debe adelantar el pie **izquierdo** (contrario al brazo que lanza).","type":"choice","props":{"options":[{"id":"a","text":"Adelantar el pie izquierdo, contrario al brazo que lanza"},{"id":"b","text":"Lanzar con los dos pies juntos","feedback":"Con los pies juntos no hay paso ni transferencia de peso."},{"id":"c","text":"Doblar menos el codo y lanzar solo con la muñeca","feedback":"Así tendría aún menos fuerza."}],"correct":["a"]},"id":"s04-ef-1-8"},{"fase":"comprobar","areas":["ef"],"cnb":["ef:2.1.2"],"prompt":"Quieres que una bolsita de arena llegue **lo más lejos posible**. ¿Qué haces?","type":"choice","props":{"options":[{"id":"a","text":"Uso todo el cuerpo y la lanzo en diagonal hacia arriba"},{"id":"b","text":"La lanzo solo con la muñeca, bien recta hacia abajo"},{"id":"c","text":"La lanzo totalmente hacia arriba"}],"correct":["a"]},"id":"s04-ef-1-9"},{"fase":"comprobar","areas":["ef"],"cnb":["ef:2.1.2"],"prompt":"¿Verdadero o falso?","type":"true-false","props":{"statements":[{"text":"Para lanzar cerca y con puntería se usa menos fuerza y un movimiento más corto.","answer":true},{"text":"Se puede lanzar aunque haya compañeros en la dirección del lanzamiento, si se lanza suave.","answer":false,"why":"Nunca se lanza si hay alguien en la dirección del lanzamiento."},{"text":"En el lanzamiento, el peso pasa del pie de atrás al pie de adelante.","answer":true}]},"id":"s04-ef-1-10"}],"kind":"materia","area":"ef","day":2}}]'),o={mission:a,lessons:e};export{o as default,e as lessons,a as mission};
